// ── FIDS BUILD ID — check this in DevTools console to confirm which version is live
const FIDS_BUILD = 'v218.84'; // legacy label for the console banner ONLY.
// CACHE TOKENS MUST USE FIDS_BUILD_TAG: this constant froze at v218.84 months
// ago, so every 'build-tied' wordmark URL was IDENTICAL across hundreds of
// deploys — a browser that cached one bad response (deploy-window 404) kept
// it forever and fell back to the clipped text name (the immortal 'jetBlu').
console.log('%c[FIDS BUILD ' + FIDS_BUILD + '] loaded ' + new Date().toISOString(), 'background:#0a0; color:#fff; font-weight:bold; padding:3px 8px; font-size:13px;');

// ── FEATURE FLAGS ────────────────────────────────────────────────────────
// GATE_LAYOUT_V2 = three-column gate screen (aircraft | media | map) with
// the always-present bottom bar that grows when a message is active.
// Toggle at runtime: localStorage.setItem('fids_gate_layout_v2', 'on'|'off')
// Default: ON. Roll back instantly by setting to 'off' and refreshing.
(function(){
  // v22356: the 'off' rollback is RETIRED. A stale machine-local flag
  // resurrected the unmaintained legacy gate on Nick's admin browser
  // ('looks like an old screen just crept up') — the v2 gate is the only
  // maintained layout and is now unconditional. The old flag is cleared
  // so no display can ever trip on it again.
  window.GATE_LAYOUT_V2 = true;
  try {
    if (localStorage.getItem('fids_gate_layout_v2') === 'off') {
      console.warn('[FIDS] Ignoring stale fids_gate_layout_v2=off (legacy layout retired)');
      localStorage.removeItem('fids_gate_layout_v2');
    }
  } catch(e) {}
  console.log('[FIDS] GATE_LAYOUT_V2 =', window.GATE_LAYOUT_V2);
})();

// ── NULL-SAFE ELEMENT HELPER (some controls only exist on certain pages) ─
function $el(id) { return document.getElementById(id) || {classList:{toggle:()=>{},add:()=>{},remove:()=>{}},textContent:'',style:{}}; }

// ════════════════════════════════════════════════════════════════════
// AIRPORT CONFIGURATION RESOLVER (Phase 2 — added 2026-05)
//
// Loads per-airport branding (display name, logo, logo position, theme)
// with this resolution order:
//   1. localStorage 'fids_airport_override_XXX'   (per-browser override wins)
//   2. KV via Worker API /api/airport-config/XXX  (per-airport central default)
//   3. Built-in fallback                           (current hardcoded behavior)
//
// Also loads per-airport airline-logo overrides — same resolution chain
// applies but only for airlines that have an explicit override registered.
// Anything not in the override list falls through to global LOCAL_LOGOS as
// before, so the existing logo system keeps working unchanged.
//
// All of this is non-blocking — render functions can call getAirportConfig()
// synchronously and get whatever's in cache. The first network fetch on page
// load may return null briefly; once resolved it triggers a one-time refresh
// of the views via window.dispatchEvent('fids-airport-config-ready').
// ════════════════════════════════════════════════════════════════════

const FIDS_API_BASE = 'https://fids-proxy.n-leblanc1984.workers.dev';

// Gate screen day/night ('light'/'dark'). Priority: an explicit manual choice
// (localStorage fids_console_theme) wins; then a PINNED URL theme (kiosk/stream,
// e.g. ?theme=mist) forces the LIGHT gate so it matches the light board instead
// of following time-of-day — that mismatch made the gate go dark at night while
// the board stayed mist; then, otherwise, time-of-day (light 06:00–19:00).
function _gateDayNightTheme() {
  try { var _t = localStorage.getItem('fids_console_theme'); if (_t === 'light' || _t === 'dark') return _t; } catch (e) {}
  try {
    var _u = new URLSearchParams(window.location.search).get('theme');
    if (_u && /^(mist|tus-teal|tus-teal-deep|light|day)$/i.test(_u.trim())) return 'light';
  } catch (e) {}
  var _h = new Date().getHours();
  return (_h >= 6 && _h < 19) ? 'light' : 'dark';
}

// In-memory cache, populated lazily. Keys are normalized airport codes.
const _airportConfigCache = {};
const _airlineOverrideCache = {};
let _airportConfigInflight = {};   // track in-progress fetches to avoid duplicates
let _airlineOverrideInflight = {};

function _normAirportCode(code) {
  return (code || '').toString().toUpperCase().trim().slice(0, 4);
}

// Synchronous read — returns whatever's cached/local right now, or null.
// Render code uses this; it never blocks the screen.
function getAirportConfig(code) {
  const norm = _normAirportCode(code);
  if (!norm) return null;
  // 1. Per-browser override (always wins, allows screens to override centrally-set config)
  try {
    const localRaw = localStorage.getItem('fids_airport_override_' + norm);
    if (localRaw) {
      const parsed = JSON.parse(localRaw);
      if (parsed && typeof parsed === 'object') {
        return { ...parsed, _source: 'local' };
      }
    }
  } catch (e) {}
  // 2. KV-backed cache (populated by loadAirportConfig)
  if (_airportConfigCache[norm]) {
    return { ..._airportConfigCache[norm], _source: 'kv' };
  }
  return null;
}

// Async loader — fetches from Worker, caches in memory.
// Returns a promise that resolves to the config object (or null on 404/error).
// Safe to call multiple times; concurrent calls share one network request.
async function loadAirportConfig(code) {
  const norm = _normAirportCode(code);
  if (!norm) return null;
  // Already cached?
  if (_airportConfigCache[norm]) return _airportConfigCache[norm];
  // Already fetching?
  if (_airportConfigInflight[norm]) return _airportConfigInflight[norm];
  // Cache "no config" results too — without this, every render() call
  // re-fetches the 404 endpoint, flooding the console with errors and
  // wasting requests. Once we know an airport has no config, remember it.
  if (norm in _airportConfigCache) return _airportConfigCache[norm];
  // Start fetch
  _airportConfigInflight[norm] = (async () => {
    try {
      const res = await fetch(FIDS_API_BASE + '/api/airport-config/' + norm, { cache: 'no-cache' });
      if (res.status === 404) {
        _airportConfigCache[norm] = null;          // remember: no config
        return null;
      }
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const cfg = await res.json();
      _airportConfigCache[norm] = cfg;
      try { window.dispatchEvent(new CustomEvent('fids-airport-config-ready', { detail: { code: norm, config: cfg } })); } catch (e) {}
      return cfg;
    } catch (e) {
      console.warn('[FIDS] airport config load failed for ' + norm + ':', e.message);
      return null;
    } finally {
      delete _airportConfigInflight[norm];
    }
  })();
  return _airportConfigInflight[norm];
}

// Synchronous read of an airline-logo override for a given airport.
// Returns the override URL, or null if no override is registered.
function getAirlineLogoOverride(airportCode, airlineCode) {
  const ap = _normAirportCode(airportCode);
  const al = _normAirportCode(airlineCode);
  if (!ap || !al) return null;
  // Per-browser override first
  try {
    const localRaw = localStorage.getItem('fids_airline_override_' + ap + '_' + al);
    if (localRaw) {
      const parsed = JSON.parse(localRaw);
      if (parsed && parsed.url) return parsed.url;
    }
  } catch (e) {}
  // KV cache
  const overrides = _airlineOverrideCache[ap];
  if (overrides && overrides[al] && overrides[al].url) {
    return overrides[al].url;
  }
  return null;
}

// Async loader for the full set of airline overrides for an airport.
async function loadAirlineOverrides(airportCode) {
  const ap = _normAirportCode(airportCode);
  if (!ap) return {};
  if (_airlineOverrideCache[ap]) return _airlineOverrideCache[ap];
  if (_airlineOverrideInflight[ap]) return _airlineOverrideInflight[ap];
  _airlineOverrideInflight[ap] = (async () => {
    try {
      const res = await fetch(FIDS_API_BASE + '/api/airline-override/' + ap, { cache: 'no-cache' });
      if (!res.ok) return {};
      const body = await res.json();
      const overrides = body.overrides || {};
      _airlineOverrideCache[ap] = overrides;
      try { window.dispatchEvent(new CustomEvent('fids-airline-overrides-ready', { detail: { airport: ap, overrides } })); } catch (e) {}
      return overrides;
    } catch (e) {
      console.warn('[FIDS] airline overrides load failed for ' + ap + ':', e.message);
      _airlineOverrideCache[ap] = {};
      return {};
    } finally {
      delete _airlineOverrideInflight[ap];
    }
  })();
  return _airlineOverrideInflight[ap];
}

// One-stop kick-off — call once when the screen knows its airport code.
// Triggers both async loads in parallel; safe to call repeatedly.
function bootstrapAirportConfig(code) {
  const norm = _normAirportCode(code);
  if (!norm) return;
  loadAirportConfig(norm);
  loadAirlineOverrides(norm);
}

// Expose to window for admin UI + debugging from DevTools console
window.FIDS_AIRPORT = {
  get: getAirportConfig,
  load: loadAirportConfig,
  getAirlineLogo: getAirlineLogoOverride,
  loadAirlineOverrides: loadAirlineOverrides,
  bootstrap: bootstrapAirportConfig,
  apiBase: FIDS_API_BASE,
  _cache: _airportConfigCache,
  _airlineCache: _airlineOverrideCache
};


// ── FIDS_MEDIA: airline-keyed media config (videos, ads, photos) ──────
// Single global doc loaded from /api/media-config on boot. Admin writes
// via PUT, all clients read fresh via GET. Schema: { airlines: {AC: {videos:[],
// adImages:[]}, ...}, global: {...} }. Each video entry: {type:'playlist'|'video',
// id:string, label:string, lang:'en'|'fr'|'auto'}. Each adImage: {url, label, link}.
var _mediaCfgCache = null;
var _mediaCfgInflight = null;
async function loadMediaConfig(force) {
  if (!force && _mediaCfgCache) return _mediaCfgCache;
  if (_mediaCfgInflight) return _mediaCfgInflight;
  _mediaCfgInflight = (async () => {
    try {
      var res = await fetch(FIDS_API_BASE + '/api/media-config', { cache: 'no-cache' });
      if (!res.ok) {
        console.warn('[FIDS_MEDIA] load failed:', res.status);
        return { airlines: {}, global: {} };
      }
      var cfg = await res.json();
      _mediaCfgCache = cfg;
      try { window.dispatchEvent(new CustomEvent('fids-media-config-ready', { detail: cfg })); } catch (e) {}
      return cfg;
    } catch (e) {
      console.warn('[FIDS_MEDIA] load error:', e.message);
      return { airlines: {}, global: {} };
    } finally {
      _mediaCfgInflight = null;
    }
  })();
  return _mediaCfgInflight;
}

// Synchronous read for code paths that need media data NOW. Returns the
// cached config or null if not loaded yet. Callers should fall back to
// hardcoded defaults when this returns null.
function getMediaConfig() {
  return _mediaCfgCache;
}

// Convenience: get the videos list for an airline. Returns [] if none.
// Each entry has shape { type:'playlist'|'video', id:string, label, lang }.
function getAirlineVideos(airlineCode) {
  var cfg = _mediaCfgCache;
  if (!cfg || !cfg.airlines) return [];
  var al = String(airlineCode || '').toUpperCase();
  var entry = cfg.airlines[al];
  if (!entry || !Array.isArray(entry.videos)) return [];
  return entry.videos;
}

// Convenience: get the ad images list for an airline. Returns [] if none.
function getAirlineAdImages(airlineCode) {
  var cfg = _mediaCfgCache;
  if (!cfg || !cfg.airlines) return [];
  var al = String(airlineCode || '').toUpperCase();
  var entry = cfg.airlines[al];
  if (!entry || !Array.isArray(entry.adImages)) return [];
  return entry.adImages;
}

// v22839 — shared 401 rescue for admin writes: an expired 24h token made
// every save die with a bare 'Save failed: HTTP 401' (Nick hit it saving
// YHU info). Clear the stale token and pop the login modal so the path
// back is visible; the caller's form keeps its values.
function _fidsSaveAuthRescue(res) {
  if (!res || res.status !== 401) return false;
  try { sessionStorage.removeItem('fids_token'); sessionStorage.removeItem('fids_user'); } catch (e) {}
  try { if (typeof showLoginModal === 'function') showLoginModal(); } catch (e) {}
  return true;
}

// Admin-only write — caller must have a valid Bearer token in
// sessionStorage.fids_token. Returns { success, config } on success.
async function saveMediaConfig(cfg) {
  var token = sessionStorage.getItem('fids_token');
  if (!token) throw new Error('Not authenticated');
  var res = await fetch(FIDS_API_BASE + '/api/media-config', {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + token
    },
    body: JSON.stringify(cfg)
  });
  if (!res.ok) {
    if (_fidsSaveAuthRescue(res)) throw new Error('Your login expired — sign in, then save again');
    var err = '';
    try { err = (await res.json()).error || ''; } catch (e) {}
    throw new Error('Save failed: HTTP ' + res.status + (err ? ' — ' + err : ''));
  }
  var json = await res.json();
  // Update local cache immediately so reads see the new values without
  // waiting for the next loadMediaConfig() call.
  _mediaCfgCache = json.config;
  try { window.dispatchEvent(new CustomEvent('fids-media-config-ready', { detail: json.config })); } catch (e) {}
  return json;
}

window.FIDS_MEDIA = {
  load: loadMediaConfig,
  get: getMediaConfig,
  getAirlineVideos: getAirlineVideos,
  getAirlineAdImages: getAirlineAdImages,
  save: saveMediaConfig,
  // ── Library + Assignments (new) ──
  loadLibrary: loadMediaLibrary,
  getLibrary: getMediaLibrary,
  loadAssignments: loadMediaAssignments,
  getAssignments: getMediaAssignments,
  addYouTube: addYouTubeLibraryItem,
  uploadFile: uploadLibraryFile,
  updateItem: updateLibraryItem,
  deleteItem: deleteLibraryItem,
  saveAssignments: saveMediaAssignments,
  // Resolved view: returns library items currently assigned to an airline
  getAssignedVideosForAirline: getAssignedVideosForAirline,
  getAssignedImagesForAirline: getAssignedImagesForAirline,
  apiBase: FIDS_API_BASE
};


// ── Library + Assignments cache ──
var _mediaLibCache = null;
var _mediaLibInflight = null;
var _mediaAssignCache = null;
var _mediaAssignInflight = null;

async function loadMediaLibrary(force) {
  if (!force && _mediaLibCache) return _mediaLibCache;
  if (_mediaLibInflight) return _mediaLibInflight;
  _mediaLibInflight = (async () => {
    try {
      var res = await fetch(FIDS_API_BASE + '/api/media-library', { cache: 'no-cache' });
      if (!res.ok) return { items: [] };
      _mediaLibCache = await res.json();
      try { window.dispatchEvent(new CustomEvent('fids-media-library-ready', { detail: _mediaLibCache })); } catch (e) {}
      return _mediaLibCache;
    } catch (e) {
      console.warn('[FIDS_MEDIA] library load failed:', e.message);
      return { items: [] };
    } finally { _mediaLibInflight = null; }
  })();
  return _mediaLibInflight;
}
function getMediaLibrary() { return _mediaLibCache; }

async function loadMediaAssignments(force) {
  if (!force && _mediaAssignCache) return _mediaAssignCache;
  if (_mediaAssignInflight) return _mediaAssignInflight;
  _mediaAssignInflight = (async () => {
    try {
      var res = await fetch(FIDS_API_BASE + '/api/media-assignments', { cache: 'no-cache' });
      if (!res.ok) return { airlines: {} };
      _mediaAssignCache = await res.json();
      try { window.dispatchEvent(new CustomEvent('fids-media-assignments-ready', { detail: _mediaAssignCache })); } catch (e) {}
      return _mediaAssignCache;
    } catch (e) {
      console.warn('[FIDS_MEDIA] assignments load failed:', e.message);
      return { airlines: {} };
    } finally { _mediaAssignInflight = null; }
  })();
  return _mediaAssignInflight;
}
function getMediaAssignments() { return _mediaAssignCache; }

// Admin: add a YouTube ref to the library. Returns the new item.
async function addYouTubeLibraryItem(ytType, ytId, label) {
  var token = sessionStorage.getItem('fids_token');
  if (!token) throw new Error('Not authenticated');
  var res = await fetch(FIDS_API_BASE + '/api/media-library/youtube', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
    body: JSON.stringify({ ytType: ytType, ytId: ytId, label: label || '' })
  });
  if (!res.ok) {
    var err = ''; try { err = (await res.json()).error || ''; } catch (e) {}
    throw new Error('Add failed: HTTP ' + res.status + (err ? ' — ' + err : ''));
  }
  var json = await res.json();
  _mediaLibCache = json.library;
  return json.item;
}

// Admin: upload a binary file (video/image). file is a File or Blob.
async function uploadLibraryFile(file, label, category) {
  var token = sessionStorage.getItem('fids_token');
  if (!token) throw new Error('Not authenticated');
  var cat = (category && /^(ads|airport-logo|airline-logo|background)$/.test(category)) ? category : 'ads';
  var url = FIDS_API_BASE + '/api/media-library/upload'
    + '?label=' + encodeURIComponent(label || '')
    + '&category=' + encodeURIComponent(cat);
  var res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': file.type || 'application/octet-stream', 'Authorization': 'Bearer ' + token },
    body: file
  });
  if (!res.ok) {
    var err = ''; try { err = (await res.json()).error || ''; } catch (e) {}
    throw new Error('Upload failed: HTTP ' + res.status + (err ? ' — ' + err : ''));
  }
  var json = await res.json();
  _mediaLibCache = json.library;
  return json.item;
}

// Admin: update a library item's playback settings (loop, duration) or label.
// patch body: { label?, playback?: { loop, duration } }
async function updateLibraryItem(itemId, patch) {
  var token = sessionStorage.getItem('fids_token');
  if (!token) throw new Error('Not authenticated');
  var res = await fetch(FIDS_API_BASE + '/api/media-library/' + encodeURIComponent(itemId), {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
    body: JSON.stringify(patch || {})
  });
  if (!res.ok) {
    var err = ''; try { err = (await res.json()).error || ''; } catch (e) {}
    throw new Error('Update failed: HTTP ' + res.status + (err ? ' — ' + err : ''));
  }
  var json = await res.json();
  _mediaLibCache = json.library;
  return json.item;
}

// Admin: delete a library item by id.
async function deleteLibraryItem(itemId) {
  var token = sessionStorage.getItem('fids_token');
  if (!token) throw new Error('Not authenticated');
  var res = await fetch(FIDS_API_BASE + '/api/media-library/' + encodeURIComponent(itemId), {
    method: 'DELETE',
    headers: { 'Authorization': 'Bearer ' + token }
  });
  if (!res.ok) {
    var err = ''; try { err = (await res.json()).error || ''; } catch (e) {}
    throw new Error('Delete failed: HTTP ' + res.status + (err ? ' — ' + err : ''));
  }
  var json = await res.json();
  _mediaLibCache = json.library;
  return json;
}

// Admin: save the airline → item id assignments map.
async function saveMediaAssignments(cfg) {
  var token = sessionStorage.getItem('fids_token');
  if (!token) throw new Error('Not authenticated');
  var res = await fetch(FIDS_API_BASE + '/api/media-assignments', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
    body: JSON.stringify(cfg)
  });
  if (!res.ok) {
    if (_fidsSaveAuthRescue(res)) throw new Error('Your login expired — sign in, then save again');
    var err = ''; try { err = (await res.json()).error || ''; } catch (e) {}
    throw new Error('Save failed: HTTP ' + res.status + (err ? ' — ' + err : ''));
  }
  var json = await res.json();
  _mediaAssignCache = json.config;
  return json;
}

// ── Resolved-view helpers ──
// Look up the assignments for an airline, then resolve each id against
// the library to return full item objects. Returns [] if anything is
// unloaded or missing. The consumer code uses these instead of the raw
// caches so it doesn't have to know about ids.
function _resolveAssignedItems(airlineCode, slot) {
  if (!_mediaAssignCache || !_mediaLibCache) return [];
  var al = String(airlineCode || '').toUpperCase();
  var entry = _mediaAssignCache.airlines && _mediaAssignCache.airlines[al];
  if (!entry || !entry[slot]) return [];
  var ids = entry[slot].itemIds || [];
  if (!ids.length) return [];
  var items = _mediaLibCache.items || [];
  var out = [];
  ids.forEach(function(id) {
    var it = items.find(function(x) { return x.id === id; });
    if (it) out.push({ item: it, mode: entry[slot].mode || 'rotate', primaryId: entry[slot].primaryId || null });
  });
  return out;
}
function getAssignedVideosForAirline(code) { return _resolveAssignedItems(code, 'videos'); }
function getAssignedImagesForAirline(code) { return _resolveAssignedItems(code, 'images'); }

// Kick off a load on page boot — non-blocking, so the rest of the page
// can render with hardcoded defaults if the fetch is slow.
try { loadMediaConfig(); } catch (e) {}
try { loadMediaLibrary(); } catch (e) {}
try { loadMediaAssignments(); } catch (e) {}

// ── GATE OVERRIDE SYSTEM (localStorage-backed) ────────────────────────
var _GATE_OVERRIDES_KEY = 'fids_gate_overrides';
function getGateOverrides() {
  try { return JSON.parse(localStorage.getItem(_GATE_OVERRIDES_KEY) || '{}'); } catch(e) { return {}; }
}
function setGateOverrides(obj) {
  try { localStorage.setItem(_GATE_OVERRIDES_KEY, JSON.stringify(obj)); } catch(e) {}
}
function getOverrideForFlight(flightNum) {
  if (!flightNum) return null;
  var all = getGateOverrides();
  return all[flightNum.toUpperCase()] || null;
}

// ══════════════════════════════════════════════════════════════════════
// GATE CHANGE TRACKING
// ══════════════════════════════════════════════════════════════════════
// Stores per-flight gate history so we can detect when a flight moves to
// a different gate and surface that to passengers at the OLD gate.
//
// Structure (localStorage, 'fids_gate_history'):
//   { "AC8616": { currentGate:"F34", previousGate:"F98", changedAt:1234567890 } }
//
// The entry persists until the flight departs (we see status === 'departed'
// or the flight is no longer in the ADB response) or is superseded by a
// newer gate change. Supersession means: if F34 later becomes F52, the old
// entry (F98→F34) is replaced by (F34→F52) — the alert always reflects the
// LATEST move, and follows the passenger as they re-consult screens.
// ══════════════════════════════════════════════════════════════════════
var _GATE_HISTORY_KEY = 'fids_gate_history';

function getGateHistory() {
  try { return JSON.parse(localStorage.getItem(_GATE_HISTORY_KEY) || '{}'); } catch(e) { return {}; }
}
function setGateHistory(obj) {
  try { localStorage.setItem(_GATE_HISTORY_KEY, JSON.stringify(obj)); } catch(e) {}
}

// Call this on every FIDS data refresh with the full set of flights.
// Detects gate changes by comparing each flight's current gate against
// its last-known gate, and records the change in history.
function trackGateChanges(flightsArr) {
  if (!flightsArr || !flightsArr.length) return;
  var hist = getGateHistory();
  var changed = false;
  var now = Date.now();
  var activeFlights = {};

  flightsArr.forEach(function(f) {
    if (!f.flight) return;
    var key = f.flight.toUpperCase();
    activeFlights[key] = true;
    var curGate = (f.gate || '').trim();
    if (!curGate) return;

    var entry = hist[key];

    // Flight has departed — remove any gate-change record.
    if (f.status === 'departed' || f.status === 'cancelled') {
      if (entry) { delete hist[key]; changed = true; }
      return;
    }

    // No history: first time we've seen this flight — just record current gate.
    if (!entry) {
      hist[key] = { currentGate: curGate, changedAt: 0 };
      changed = true;
      return;
    }

    // Gate has changed since last observation.
    if (entry.currentGate !== curGate) {
      hist[key] = {
        currentGate: curGate,
        previousGate: entry.currentGate,
        changedAt: now
      };
      changed = true;
      console.log('[FIDS] Gate change:', key, entry.currentGate, '→', curGate);
    }
  });

  // Purge records for flights no longer active (departed, cancelled, or
  // dropped from the FIDS feed).
  Object.keys(hist).forEach(function(k) {
    if (!activeFlights[k]) { delete hist[k]; changed = true; }
  });

  if (changed) setGateHistory(hist);
}

// Is this screen (identified by its subScreenVal) watching a gate that a
// flight has moved AWAY from? If yes, we need to show the redirect banner.
function getInboundGateRedirect(gateNumber) {
  if (!gateNumber) return null;
  var hist = getGateHistory();
  var match = null;
  Object.keys(hist).forEach(function(k) {
    var e = hist[k];
    if (e && e.previousGate === gateNumber && e.currentGate && e.changedAt) {
      // Only the most recent move wins
      if (!match || e.changedAt > match.changedAt) {
        match = { flight: k, fromGate: e.previousGate, toGate: e.currentGate, changedAt: e.changedAt };
      }
    }
  });
  return match;
}

// ══════════════════════════════════════════════════════════════════════
// AIRCRAFT-PENDING RETRY
// ══════════════════════════════════════════════════════════════════════
// When loadFlight() returns without a reg (aircraft not yet assigned to
// the flight), we retry periodically. ADB will eventually pick up the
// registration when operations commits to an airframe, and the screen
// will then populate automatically.
// ══════════════════════════════════════════════════════════════════════
var _acPendingRetries = {}; // flight → timer id

function scheduleAircraftPendingRetry(flightNumber, airportIata) {
  if (!flightNumber) return;
  if (_acPendingRetries[flightNumber]) return; // already scheduled
  _acPendingRetries[flightNumber] = setTimeout(function() {
    delete _acPendingRetries[flightNumber];
    var cf = window._gateCurrentFlight;
    if (!cf || cf.flight !== flightNumber) return; // flight changed, abort
    // Any displayed reg aborts the retry (including an "expected" history
    // tail): the retry force-rebuilds the whole gate, which restarted the
    // weather/takeover slides every 3 minutes on expected-reg gates (Nick:
    // 'something refreshes... reboot'). Expected → confirmed upgrades ride
    // the NATURAL poll instead — each board refresh rebuilds the flight and
    // re-runs enrichment past the 60s cache, so today's tail still lands.
    if (cf._reg) return;
    cf._gateEnriched = false; // allow re-enrichment
    window._lastGateKey = ''; // force re-render which re-fetches
    if (typeof renderDedicatedScreen === 'function') renderDedicatedScreen();
  }, 3 * 60 * 1000); // retry every 3 minutes
}

function applyOverrideToFlight(flight) {
  if (!flight || !flight.flight) return;
  var ov = getOverrideForFlight(flight.flight);
  if (!ov) return;
  if (ov.gate) flight.gate = ov.gate;
  if (ov.aircraft) flight._aircraft = ov.aircraft;
  if (ov.reg) flight._reg = ov.reg;
  if (ov.equipCode) flight._aircraftCode = ov.equipCode;
  if (ov.status) flight.status = ov.status;
  if (ov.revisedTime) {
    flight.upd = ov.revisedTime;
    // Recalculate _revTs from the revised time
    var parts = ov.revisedTime.split(':');
    if (parts.length === 2) {
      var d = new Date(flight._sortTs || Date.now());
      d.setHours(parseInt(parts[0]), parseInt(parts[1]), 0, 0);
      flight._revTs = d.getTime();
    }
  }
  // Mark flight as having overrides for visual indicator
  flight._hasOverride = true;
}
function toggleOverridePanel() {
  var panel = document.getElementById('overridePanel');
  panel.classList.toggle('open');
  if (panel.classList.contains('open')) {
    loadOverrideFields();
  }
}
function loadOverrideFields() {
  var cf = window._gateCurrentFlight;
  if (!cf) return;
  var tag = document.getElementById('govFlightTag');
  tag.textContent = ' — ' + cf.flight;
  var ov = getOverrideForFlight(cf.flight) || {};
  document.getElementById('govGate').value = ov.gate || '';
  document.getElementById('govAircraft').value = ov.aircraft || '';
  document.getElementById('govReg').value = ov.reg || '';
  document.getElementById('govEquipCode').value = ov.equipCode || '';
  document.getElementById('govStatus').value = ov.status || '';
  document.getElementById('govRevisedTime').value = ov.revisedTime || '';
  document.getElementById('govMessage').value = ov.message || '';
  // Highlight fields that have overrides
  document.querySelectorAll('.gov-input').forEach(function(inp) {
    inp.classList.toggle('has-override', !!inp.value);
  });
}
function saveOverride() {
  var cf = window._gateCurrentFlight;
  if (!cf) return;
  var key = cf.flight.toUpperCase();
  var all = getGateOverrides();
  var ov = {};
  var gate = document.getElementById('govGate').value.trim();
  var aircraft = document.getElementById('govAircraft').value.trim();
  var reg = document.getElementById('govReg').value.trim().toUpperCase();
  var equipCode = document.getElementById('govEquipCode').value.trim().toUpperCase();
  var status = document.getElementById('govStatus').value;
  var revisedTime = document.getElementById('govRevisedTime').value;
  var message = document.getElementById('govMessage').value.trim();
  if (gate) ov.gate = gate;
  if (aircraft) ov.aircraft = aircraft;
  if (reg) ov.reg = reg;
  if (equipCode) ov.equipCode = equipCode;
  if (status) ov.status = status;
  if (revisedTime) ov.revisedTime = revisedTime;
  if (message) ov.message = message;
  ov._savedAt = new Date().toISOString();
  if (Object.keys(ov).length > 1) {
    all[key] = ov;
  } else {
    delete all[key];
  }
  setGateOverrides(all);
  // Flash saved message
  var msg = document.getElementById('govStatusMsg');
  msg.textContent = 'Saved!';
  msg.classList.add('show');
  setTimeout(function() { msg.classList.remove('show'); }, 2000);
  // Force re-render
  window._lastGateKey = '';
  dedicatedRenderKey = '';
  renderDedicatedScreen();
  loadOverrideFields();
  updateOverrideBtn();
}
function clearOverride() {
  var cf = window._gateCurrentFlight;
  if (!cf) return;
  var key = cf.flight.toUpperCase();
  var all = getGateOverrides();
  delete all[key];
  setGateOverrides(all);
  // Clear fields
  document.querySelectorAll('#overridePanel .gov-input').forEach(function(inp) {
    if (inp.tagName === 'SELECT') inp.value = '';
    else inp.value = '';
    inp.classList.remove('has-override');
  });
  var msg = document.getElementById('govStatusMsg');
  msg.textContent = 'Cleared!';
  msg.style.color = '#ef4444';
  msg.classList.add('show');
  setTimeout(function() { msg.classList.remove('show'); msg.style.color = '#22c55e'; }, 2000);
  window._lastGateKey = '';
  dedicatedRenderKey = '';
  renderDedicatedScreen();
  updateOverrideBtn();
}
function showAllOverrides() {
  var all = getGateOverrides();
  var keys = Object.keys(all);
  if (!keys.length) { alert('No saved overrides.'); return; }
  var lines = keys.map(function(k) {
    var o = all[k];
    var parts = [k + ':'];
    if (o.gate) parts.push('Gate=' + o.gate);
    if (o.aircraft) parts.push('Aircraft=' + o.aircraft);
    if (o.reg) parts.push('Reg=' + o.reg);
    if (o.status) parts.push('Status=' + o.status);
    if (o.message) parts.push('Msg="' + o.message + '"');
    return parts.join(' ');
  });
  alert('Active Gate Overrides:\n\n' + lines.join('\n'));
}
function updateOverrideBtn() {
  var btn = document.getElementById('overrideBtn');
  if (!btn) return;
  var cf = window._gateCurrentFlight;
  var ov = cf ? getOverrideForFlight(cf.flight) : null;
  // Remove existing badge
  var existing = btn.querySelector('.gov-active-badge');
  if (existing) existing.remove();
  if (ov) {
    btn.insertAdjacentHTML('beforeend', '<span class="gov-active-badge">ACTIVE</span>');
  }
}
function getOverrideMessage(flightNum) {
  var ov = getOverrideForFlight(flightNum);
  return (ov && ov.message) ? ov.message : null;
}

