// Escape: close panels/dropdowns; don't try to toggle a lobby that no longer exists
document.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;

  // 1) Close ctrl airport panel if open
  const apPanel = document.getElementById('apPanel');
  if (apPanel && !apPanel.classList.contains('hidden')) {
    apPanel.classList.add('hidden');
    return;
  }
  // 2) Close any open autocomplete dropdown
  let ddClosed = false;
  ['apDropdown','apDropdownCtrl','apDropdownMenu'].forEach(id => {
    const dd = document.getElementById(id);
    if (dd && dd.style.display !== 'none') { dd.style.display='none'; ddClosed=true; }
  });
  if (ddClosed) return;
  // 3) Close sidebar menu if open
  const menu = document.getElementById('overlayMenu');
  if (menu && menu.classList.contains('open') && typeof closeOverlayMenu === 'function') {
    closeOverlayMenu();
    return;
  }
  // 4) Nothing else to close — go back to picker
  returnToLobby();
});

