// ── MODE DETECTION & LOGIN ────────────────────────────────────────────────
// Auth handled by Cloudflare Worker KV — no credentials stored here
const LIVE_USER = '';
const LIVE_PASS = '';

let LIVE_MODE = false;
let GATE_BG_MODE = 'photo'; // 'photo', 'airline', or 'custom'
// Restore last-used mode from localStorage so the pill stays sticky across reloads.
try {
  var _savedBgMode = localStorage.getItem('fids_gate_bg_mode');
  if (_savedBgMode && ['photo','airline','custom'].indexOf(_savedBgMode) !== -1) {
    GATE_BG_MODE = _savedBgMode;
  }
} catch(e) {}

// ── AIRLINE BG ROTATION STATE ─────────────────────────────────────────
// Selected slide index in the current airline's rotation list.
// 'auto' = rotate every ~10s; integer = static pick.
// Persisted so it survives page reloads.
var GATE_AIRLINE_BG_PICK = 'auto';
try { GATE_AIRLINE_BG_PICK = localStorage.getItem('fids_airline_bg_pick') || 'auto'; } catch(e) {}
var _airlineBgTimer = null;
var _airlineBgIndex = 0;
var _airlineBgLastAirline = '';

// Build the ordered slide list for a given airline.
// Each slide is either a URL string (brand scene) or the marker '__SKY_LOGO__'
// (sky gradient + centered airline logo watermark — used when no brand scene).
function getAirlineBgSlides(airlineCode) {
  var code = String(airlineCode || '').toUpperCase();
  var registry = (typeof AIRLINE_BACKGROUNDS !== 'undefined') ? AIRLINE_BACKGROUNDS[code] : null;
  var list = [];
  if (registry && registry.length) {
    for (var i = 0; i < registry.length; i++) list.push(registry[i]);
  }
  // Sky variants — always added, in order dusk, day, night — so every
  // airline rotation has three distinct sky looks. For airlines without
  // brand photos, these are the only slides.
  list.push('__SKY_DUSK__');
  list.push('__SKY_DAY__');
  list.push('__SKY_NIGHT__');
  return list;
}

// Human-friendly label for a slide (used in the menu dropdown).
function getAirlineBgSlideLabel(slide, idx) {
  if (slide === '__SKY_LOGO__' || slide === '__SKY_DUSK__') return 'Dusk Sky';
  if (slide === '__SKY_DAY__') return 'Blue Sky';
  if (slide === '__SKY_NIGHT__') return 'Night Sky';
  // Derive a short name from the filename (e.g. "americanbackground3.png" → "Scene 3")
  var fn = String(slide).split('/').pop().replace(/\.(png|jpg|jpeg|webp|avif)$/i, '');
  var m = fn.match(/(\d+)$/);
  if (m) return 'Scene ' + m[1];
  return 'Scene ' + (idx + 1);
}

function changeFont(f) {
  const fam = "'" + f + "', sans-serif";
  document.body.style.fontFamily = fam;
  // Force font on ALL elements including gate/baggage screens
  let s = document.getElementById('fids-font-override');
  if (!s) { s = document.createElement('style'); s.id = 'fids-font-override'; document.head.appendChild(s); }
  // .axr (Accor hotel ads) is EXEMPT — brand typography (The Seasons /
  // Montserrat / Rebelton…) must render per brand book, not the board font.
  // Without the :not() guards this universal !important nuked those fonts
  // (Nick: 'AC Nord takes over' — it was actually this override).
  s.textContent = `*:where(:not(.axr):not(.axr *):not(.ac-ico)), *:where(:not(.axr):not(.axr *):not(.ac-ico))::before, *:where(:not(.axr):not(.axr *):not(.ac-ico))::after { font-family: ${fam} !important; } .ac-ico, .ac-ico::before { font-family:'ac-icons' !important; }`;
  // Persist the choice — page load used to hard-reset to Geist, wiping
  // whatever the user picked ("every time I add a new font it goes away").
  try { localStorage.setItem('fids_font_choice', f); } catch (e) {}
  try { var _fs = document.getElementById('fontSel'); if (_fs && _fs.value !== f) _fs.value = f; } catch (e) {}
}

// Font stacks shared by the control-bar dropdown AND the FIDS Console
// Customize panel (same keys the Customize <select> saves).
var FIDS_FONT_STACKS = {
  'possibility':   "'Possibility', -apple-system, BlinkMacSystemFont, sans-serif",
  'ginto-nord': "'ABC Ginto Nord', -apple-system, BlinkMacSystemFont, sans-serif",
  'ginto-nord-thin': "'ABC Ginto Nord Thin', 'ABC Ginto Nord', sans-serif",
  'ginto-nord-light': "'ABC Ginto Nord Light', 'ABC Ginto Nord', sans-serif",
  'ginto-nord-regular': "'ABC Ginto Nord Regular', 'ABC Ginto Nord', sans-serif",
  'ginto-nord-medium': "'ABC Ginto Nord Medium', 'ABC Ginto Nord', sans-serif",
  'ginto-nord-bold': "'ABC Ginto Nord Bold', 'ABC Ginto Nord', sans-serif",
  'ginto-nord-black': "'ABC Ginto Nord Black', 'ABC Ginto Nord', sans-serif",
  'ginto-nord-ultra': "'ABC Ginto Nord Ultra', 'ABC Ginto Nord', sans-serif",
  'ginto-nord-hairline': "'ABC Ginto Nord Hairline', 'ABC Ginto Nord', sans-serif",
    'tr-tahoma':     "'TR Tahoma', Tahoma, Geneva, Verdana, sans-serif",
  'geist':         "'Geist', -apple-system, BlinkMacSystemFont, sans-serif",
  'inter':         "'Inter', system-ui, -apple-system, sans-serif",
  'manrope':       "'Manrope', system-ui, -apple-system, sans-serif",
  'space-grotesk': "'Space Grotesk', system-ui, -apple-system, sans-serif",
  'airport':       "'Airport', system-ui, -apple-system, sans-serif",
  'airport-x':     "'Airport X', system-ui, -apple-system, sans-serif",
  'system':        "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  'mono':          "'JetBrains Mono', 'SF Mono', 'Roboto Mono', Menlo, Consolas, monospace"
};
// Re-apply the saved font on page load. Priority:
//   1. FIDS Console → Customize panel pick (per-airport pref) — the UI users
//      actually use. The GATE screen never applied this on load (only the
//      board render did), so the font vanished on refresh until the panel
//      was reopened. Apply it here for every screen type.
//   2. Control-bar FONT dropdown pick (fids_font_choice).
//   3. defaultFont (page default), then Geist.
function restoreFontChoice(defaultFont) {
  try {
    var _iata = String((window._gateIata || (document.getElementById('apSel') || {}).value || '')).toUpperCase();
    if (_iata) {
      var _cfgRaw = localStorage.getItem('fids_customize_' + _iata);
      var _cfg = _cfgRaw ? JSON.parse(_cfgRaw) : null;
      var _stack = null;
      if (_cfg && _cfg.font) {
        if (FIDS_FONT_STACKS[_cfg.font]) {
          _stack = FIDS_FONT_STACKS[_cfg.font];
        } else if (String(_cfg.font).indexOf('custom:') === 0) {
          // User-uploaded font ("custom:Name") — menu.js re-injects its
          // @font-face from fids_custom_fonts on every load; we just point at it.
          var _cfName = String(_cfg.font).slice(7).replace(/'/g, '');
          if (_cfName) _stack = "'" + _cfName + "', system-ui, -apple-system, sans-serif";
        }
      }
      if (_stack) {
        document.body.style.setProperty('--font-primary', _stack, 'important');
        var s = document.getElementById('fids-font-override');
        if (!s) { s = document.createElement('style'); s.id = 'fids-font-override'; document.head.appendChild(s); }
        // .axr exempt — Accor brand ads keep brand typography (see changeFont).
        s.textContent = '*:where(:not(.axr):not(.axr *):not(.ac-ico)), *:where(:not(.axr):not(.axr *):not(.ac-ico))::before, *:where(:not(.axr):not(.axr *):not(.ac-ico))::after { font-family: ' + _stack + " !important; } .ac-ico, .ac-ico::before { font-family:'ac-icons' !important; }";
        return;
      }
    }
  } catch (e) {}
  var f = '';
  try { f = localStorage.getItem('fids_font_choice') || ''; } catch (e) {}
  changeFont(f || defaultFont || 'Possibility');  // Possibility = brand default
}

// Start / stop the airline background rotation timer. Runs only when
// GATE_BG_MODE === 'airline' AND the user has 'auto' selected.
function stopAirlineBgRotation() {
  if (_airlineBgTimer) { clearInterval(_airlineBgTimer); _airlineBgTimer = null; }
}
function startAirlineBgRotation() {
  stopAirlineBgRotation();
  if (GATE_BG_MODE !== 'airline') return;
  if (GATE_AIRLINE_BG_PICK !== 'auto') return;
  _airlineBgTimer = setInterval(function() {
    if (GATE_BG_MODE !== 'airline') { stopAirlineBgRotation(); return; }
    var code = (window._gateCurrentAirline || '').toUpperCase();
    var slides = getAirlineBgSlides(code);
    // A single slide has nothing to rotate to — repainting it anyway made
    // the whole screen visibly pulse on every tick (Nick: 'everything on
    // the screen bumps in and out about every 10 seconds').
    if (slides.length < 2) return;
    _airlineBgIndex = (_airlineBgIndex + 1) % slides.length;
    // Repaint both photo layers directly (avoid a full screen rebuild).
    var ids = ['gatePhotoBg','gateWelcomePhotoBg','gateBgDiv'];
    for (var i = 0; i < ids.length; i++) {
      var el = document.getElementById(ids[i]);
      if (el) setGateBg(el, window._gateIata || '');
    }
  }, 45000); // was 10s — a 10-second full-background swap read as a constant bump
}

// Update the menu dropdown (if visible) with the current airline's slide list.
function refreshAirlineBgPicker() {
  var sel = document.getElementById('smAirlineBgPick');
  if (!sel) return;
  var code = (window._gateCurrentAirline || '').toUpperCase();
  var slides = code ? getAirlineBgSlides(code) : [];
  var current = GATE_AIRLINE_BG_PICK;
  var html = '<option value="auto"' + (current === 'auto' ? ' selected' : '') + '>Auto (rotate every 45s)</option>';
  for (var i = 0; i < slides.length; i++) {
    var val = String(i);
    var sel2 = (current === val) ? ' selected' : '';
    html += '<option value="' + val + '"' + sel2 + '>' + getAirlineBgSlideLabel(slides[i], i) + '</option>';
  }
  sel.innerHTML = html;
  // Show the picker only in airline mode
  var wrap = document.getElementById('smAirlineBgPickWrap');
  if (wrap) wrap.style.display = (GATE_BG_MODE === 'airline') ? 'block' : 'none';
}

function setAirlineBgPick(val) {
  GATE_AIRLINE_BG_PICK = val;
  try { localStorage.setItem('fids_airline_bg_pick', val); } catch(e) {}
  if (val !== 'auto') {
    var idx = parseInt(val, 10);
    if (!isNaN(idx)) _airlineBgIndex = idx;
    stopAirlineBgRotation();
  } else {
    startAirlineBgRotation();
  }
  // Repaint immediately
  var ids = ['gatePhotoBg','gateWelcomePhotoBg','gateBgDiv'];
  for (var i = 0; i < ids.length; i++) {
    var el = document.getElementById(ids[i]);
    if (el) setGateBg(el, window._gateIata || '');
  }
}

function setGateBgMode(m) {
  if (['photo','airline','custom'].indexOf(m) === -1) return;
  GATE_BG_MODE = m;
  try { localStorage.setItem('fids_gate_bg_mode', m); } catch(e) {}
  const ids = {bgLight:'light',bgDark:'dark',bgSky:'sky',bgAirline:'airline',bgPhoto:'photo',bgCustom:'custom'};
  for (const [id, mode] of Object.entries(ids)) {
    const el = document.getElementById(id);
    if (el) el.classList.toggle('active', m === mode);
  }
  const cp = document.getElementById('customBgPanel');
  if (cp) cp.style.display = m === 'custom' ? 'block' : 'none';
  // Update ctrl bar bg buttons
  document.querySelectorAll('.ctrl-bg-btn').forEach(btn => {
    btn.classList.toggle('active', btn.title && btn.title.toLowerCase().startsWith(m));
  });
  // Hide the welcome text when in airline mode — the airline IS the show.
  var _wt = document.getElementById('gateWelcomeText');
  if (_wt) _wt.style.display = (m === 'airline') ? 'none' : 'flex';
  // Start / stop airline bg rotation as appropriate
  if (m === 'airline') {
    _airlineBgIndex = (GATE_AIRLINE_BG_PICK === 'auto') ? 0 : (parseInt(GATE_AIRLINE_BG_PICK,10) || 0);
    startAirlineBgRotation();
  } else {
    stopAirlineBgRotation();
  }
  // Refresh the menu picker (show/hide + rebuild options)
  try { refreshAirlineBgPicker(); } catch(e) {}
  // Force re-render so the chosen mode actually applies to the current screen
  try { if (typeof dedicatedRenderKey !== 'undefined') { dedicatedRenderKey = ''; } } catch(e){}
  try { if (typeof renderDedicatedScreen === 'function') renderDedicatedScreen(); } catch(e){}
}

// ──────────────────────────────────────────────────────────────────────
// CUSTOM BACKGROUND URL MANAGER
// ──────────────────────────────────────────────────────────────────────
// Stores a persistent list of image URLs the user wants to use as gate
// backgrounds when the mode is set to 'custom'. URLs are saved in
// localStorage under 'fids_custom_bg_urls' so they survive reloads.
// The manage dialog (opened by clicking the ⚙ button next to the Custom
// mode button) shows a simple list with add/remove controls.

var _customBgIndex = 0;  // rotating index — global so all panels sync

function _loadCustomBgUrls() {
  try {
    var raw = localStorage.getItem('fids_custom_bg_urls');
    var arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr : [];
  } catch(e) { return []; }
}

function _saveCustomBgUrls(arr) {
  try { localStorage.setItem('fids_custom_bg_urls', JSON.stringify(arr)); } catch(e) {}
}


// Safe UI wrapper for background buttons. Some buttons are rendered on pages
// where the dedicated screen renderer is not active yet; calling the renderer
// blindly made those buttons feel dead or throw errors. This wrapper applies
// the mode, clears the dedicated render cache only when it exists, and then
// asks the best available renderer to repaint.
function setDedicatedBgMode(mode) {
  try {
    if (typeof setGateBgMode === 'function') setGateBgMode(mode);
    // Custom backgrounds need saved image URLs — with none, the screen just
    // went BLACK and looked broken (Nick). Open the URL manager right away
    // so picking Custom always leads somewhere.
    if (mode === 'custom' && typeof _loadCustomBgUrls === 'function'
        && !_loadCustomBgUrls().length && typeof manageCustomBgUrls === 'function') {
      manageCustomBgUrls();
    }
    if (typeof dedicatedRenderKey !== 'undefined') dedicatedRenderKey = '';
    if (typeof renderDedicatedScreen === 'function') {
      renderDedicatedScreen();
    } else if (typeof render === 'function') {
      render();
    }
    if (typeof _syncMenu === 'function') _syncMenu();
  } catch (e) {
    console.error('[FIDS] setDedicatedBgMode failed:', e);
  }
}
window.setDedicatedBgMode = setDedicatedBgMode;

function manageCustomBgUrls() {
  // Remove any existing dialog first
  var existing = document.getElementById('customBgManager');
  if (existing) { existing.remove(); return; }

  var urls = _loadCustomBgUrls();
  var dlg = document.createElement('div');
  dlg.id = 'customBgManager';
  dlg.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:10000;'
    + 'background:#18181b;color:#fff;border:1px solid #3f3f46;border-radius:10px;'
    + 'padding:20px;min-width:420px;max-width:600px;max-height:80vh;overflow:auto;'
    + 'font-family:Helvetica,Arial,sans-serif;box-shadow:0 20px 60px rgba(0,0,0,0.6);';

  function render() {
    var html = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">'
      +   '<h3 style="margin:0;font-size:16px;font-weight:700;">Custom Background URLs</h3>'
      +   '<button onclick="document.getElementById(\'customBgManager\').remove()" style="background:transparent;border:none;color:#a1a1aa;font-size:22px;cursor:pointer;line-height:1;">&times;</button>'
      + '</div>'
      + '<p style="font-size:12px;color:#a1a1aa;margin:0 0 14px 0;line-height:1.4;">'
      +   'Add image URLs here. When the background mode is set to Custom, all screens will rotate through these images. URLs are saved in this browser.'
      + '</p>'
      + '<div style="display:flex;gap:8px;margin-bottom:14px;">'
      +   '<input id="newCustomBgUrl" type="text" placeholder="https://example.com/image.jpg" '
      +   'style="flex:1;background:#27272a;color:#fff;border:1px solid #3f3f46;border-radius:6px;padding:8px 10px;font-size:13px;" '
      +   'onkeypress="if(event.key===\'Enter\')document.getElementById(\'customBgAddBtn\').click()">'
      +   '<button id="customBgAddBtn" style="background:#2563eb;color:#fff;border:none;border-radius:6px;padding:8px 14px;font-size:13px;font-weight:600;cursor:pointer;">Add URL</button>'
      +   '<button id="customBgPickLibraryBtn" style="background:#fbbf24;color:#0f1424;border:none;border-radius:6px;padding:8px 14px;font-size:13px;font-weight:600;cursor:pointer;">Pick from Library</button>'
      + '</div>';

    if (urls.length === 0) {
      html += '<div style="text-align:center;color:#71717a;font-size:12px;padding:20px;border:1px dashed #3f3f46;border-radius:6px;">No URLs saved yet. Add one above.</div>';
    } else {
      html += '<div style="display:flex;flex-direction:column;gap:6px;">';
      urls.forEach(function(u, i) {
        // Show a small thumbnail of the image next to its URL
        html += '<div style="display:flex;align-items:center;gap:10px;background:#27272a;border-radius:6px;padding:6px 10px;">'
          +   '<img src="' + u.replace(/"/g,'&quot;') + '" style="width:48px;height:32px;object-fit:cover;border-radius:4px;background:#18181b;flex-shrink:0;" onerror="this.style.opacity=0.3">'
          +   '<div style="flex:1;font-size:11px;color:#d4d4d8;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + u.replace(/</g,'&lt;') + '</div>'
          +   '<button data-idx="' + i + '" class="customBgRmBtn" style="background:#7f1d1d;color:#fff;border:none;border-radius:4px;padding:4px 10px;font-size:11px;cursor:pointer;">Remove</button>'
          + '</div>';
      });
      html += '</div>';
      html += '<div style="margin-top:14px;font-size:11px;color:#71717a;text-align:center;">' + urls.length + ' URL' + (urls.length !== 1 ? 's' : '') + ' saved</div>';
    }

    dlg.innerHTML = html;

    // Wire up add button
    dlg.querySelector('#customBgAddBtn').onclick = function() {
      var input = dlg.querySelector('#newCustomBgUrl');
      var v = (input.value || '').trim();
      if (!v) return;
      if (!/^https?:\/\//i.test(v)) { alert('URL must start with http:// or https://'); return; }
      urls.push(v);
      _saveCustomBgUrls(urls);
      render();
      // Trigger a re-render if we're currently in custom mode
      if (GATE_BG_MODE === 'custom') {
        try { dedicatedRenderKey = ''; renderDedicatedScreen(); } catch(e){}
      }
    };

    // v218.99.14 — Pick from Library button (opens the universal picker)
    var pickBtn = dlg.querySelector('#customBgPickLibraryBtn');
    if (pickBtn) pickBtn.onclick = function() {
      if (!window.FIDS_MEDIA_PICKER) {
        alert('Media Library not available yet — try again in a moment.');
        return;
      }
      window.FIDS_MEDIA_PICKER.open({
        category: 'background',
        type: 'image',
        title: 'Pick background image from Library',
        allowUpload: true,
        onPick: function(item) {
          if (!item || !item.url) return;
          // Skip if already in list
          if (urls.indexOf(item.url) >= 0) {
            render();
            return;
          }
          urls.push(item.url);
          _saveCustomBgUrls(urls);
          render();
          if (GATE_BG_MODE === 'custom') {
            try { dedicatedRenderKey = ''; renderDedicatedScreen(); } catch(e){}
          }
        }
      });
    };

    // Wire up remove buttons
    dlg.querySelectorAll('.customBgRmBtn').forEach(function(btn) {
      btn.onclick = function() {
        var idx = parseInt(btn.dataset.idx, 10);
        urls.splice(idx, 1);
        _saveCustomBgUrls(urls);
        render();
        if (GATE_BG_MODE === 'custom') {
          try { dedicatedRenderKey = ''; renderDedicatedScreen(); } catch(e){}
        }
      };
    });
  }

  render();
  document.body.appendChild(dlg);

  // Close on backdrop click (outside the dialog)
  var backdrop = document.createElement('div');
  backdrop.id = 'customBgBackdrop';
  backdrop.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;';
  backdrop.onclick = function() { dlg.remove(); backdrop.remove(); };
  document.body.appendChild(backdrop);
  dlg.style.zIndex = '10000';
}

