// Check if already authenticated via URL
// ── SESSION RESTORE on page load ─────────────────────────────────────────
// If we already have a valid session token, restore LIVE_MODE=true BEFORE
// the demo rebuild timer would start. Without this, every page refresh
// knocks you back to DEMO data until you log in again.
if (sessionStorage.getItem('fids_token')) {
  LIVE_MODE = true;
  // Defer UI updates until DOM is ready
  document.addEventListener('DOMContentLoaded', () => {
    try {
      const m = document.getElementById('modeBadge');
      if (m) {
        m.className = 'mode-badge live';
        m.textContent = 'LIVE';
      }
      const ll = document.getElementById('liveLabel');
      if (ll) ll.textContent = 'LIVE';
      const al = document.getElementById('apiLabel');
      if (al) al.textContent = 'AERODATABOX';
      const ld = document.querySelector('.live-dot');
      if (ld) ld.style.background = '#10b981';
      const lm = document.getElementById('loginModal');
      if (lm) lm.style.display = 'none';
    } catch(e) {}
  });
  console.log('[FIDS] Session restored from token — LIVE mode active');
}

if (/[?&]live/.test(location.search) || location.hash === '#live') {
  // Show login modal
  showLoginModal();
}

function showLoginModal() {
  const m = document.getElementById('loginModal');
  if (m) m.style.display = 'flex';
}

async function attemptLogin() {
  const u = document.getElementById('loginUser').value.trim();
  const p = document.getElementById('loginPass').value.trim();
  const err = document.getElementById('loginError');
  err.textContent = '';
  // Authenticate via Cloudflare Worker
  try {
    const resp = await fetch('https://fids-proxy.n-leblanc1984.workers.dev/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: u, password: p })
    });
    const data = await resp.json();
    if (resp.ok && data.token) {
      sessionStorage.setItem('fids_token', data.token);
      sessionStorage.setItem('fids_user', JSON.stringify(data.user || { username: u }));
      LIVE_MODE = true;
      if (typeof demoRebuildTimer !== 'undefined' && demoRebuildTimer) {
        clearInterval(demoRebuildTimer); demoRebuildTimer = null;
      }
      document.getElementById('loginModal').style.display = 'none';
      document.getElementById('modeBadge').className  = 'mode-badge live';
      document.getElementById('modeBadge').textContent = 'LIVE';
      document.getElementById('liveLabel').textContent = 'LIVE';
      document.getElementById('apiLabel').textContent  = 'AERODATABOX';
      document.querySelector('.live-dot').style.background = '#10b981';
      // v11p: no lobby overlay to coordinate with; just refresh for new airport
      onApChange();
    } else {
      err.textContent = (data.error || 'Invalid credentials') + ' / Identifiants invalides';
    }
  } catch(e) {
    err.textContent = 'Connection error / Erreur de connexion';
    err.style.display = 'block';
    document.getElementById('loginPass').value = '';
  }
}

function cancelLogin() {
  document.getElementById('loginModal').style.display = 'none';
}

if (!LIVE_MODE) {
  document.getElementById('modeBadge').className  = 'mode-badge demo';
  document.getElementById('modeBadge').textContent = 'DEMO';
  document.getElementById('liveLabel').textContent = 'DEMO';
  document.getElementById('apiLabel').textContent  = 'DEMO MODE';
  document.querySelector('.live-dot').style.background = '#eab308';
}

