// ── PHONE HANDOFF → app.html (Nick: "Wrong app opens should be the app one")
// A PHONE opening any board link (fids/gids/bids) gets the Airport Companion
// app instead, with the URL state carried over — app.html reads ?ap= /
// ?screen= / ?gate= / ?belt= and lands on the same airport, tab and gate.
// Guards keep every DISPLAY on the board: rotator iframes, stream/yt/compact
// layouts, and the ?nomobile=1 escape hatch (same as index.html's router).
// Bare 'Android' without 'Mobile' is NOT a phone — Android TVs carry it. No
// width test either, so a narrow desktop window keeps the board.
(function () {
  try {
    if (window.self !== window.top) return;
    if (document.documentElement.classList.contains('fids-stream')) return;
    var _hq = location.search || '';
    if (/[?&](nomobile|stream|yt|compact)([=&]|$)/.test(_hq)) return;
    var _hua = navigator.userAgent || '';
    var _hPhone = /iPhone|iPod|iPad|Windows Phone/i.test(_hua) || (/Android/i.test(_hua) && /Mobile/i.test(_hua));
    if (!_hPhone) return;
    location.replace('app.html' + _hq + location.hash);
  } catch (e) {}
})();

// ── CROSS-DEVICE SCREEN STATE (Nick: "They need to be connected to the same
// devices … I'm not connecting in the same system whatsoever") ──────────────
// The URL always mirrors the full screen state: ?ap= is kept in sync by
// onApChange, and ?screen= + ?gate=/?belt= are kept in sync here. Copy the
// address bar onto ANY device — phone, TV, laptop — and it lands on the SAME
// airport, screen type and gate/belt. localStorage stays the per-display
// memory across reloads; the URL is the cross-device carrier and WINS on
// load (see SCREEN-STATE RESTORE near the end of this file).
function _fidsSyncUrl(t, s) {
  try {
    if (window.self !== window.top) return;   // rotator iframe — leave frame URLs alone
    if (document.documentElement.classList.contains('fids-stream')) return;
    var q = new URLSearchParams(window.location.search);
    if (document.body && document.body.getAttribute('data-page')) {
      // Dedicated gids/bids pages carry their gate/belt natively (?gate= /
      // ?belt=) and auto-pick one when absent. Only REFRESH a param the URL
      // already has — a plain gids.html (auto-pick, walking lobby screen)
      // keeps its URL clean so reloads keep auto-picking.
      var keyD = (t === 'baggage') ? 'belt' : 'gate';
      if (!q.get(keyD) || !s) return;
      q.set(keyD, s);
    } else {
      q.delete('screen'); q.delete('sub'); q.delete('gate'); q.delete('belt'); q.delete('carousel');
      if (t && t !== 'main') {
        q.set('screen', t);
        if (s) q.set((t === 'baggage') ? 'belt' : 'gate', s);
      }
    }
    var qs = q.toString();
    history.replaceState(null, '', window.location.pathname + (qs ? '?' + qs : '') + window.location.hash);
  } catch (e) {}
}

function changeScreenType(val) {
  screenType = val;
  // v22814: the SCREEN TYPE dropdown always mirrors reality. The gids boot
  // path called changeScreenType('gate') without setting the select, so the
  // menu read 'Main Board' on a live gate (Nick: 'Proof im on the gate
  // right now its showing main board its fucked up'). Sync here — the one
  // place every caller passes through.
  try { var _stSel = document.getElementById('screenTypeSel'); if (_stSel && _stSel.value !== val) _stSel.value = val; } catch (e) {}
  // Survive the self-update reloads: a screen put into gate/baggage mode via
  // the MENU (no URL param) was being dumped back to the main board on every
  // deploy (Nick: 'what happened to baggage… it's all over the place').
  try { localStorage.setItem('fids_screen_state', JSON.stringify({ t: val, s: (typeof subScreenVal !== 'undefined' ? subScreenVal : '') })); } catch (e) {}
  document.body.classList.toggle('uxg-gate-mode', val === 'gate');
  if (val !== 'gate') { if (typeof stopGateAds==='function') stopGateAds(); } else { if (typeof startGateAds==='function' && !_gateAdTimer) startGateAds(); }
  
  const subSel = document.getElementById('subScreenSel');
  const testBtn = document.getElementById('testFlightBtn');
  const bgCtrls = document.getElementById('ctrlBgGroup');
  const ovBtn = document.getElementById('overrideBtn');
  const ovPanel = document.getElementById('overridePanel');
  if (bgCtrls) bgCtrls.style.display = val === 'gate' ? 'flex' : 'none';
  if (ovBtn) ovBtn.style.display = val === 'gate' ? 'inline-block' : 'none';
  if (ovPanel && val !== 'gate') ovPanel.classList.remove('open');
  if (val === 'main') {
    subSel.style.display = 'none';
    testBtn.style.display = 'inline-block';
    const _ft = document.getElementById('fidsTable');     if (_ft) _ft.style.display = '';
    const _ca2 = document.querySelector('.content-area'); if (_ca2) _ca2.style.display = '';
    const _gv2 = document.getElementById('gateView');     if (_gv2) _gv2.style.display = 'none';
    const _bv2 = document.getElementById('baggageView');  if (_bv2) _bv2.style.display = 'none';
    const _hd2 = document.querySelector('.hdr');          if (_hd2) _hd2.style.display = '';
    const _tk2 = document.querySelector('.ticker');       if (_tk2) _tk2.style.display = '';
    const _bn2 = document.getElementById('fidsBanner');   if (_bn2) _bn2.style.display = '';
    const vs = document.querySelector('.view-selector');
    if (vs) vs.style.display = '';
    render();
  } else {
    subSel.style.display = 'inline-block';
    testBtn.style.display = val === 'gate' ? 'inline-block' : 'none';
    updateSubScreens();
    render();
    if (val === 'gate') scheduleGateControlsAutoHide();
  }
  // URL sync AFTER updateSubScreens — it settles subScreenVal for the new
  // type (kept when still valid, else first available), so the URL never
  // carries a gate number from the previous screen type.
  _fidsSyncUrl(val, (val === 'main') ? '' : (typeof subScreenVal !== 'undefined' ? subScreenVal : ''));
}

function changeSubScreen(val) {
  try { localStorage.setItem('fids_screen_state', JSON.stringify({ t: (typeof screenType !== 'undefined' ? screenType : 'main'), s: val })); } catch (e) {}
  // Sanitize the gate/belt value (it comes from a DOM <select>.value, a CodeQL
  // "DOM text reinterpreted as HTML" source) before it flows into the gate
  // innerHTML. Gates/belts are alphanumeric — strip anything else (incl. < > & ").
  subScreenVal = String(val == null ? '' : val).replace(/[^A-Za-z0-9 ./\-]/g, '');
  _fidsSyncUrl((typeof screenType !== 'undefined' ? screenType : 'main'), subScreenVal);
  render();
}

function updateSubScreens() {
  const subSel = document.getElementById('subScreenSel');
  const oldVal = subSel.value;
  subSel.innerHTML = '';
  const isDep = screenType === 'gate';
  const isBag = screenType === 'baggage';
  const flights = isDep ? (data.dep || []) : (data.arr || []);
  // For BIDS: build dropdown from belts (synthesized via belt rules at
  // normalize-time). For gate screens: build from gate values.
  let locations;
  let useGate = true;
  if (isBag) {
    locations = [...new Set(flights.map(f => f._belt).filter(b => b && b !== '—'))].sort();
    // YQM has exactly two carousels: 1 (domestic) and 2 (international). Always
    // surface BOTH — even an empty Carousel 2 — so travelers always see where
    // international bags come out (Nick). Other airports list only live belts.
    try {
      var _apBagSel = document.getElementById('apSel');
      if (_apBagSel && _apBagSel.value === 'YQM') {
        if (locations.indexOf('1') === -1) locations.push('1');
        if (locations.indexOf('2') === -1) locations.push('2');
        locations = [...new Set(locations)].sort();
      }
    } catch (e) {}
    useGate = false;
  } else {
    locations = [...new Set(flights.map(f => f.gate).filter(g => g && g !== '—'))].sort();
  }
  if (!locations.length) {
    // No belt/gate data — use flight numbers as sub-screen identifiers
    locations = [...new Set(flights.map(f => f.flight).filter(Boolean))].sort();
    useGate = false;
  }
  if (!locations.length) {
    subSel.innerHTML = '<option value="">N/A</option>';
    subScreenVal = '';
    return;
  }
  locations.forEach(loc => {
    const opt = document.createElement('option');
    opt.value = loc;
    // Gate screens use "GATE x"; BIDS uses "BELT x".
    // Belt keys may be terminal-composed ("1-4") — strip the prefix for
    // display since BIDS shows flights from one terminal at a time.
    if (isBag) {
      const _m = String(loc).match(/^(\w+)-(.+)$/);
      opt.textContent = 'BELT ' + (_m ? _m[2] : loc);
    }
    else if (useGate) opt.textContent = 'GATE ' + loc;
    else opt.textContent = loc;
    subSel.appendChild(opt);
  });
  if (locations.includes(oldVal)) { subSel.value = oldVal; subScreenVal = oldVal; }
  else { subSel.value = locations[0]; subScreenVal = locations[0]; }
}

// ── TEST FLIGHT ENTRY ─────────────────────────────────────────────────────
function openTestFlight() {
  const modal = document.getElementById('testFlightModal');
  modal.style.display = 'flex';
  // Pre-fill time with current time + 1 hour
  const now = new Date();
  const later = new Date(now.getTime() + 3600000);
  const iata = (document.getElementById('apSel').value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const tz = (AP[iata] || {}).tz;
  const tOpt = tz ? {timeZone:tz, hour:'2-digit', minute:'2-digit', hour12:true}
                   : {hour:'2-digit', minute:'2-digit', hour12:true};
  document.getElementById('tfTime').value = later.toLocaleTimeString('en-CA', tOpt);
}

function closeTestFlight() {
  document.getElementById('testFlightModal').style.display = 'none';
}

function submitTestFlight() {
  const gate = document.getElementById('tfGate').value.trim().toUpperCase();
  const airline = document.getElementById('tfAirline').value.trim().toUpperCase();
  const flight = document.getElementById('tfFlight').value.trim().toUpperCase();
  const dest = document.getElementById('tfDest').value.trim().toUpperCase();
  const destIata = document.getElementById('tfDestIata').value.trim().toUpperCase();
  const timeVal = document.getElementById('tfTime').value;
  const status = document.getElementById('tfStatus').value;
  // Optional equipment + operator fields (added in v11p).
  const equipEl = document.getElementById('tfEquip');
  const operEl = document.getElementById('tfOperator');
  const equip = equipEl ? equipEl.value.trim().toUpperCase() : '';
  const operator = operEl ? operEl.value.trim().toUpperCase() : '';

  if (!gate || !flight || !dest) { alert('Please fill in Gate, Flight # and Destination'); return; }

  // Build time string and sortTs
  const now = new Date();
  const [h, m] = (timeVal || '12:00').split(':').map(Number);
  const schedDate = new Date(now);
  schedDate.setHours(h, m, 0, 0);
  if (schedDate < now - 3600000) schedDate.setDate(schedDate.getDate() + 1); // next day if past

  const iata = (document.getElementById('apSel').value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const tz = (AP[iata] || {}).tz;
  const tOpt = tz ? {timeZone:tz, hour:'2-digit', minute:'2-digit', hour12:true}
                   : {hour:'2-digit', minute:'2-digit', hour12:true};
  const timeStr = schedDate.toLocaleTimeString('en-CA', tOpt);

  const testFlight = {
    time: timeStr,
    upd: null,
    flight: flight,
    airline: airline.slice(0,2),
    status: status,
    gate: gate,
    terminal: '—',
    dest: dest,
    _sortTs: schedDate.getTime(),
    _flightKey: flight + '_test',
    _locIata: destIata,
    _airlineName: AIRLINE_NAME[airline.slice(0,2)] || airline,
  };
  // Attach equipment + operator if the user selected them. These feed the
  // gate screen's aircraft mock/livery picker (e.g. AC + RV + 7M8 → Rouge
  // 737 MAX 8 livery from /aircraft/AC/7M8r.png).
  if (equip) {
    testFlight._aircraftCode = equip;
    testFlight._aircraft = (typeof formatAircraft === 'function') ? formatAircraft(equip) : equip;
  }
  if (operator && operator !== testFlight.airline) {
    testFlight._opCode = operator;
    var _OP_NAMES = { 'RV':'Air Canada Rouge','QK':'Jazz Aviation','WR':'WestJet Encore',
                      '9X':'Mokulele','MQ':'Envoy Air','OH':'PSA Airlines','PT':'Piedmont Airlines',
                      '9E':'Endeavor Air','OO':'SkyWest Airlines','YV':'Mesa Airlines',
                      'G7':'GoJet Airlines','YX':'Republic Airways' };
    testFlight._opName = _OP_NAMES[operator] || operator;
  }

  if (!window._testFlights) window._testFlights = [];
  window._testFlights.push(testFlight);
  data.dep.push(testFlight);
  data.dep.sort((a,b) => a._sortTs - b._sortTs);

  closeTestFlight();

  // Switch to gate screen for this gate
  screenType = 'gate';
  document.getElementById('screenTypeSel').value = 'gate';
  document.getElementById('subScreenSel').style.display = 'inline-block';
  document.getElementById('testFlightBtn').style.display = 'inline-block';
  updateSubScreens();
  // Select the test gate
  const subSel = document.getElementById('subScreenSel');
  if ([...subSel.options].some(o => o.value === gate)) {
    subSel.value = gate;
    subScreenVal = gate;
  }
  render();

  // Fetch weather for destination via Tomorrow.io
  if (destIata && COORDS[destIata]) fetchTomorrowWeather(destIata);
}

