function getTimeInTz(ts, tz) {
  if (!ts || !tz) return '';
  try {
    return new Date(ts).toLocaleTimeString('en-US', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: true });
  } catch(e) { return ''; }
}

