// Emblems wordmark native viewBox: 7.25 11.73 55.52 16.57 (after cropping).
// Aspect ratio ~3.35:1 — wide and short, similar to Fairmont.
function makeEmblemsLockupSvgDataUri(propertyName) {
  if (!propertyName) return null;
  // Clean name: strip ", Emblems Collection" suffix variations
  var clean = String(propertyName)
    .replace(/,?\s*emblems\s+collection\s*$/i, '')
    .replace(/,?\s*the\s+emblems\s+collection\s*$/i, '')
    .trim();
  if (!clean) clean = String(propertyName).trim();
  var name = clean.toUpperCase();

  // Auto-shrink for long names — same scale logic as Fairmont generator
  var len = name.length;
  var fontSize, letterSpacing;
  if (len <= 12) {
    fontSize = 5; letterSpacing = 1.5;
  } else if (len <= 18) {
    fontSize = 4.2; letterSpacing = 1.0;
  } else if (len <= 26) {
    fontSize = 3.4; letterSpacing = 0.6;
  } else {
    fontSize = 2.8; letterSpacing = 0.3;
  }

  // Output viewBox 80x36, same envelope as the Fairmont generator so both
  // brands present at consistent scale across the carousel.
  // Wordmark native viewBox is 7.25 11.73 55.52 16.57. To place it in our
  // 80x36 output, we need to translate by (-7.25, -11.73) then scale to fit.
  // Target: width 50, centered → scale = 50/55.52 = 0.901
  // Translated: x = (80-50)/2 = 15, y = ~3 (top-aligned)
  // After scale: y-offset for vertical centering in the top portion
  // No rule between wordmark and name — official lockups are one unit, and
  // the black stroke read as a stray black bar on photos (same fix as the
  // Fairmont generator).
  var svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 32" preserveAspectRatio="xMidYMid meet">'
    + '<g transform="translate(15, 2) scale(0.901) translate(-7.25, -11.73)" fill="#ffffff">'
    +   '<path d="' + _EMBLEMS_WORDMARK_D + '"/>'
    + '</g>'
    + '<text x="40" y="27" text-anchor="middle" '
    +   'font-family="Cinzel, &apos;Trajan Pro&apos;, &apos;Times New Roman&apos;, serif" '
    +   'font-size="' + fontSize + '" letter-spacing="' + letterSpacing + '" font-weight="500" fill="#ffffff">'
    +   name
    + '</text>'
    + '</svg>';
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
}



