var _g8LogoCache = {};
function g8LogoFail(img) {
  var code = img.getAttribute('data-code') || '';
  var fb = img.getAttribute('data-fb');
  // PAIR mode (emblem tile already shown beside this wordmark): external
  // lockup fallbacks would render the carrier's symbol a second time.
  // One retry with a fresh cache-buster, then the plain text name.
  if (img.getAttribute('data-pairmode') === '1') {
    if (!img.dataset.pmr) { img.dataset.pmr = '1'; img.src = img.src.split('?')[0] + '?r=' + Date.now(); return; }
    var nmP = img.getAttribute('data-name') || '';
    var spP = document.createElement('span');
    spP.className = 'g8-r1-airline';
    spP.textContent = nmP;
    if (img.parentNode) img.parentNode.replaceChild(spP, img);
    return;
  }
  // v197: for IATA codes that have been recycled (e.g. 4Y was Yute Air, now
  // Discover Airlines), skip external logo services — they serve the OLD
  // carrier's logo. Go straight to text fallback.
  var STALE_EXTERNAL = { '4Y': 1 };
  if (STALE_EXTERNAL[(code||'').toUpperCase()]) {
    if (code) _g8LogoCache[code] = 'text';
    var nm0 = img.getAttribute('data-name') || '';
    var sp0 = document.createElement('span');
    sp0.className = 'g8-r1-airline';
    sp0.textContent = nm0;
    if (img.parentNode) img.parentNode.replaceChild(sp0, img);
    return;
  }
  if (fb && img.src.indexOf('avs.io') === -1) {
    img.onerror = function() { g8LogoFail(this); };
    img.src = fb;
  } else {
    // Both sources failed - try Google Flights as last resort
    if (code && img.src.indexOf('gstatic') === -1) {
      img.onerror = function() { g8LogoFail(this); };
      img.src = 'https://www.gstatic.com/flights/airline_logos/70px/' + code + '.png';
    } else {
      if (code) _g8LogoCache[code] = 'text';
      var name = img.getAttribute('data-name') || '';
      var span = document.createElement('span');
      span.className = 'g8-r1-airline';
      span.textContent = name;
      if (img.parentNode) img.parentNode.replaceChild(span, img);
    }
  }
}

// Operating carrier for regional flights
// Québec-province airports show FRENCH FIRST on every bilingual pair
// (Nick — OQLF convention: 'anything in Quebec, French first then English').
function frFirstAirport(iata) {
  return /^(YUL|YQB|YHU|YMX|YMY|YBG|YVO|YZV|YUY|YGP|YGL|YGW|YKQ|YPX|YVP|YHR|YNA|YBC|YTF|AKV|YIK|YZG|YQC|YHA|YKG|XGR)$/.test(String(iata || '').toUpperCase());
}

function getAirlineAccent(code) {
  var c = String(code || '').toUpperCase();
  // AIRLINE_BRAND carries accents for carriers the accent map never got
  // (Caribbean etc.) — falling straight to navy painted their icons wrong.
  return AIRLINE_ACCENT[c] || AIRLINE_ACCENT[c.substring(0, 2)]
    || (typeof AIRLINE_BRAND !== 'undefined' && AIRLINE_BRAND[c] && AIRLINE_BRAND[c].accent)
    || '#0033A1';
}

// ── AIR CANADA EXPRESS OPERATOR MATRIX ───────────────────────────────────
// Marketing AC flight-number ranges may identify the operating partner for
// branding/boarding rules. They NEVER identify equipment: AC7992/AC7995 are a
// concrete counterexample to the old range-based DH4 assumption. Aircraft
// comes only from today's registration/live/scheduled truth chain.
function acExpressMatrix(fn) {
  if (isNaN(fn)) return null;
  if (fn >= 7000 && fn <= 7299) return { op:'PB', opName:'PAL Airlines' };
  if (fn >= 7950 && fn <= 8249) return { op:'QK', opName:'Jazz Aviation' };
  if (fn >= 8250 && fn <= 8999) return { op:'QK', opName:'Jazz Aviation' };
  return null;
}

// ── THE PARTNER HAS TO BE ABLE TO FLY THE LEG ────────────────────────────
// A flight-number band is contractual shorthand, not evidence. AC7053 (YYZ →
// YVR, 3,355 km, Air Canada's own metal per the feed) landed inside the
// 7000–7299 band, so the gate printed 'Operated by PAL Airlines' — and then,
// because PAL flies nothing but Dash 8-400s, the equipment rule below
// OVERWROTE the aircraft with a Dash 8. A turboprop crossing the country in
// the schedule's block time (Nick: 'PAL airlines going to operate that flight
// to YVR? In a Dash8? in one hour 15 minutes?'). Every band-derived operator
// now has to survive the geography; when it can't, the attribution is dropped
// and the marketing carrier stands on its own rather than being invented.
var _REGIONAL_MAX_KM = { 'PB': 1900, 'WR': 1900, 'QK': 2900 };
function _apLatLngFor(iata) {
  var c = String(iata || '').replace(/[^A-Za-z]/g, '').toUpperCase().slice(0, 3);
  if (!c) return null;
  try { if (typeof GATE_AP !== 'undefined' && GATE_AP[c]) return GATE_AP[c]; } catch (e) {}
  try { if (typeof AIRPORT_COORDS !== 'undefined' && AIRPORT_COORDS[c]) return AIRPORT_COORDS[c]; } catch (e) {}
  try {
    if (typeof AP !== 'undefined' && AP[c] && AP[c].lat != null && AP[c].lon != null) return [AP[c].lat, AP[c].lon];
  } catch (e) {}
  return null;
}
function _regionalOpFitsRoute(opCode, iataA, iataB) {
  var lim = _REGIONAL_MAX_KM[String(opCode || '').toUpperCase()];
  if (!lim) return true;                       // not a range-limited partner
  var A = _apLatLngFor(iataA), B = _apLatLngFor(iataB);
  if (!A || !B) return true;                   // unknown geography — no verdict either way
  try {
    var km = _haversineKm(A[0], A[1], B[0], B[1]);
    if (!isFinite(km) || km <= 0) return true;
    return km <= lim;
  } catch (e) { return true; }
}

