// Equipment codes that are uniquely ex-Hawaiian fleet (post April 22, 2026).
// Pualani livery is preserved on these frames per Alaska Air Group brand policy.
const _HAWAIIAN_EQUIP = ['717','32Q','21N','32B','332','339'];

// Equipment codes that are uniquely Alaska's mainland fleet — NEVER Hawaiian-painted.
// Even on a Hawaii route (e.g. SEA->HNL operated by AS 737), this is an Alaska frame.
const _ALASKA_MAINLAND_EQUIP = ['737','738','739','73G','73H','73J','7M7','7M8','7M9','E75','E7W','E70','789'];

// Returns true if an AS-marketed flight should be displayed with Hawaiian branding
// (banner logo, accent color, livery folder, watermark, ad set).
//
// Decision order (equipment is king):
//   1. If equipment matches Hawaiian fleet (717/A321neo/A330) -> Hawaiian, period.
//   2. If equipment matches Alaska mainland fleet (737/E175/787) -> Alaska, period.
//      This stops a route-based false-positive on a real Alaska 737 flying inter-island.
//   3. If equipment is unknown/ambiguous AND a Hawaii airport is involved -> Hawaiian.
//   4. Otherwise -> Alaska.
function isHawaiianBrandedFlight(flight, gateIata) {
  if (!flight) return false;
  var code = (flight.airline || '').trim().toUpperCase();
  if (code !== 'AS') return false;
  var equip = (flight._aircraftCode || '').toUpperCase();
  // Rule 1: equipment match wins
  if (equip && _HAWAIIAN_EQUIP.indexOf(equip) !== -1) return true;
  // Rule 2: known Alaska mainland equipment overrides route-based detection
  if (equip && _ALASKA_MAINLAND_EQUIP.indexOf(equip) !== -1) return false;
  // Rule 3: only when equipment is unknown/ambiguous, fall back to route
  var loc = (flight._locIata || '').toUpperCase();
  var here = (gateIata || '').toUpperCase();
  if (loc && _HAWAII_AIRPORTS.indexOf(loc) !== -1) return true;
  if (here && _HAWAII_AIRPORTS.indexOf(here) !== -1) return true;
  return false;
}

// Darken a hex color by mixing it with black (factor 0-1, lower=darker)
// Mix an airline accent color with a deep navy base to produce a tasteful
// tinted weather-panel background. Unlike darkenHex (which muddies bright reds
// into maroon), this keeps the hue recognizable but keeps the whole thing
// dark enough for white text to have good contrast.
function accentTint(hex, intensity) {
  hex = String(hex || '#0033A1').replace('#', '');
  if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
  var r = parseInt(hex.slice(0, 2), 16) || 0;
  var g = parseInt(hex.slice(2, 4), 16) || 0;
  var b = parseInt(hex.slice(4, 6), 16) || 0;
  // AC OVERRIDE: Air Canada red (#D82F2E, #C8102E) tinted looks like muddy maroon.
  // Force a neutral charcoal gradient instead to avoid that look.
  var isACRed = (r > 180 && g < 80 && b < 80);
  if (isACRed) {
    return 'linear-gradient(135deg, rgb(40,44,54) 0%, rgb(28,32,42) 100%)';
  }
  intensity = typeof intensity === 'number' ? intensity : 0.25; // 0..1
  var baseR = 14, baseG = 18, baseB = 32;
  var mixR = Math.round(baseR * (1 - intensity) + r * intensity);
  var mixG = Math.round(baseG * (1 - intensity) + g * intensity);
  var mixB = Math.round(baseB * (1 - intensity) + b * intensity);
  var darkR = Math.round(mixR * 0.75);
  var darkG = Math.round(mixG * 0.75);
  var darkB = Math.round(mixB * 0.75);
  return 'linear-gradient(135deg, rgb(' + mixR + ',' + mixG + ',' + mixB + ') 0%, rgb(' + darkR + ',' + darkG + ',' + darkB + ') 100%)';
}

