// Return a background URL for a given airline + flight number, or null if
// the airline has no branded backgrounds. The flight number seeds a
// deterministic pick so the same flight always gets the same background.
function getAirlineBackground(airlineCode, flightNum) {
  if (!airlineCode) return null;
  var pool = AIRLINE_BACKGROUNDS[String(airlineCode).toUpperCase()];
  if (!pool || !pool.length) return null;
  var n = parseInt(String(flightNum || '0').replace(/\D/g, ''), 10) || 0;
  return pool[Math.abs(n) % pool.length];
}

function darkenHex(hex, factor) {
  var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  r = Math.round(r * factor); g = Math.round(g * factor); b = Math.round(b * factor);
  return '#' + ((1<<24)|(r<<16)|(g<<8)|b).toString(16).slice(1);
}

