const AIRCRAFT_CATEGORY = {
  // Widebody
  '330':'widebody','332':'widebody','333':'widebody','339':'widebody',
  '350':'widebody','359':'widebody','351':'widebody',
  '380':'widebody','388':'widebody',
  '744':'widebody','748':'widebody',
  '763':'widebody','764':'widebody',
  '772':'widebody','773':'widebody','77W':'widebody','77L':'widebody',
  '787':'widebody','788':'widebody','789':'widebody','78J':'widebody',
  '752':'widebody','753':'widebody',
  // Regional
  'AT7':'regional','CR9':'regional','CR7':'regional','CR2':'regional',
  'DH4':'regional','DH3':'regional','DH8':'regional',
  'E75':'regional','E90':'regional','E95':'regional',
  'BCS':'regional','CS1':'regional',
  // Everything else → narrowbody (737s, A320s, A220-300, etc.)
};
function getAircraftCategory(code) {
  if (!code) return 'narrowbody';
  return AIRCRAFT_CATEGORY[code.toUpperCase()] || 'narrowbody';
}
function getBoardingLeadMins(aircraftCode) {
  var cat = getAircraftCategory(aircraftCode || '');
  // v22747 — the Q400 boards in 20 minutes, not the generic regional 25
  // (Nick, who works these gates: 'It's 20 minutes for the q400'). Covers
  // every code the feeds use for the Dash 8-400 — DH4 (IATA), DH8D (ICAO) —
  // and the -300/-100/-200 stay on the regional default.
  var _acU = String(aircraftCode || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (_acU === 'DH4' || _acU === 'DH8D' || _acU === 'Q400' || /DHC8400|DASH8400/.test(_acU)) return 20;
  if (cat === 'regional') return 25;
  if (cat === 'widebody') return 45;
  // Narrowbody - check if small (A319/A320) or large (737/A321)
  var upper = (aircraftCode || '').toUpperCase();
  if (upper === '319' || upper === '320' || upper === '32N' || upper === '32A' || upper === '318' || upper === '223' || upper === 'BCS' || upper === 'CS3') return 30;
  return 35; // default narrowbody (737, A321, etc.)
}

function getZoneCount(airlineCode, aircraftCode) {
  var cat = getAircraftCategory(aircraftCode);
  var config = AIRLINE_ZONES[airlineCode] || { narrowbody:4, widebody:4, regional:3, label:'Zone' };
  return config[cat] || config.narrowbody || 4;
}
