  if (/E[\s-]*195|ERJ[\s-]*195|E2[\s-]*195/i.test(s)) return 'E95';
  if (/E[\s-]*190|ERJ[\s-]*190/i.test(s)) return 'E90';
  if (/E[\s-]*175|ERJ[\s-]*175/i.test(s)) return 'E75';
  if (/E[\s-]*170|ERJ[\s-]*170/i.test(s)) return 'E7W';
  if (/E[\s-]*145|ERJ[\s-]*145/i.test(s)) return 'ER4';
  if (/E[\s-]*135|ERJ[\s-]*135/i.test(s)) return 'ER3';

