  // passed via opts (or equipRawOrCode is itself a full model), pick the
  // engine-specific file first; otherwise generic.
  var rawModel = opts.rawModel || (rawStr.length > 5 ? rawStr : '');
  var engineCode = engineVariantSuffix(rawModel, opts.reg);

