    const _pageStart = bView._bidsPage * BIDS_FLIGHTS_PER_PAGE;
    const _pageFlights = arrFlights.slice(_pageStart, _pageStart + BIDS_FLIGHTS_PER_PAGE);

    // Set up rotation timer (one per BIDS render lifetime)
