      if (_bScrProbe) {
        var _bLumM = getComputedStyle(_bScrProbe).backgroundColor.match(/rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/);
        if (_bLumM) _bWmVariant = (0.2126 * _bLumM[1] + 0.7152 * _bLumM[2] + 0.0722 * _bLumM[3]) > 150 ? 'dark' : 'light';
      }
