const WX_LABELS = {
  clear:{en:'CLEAR',fr:'DÉGAGÉ'},partcloud:{en:'PARTLY CLOUDY',fr:'SEMI-COUVERT'},
  cloudy:{en:'CLOUDY',fr:'NUAGEUX'},fog:{en:'FOG',fr:'BROUILLARD'},
  drizzle:{en:'DRIZZLE',fr:'BRUINE'},fzdrizzle:{en:'FZ. DRIZZLE',fr:'BRUINE VERGL.'},
  rain:{en:'RAIN',fr:'PLUIE'},hvyrain:{en:'HEAVY RAIN',fr:'FORTE PLUIE'},
  fzrain:{en:'FZ. RAIN',fr:'PLUIE VERGL.'},snow:{en:'SNOW',fr:'NEIGE'},
  hvysnow:{en:'HEAVY SNOW',fr:'FORTE NEIGE'},showers:{en:'SHOWERS',fr:'AVERSES'},
  snowshow:{en:'SNOW SHOWERS',fr:'AVERSES NEIGE'},tstorm:{en:'T-STORM',fr:'ORAGE'},
};
const wxLabel = (key) => (WX_LABELS[key]||{})[lang] || key;
const WX_KEY_CODE = {
  clear:0,partcloud:1,cloudy:3,fog:45,drizzle:51,fzdrizzle:56,
  rain:61,hvyrain:65,fzrain:66,snow:71,hvysnow:75,showers:80,snowshow:85,tstorm:95,
};

// All destination IATAs a flight's board row can display — the primary dest
// PLUS every through-flight leg (Nick: multi-city rows 'do not give us
// weather'). The dest chip flips leg-by-leg (_destFlipStops), but the weather
// fetch list only had f._locIata, so the non-primary legs had no weather to
// show when the row flipped to them. Resolve name-only legs to a code the same
// way _destFlipStops does, so TPA/YYZ via-stops are covered too.
function _flightWxCodes(f) {
  var out = [];
  try {
    if (f && f._locIata) out.push(String(f._locIata).toUpperCase());
    if (f && Array.isArray(f._stops)) {
      f._stops.forEach(function (s) {
        var ia = String((s && s.iata) || '').replace(/[^A-Za-z]/g, '').toUpperCase().slice(0, 3);
        if (!ia && typeof _iataFromCityName === 'function') ia = _iataFromCityName((s && s.city) || '');
        if (ia) out.push(ia);
      });
    }
  } catch (e) {}
  return out;
}

// Batch weather fetcher for board destinations
async function _fetchBoardWeather(codes) {
  var now = Date.now();
  var todo = codes.filter(function(c){ var x=TOMORROW_WX[c]; return !x||(now-x.ts>TOMORROW_TTL); });
  if (!todo.length) return;
  for (var i=0; i<todo.length; i+=4) {
    var batch = todo.slice(i, i+4);
    await Promise.all(batch.map(function(c){ return fetchTomorrowWeather(c); }));
    if (i+4 < todo.length) await new Promise(function(r){ setTimeout(r, 1000); });
  }
  if (typeof render === 'function') render();
}

// Weather-themed background gradient for panels
function wxBgGradient(code) {
  if (code===1000) return 'linear-gradient(135deg,#0f1628,#1a2744)';
  if (code>=1100&&code<=1103) return 'linear-gradient(135deg,#1a2030,#253550)';
  if (code===1001) return 'linear-gradient(135deg,#1c2333,#2a3548)';
  if (code>=2000&&code<=2100) return 'linear-gradient(135deg,#252d3a,#3a4555)';
  if (code>=3000&&code<=3002) return 'linear-gradient(135deg,#1a2535,#2a3d50)';
  if (code>=4000&&code<=4200) return 'linear-gradient(135deg,#171d2a,#252d3f)';
  if (code===4201) return 'linear-gradient(135deg,#111520,#1a2030)';
  if (code>=5000&&code<=5101) return 'linear-gradient(135deg,#202838,#354050)';
  if (code>=6000&&code<=6201) return 'linear-gradient(135deg,#1a2030,#2a3345)';
  if (code>=7000&&code<=7102) return 'linear-gradient(135deg,#1a2030,#2a3345)';
  if (code===8000) return 'linear-gradient(135deg,#12101e,#1e1a35)';
  return 'linear-gradient(135deg,#0f1628,#1a2744)';
}

