function tioIcon(weatherCode, size) {
  // Prefer the inline SVG-sprite icon used by the FIDS board (fidsWxIcon).
  // The legacy meteoconImg path points at an external PNG CDN that 404s on
  // the gate screens, leaving broken-image placeholders. fidsWxIcon accepts
  // the same numeric Tomorrow.io/WMO code and renders the same icon set the
  // board uses, so gate weather now matches the board exactly.
  if (typeof window !== 'undefined' && typeof window.fidsWxIcon === 'function') {
    return window.fidsWxIcon(weatherCode, size || 48);
  }
  const name = TIO_ICON[weatherCode] || 'clear-day';
  return meteoconImg(name, size || 48);
}
// Expose the WMO/Tomorrow.io code → name map to window so the v2 weather
// helper (in fids-v2.js) can translate numeric codes from the data feed
// into our flat-icon sprite cell names.
if (typeof window !== 'undefined') window.TIO_ICON = TIO_ICON;

function tioLabel(weatherCode) {
  const labels = (typeof lang !== 'undefined' && lang === 'fr') ? TIO_LABEL_FR : TIO_LABEL;
  if (labels[weatherCode]) return labels[weatherCode];
  if (TIO_LABEL[weatherCode]) return TIO_LABEL[weatherCode];
  return '';
}

// ── Open-Meteo fallback (keyless, no quota) ────────────────────────────
// Tomorrow.io's free quota can die mid-day and the whole WEATHER column
// went '—' until it reset (Nick: 'weather doesn't work actually, on FIDS').
// Open-Meteo returns WMO codes, which TIO_ICON already maps natively; the
// worker's /wxdaily route set the precedent for leaning on it.
async function _fetchOpenMeteoWx(iata) {
  try {
    if (!COORDS[iata]) return null;
    var lat = COORDS[iata][0], lon = COORDS[iata][1];
    var r = await fetch('https://api.open-meteo.com/v1/forecast?latitude=' + lat + '&longitude=' + lon
      + '&current=temperature_2m,apparent_temperature,weather_code,wind_speed_10m,relative_humidity_2m'
      + '&hourly=temperature_2m,weather_code&forecast_days=2&timezone=UTC');
    if (!r.ok) return null;
    var d = await r.json();
    if (!d || !d.current || typeof d.current.temperature_2m !== 'number') return null;
    var hourly = [];
    try {
      var ht = (d.hourly && d.hourly.time) || [];
      for (var i = 0; i < ht.length; i++) {
        hourly.push({ time: ht[i], ts: new Date(ht[i] + ':00Z').getTime(),
                      temp: d.hourly.temperature_2m[i], code: d.hourly.weather_code[i] });
      }
    } catch (e2) {}
    TOMORROW_WX[iata] = {
      current: {
        temp: d.current.temperature_2m,
        feelsLike: d.current.apparent_temperature,
        code: d.current.weather_code,
        windSpeed: d.current.wind_speed_10m,
        humidity: d.current.relative_humidity_2m,
      },
      hourly: hourly,
      ts: Date.now(),
      _src: 'open-meteo',
    };
    console.log('[WX-OM] ✓ Open-Meteo fallback for', iata, Math.round(d.current.temperature_2m) + '°C');
    return TOMORROW_WX[iata];
  } catch (e) { return null; }
}

async function fetchTomorrowWeather(iata) {
  if (!COORDS[iata]) { console.warn('[TIO] No coords for', iata); return null; }
  const now = Date.now();
  const cached = TOMORROW_WX[iata];
  if (cached && (now - cached.ts < TOMORROW_TTL)) return cached;

  // Rate limit backoff — if we got 429'd, go straight to the keyless
  // fallback for 5 minutes instead of showing '—'.
  if (window._tioRateLimited && (now - window._tioRateLimited < 5 * 60000)) {
    return (await _fetchOpenMeteoWx(iata)) || cached || null;
  }

  try {
    const [lat, lon] = COORDS[iata];
    console.log('[TIO] Fetching weather for', iata, 'at', lat, lon);
    const rtRes = await fetch(`https://fids-proxy.n-leblanc1984.workers.dev/weather/realtime?location=${lat},${lon}&units=metric`);

    if (rtRes.status === 429) {
      console.warn('[TIO] Rate limited (429) — backing off 5 minutes, using Open-Meteo');
      window._tioRateLimited = now;
      return (await _fetchOpenMeteoWx(iata)) || cached || null;
    }

    if (!rtRes.ok) {
      const errText = await rtRes.text().catch(() => '');
      console.warn('[TIO] HTTP', rtRes.status, 'for', iata, errText.substring(0, 200));
      return (await _fetchOpenMeteoWx(iata)) || cached || null;
    }

    const rtData = await rtRes.json();
    const current = rtData.data?.values || {};

    if (current.temperature == null) {
      console.warn('[TIO] No temperature in response for', iata);
      return (await _fetchOpenMeteoWx(iata)) || cached || null;
    }

    TOMORROW_WX[iata] = {
      current: {
        temp: current.temperature,
        feelsLike: current.temperatureApparent,
        code: current.weatherCode,
        windSpeed: current.windSpeed,
        windDir: current.windDirection,
        windGust: current.windGust,
        humidity: current.humidity,
        visibility: current.visibility,
        precip: current.precipitationProbability,
        cloudCover: current.cloudCover,
        cloudCeiling: current.cloudCeiling,
        pressure: current.pressureSeaLevel,
        altimeter: current.altimeterSetting,
      },
      hourly: TOMORROW_WX[iata]?.hourly || [],
      ts: now,
    };

    console.log('[TIO] ✓ Weather loaded for', iata, Math.round(current.temperature) + '°C', tioLabel(current.weatherCode));

    // Fetch hourly forecast in background (non-blocking)
    fetch(`https://fids-proxy.n-leblanc1984.workers.dev/weather/forecast?location=${lat},${lon}&timesteps=1h&units=metric`)
      .then(r => {
        if (r.status === 429) { window._tioRateLimited = Date.now(); return null; }
        return r.ok ? r.json() : null;
      })
      .then(fcData => {
        if (!fcData || !fcData.timelines) return;
        TOMORROW_WX[iata].hourly = (fcData.timelines.hourly || []).map(h => ({
          time: h.time,
          ts: new Date(h.time).getTime(),
          temp: h.values?.temperature,
          feelsLike: h.values?.temperatureApparent,
          code: h.values?.weatherCode,
          windSpeed: h.values?.windSpeed,
          windDir: h.values?.windDirection,
          windGust: h.values?.windGust,
          humidity: h.values?.humidity,
          visibility: h.values?.visibility,
          precip: h.values?.precipitationProbability,
          cloudCover: h.values?.cloudCover,
          cloudCeiling: h.values?.cloudCeiling,
        }));
        console.log('[TIO] ✓ Hourly forecast loaded for', iata, TOMORROW_WX[iata].hourly.length, 'hours');
        var wxEl = document.getElementById('gateWxStrip');
        var cf = window._gateCurrentFlight;
        if (wxEl && cf) {
          var arrTs = cf._arrTs || (cf._sortTs ? cf._sortTs + (cf._durationMins||0)*60000 : 0);
          wxEl.innerHTML = gateWeatherWidget(window._gateIata || iata, cf._locIata || '', arrTs);
          wxEl.style.display = 'flex';
        }
      })
      .catch(e => console.warn('[TIO] Hourly forecast error for', iata, e.message));

    return TOMORROW_WX[iata];
  } catch(e) {
    console.warn('[TIO] Fetch error for', iata, ':', e.message);
    return (await _fetchOpenMeteoWx(iata)) || cached || null;
  }
}

// Get forecast for a specific arrival timestamp
function tioArrivalWeather(iata, arrivalTs) {
  const data = TOMORROW_WX[iata];
  if (!data || !data.hourly || !data.hourly.length || !arrivalTs) return null;
  // Find the hourly entry closest to arrival time
  let best = data.hourly[0];
  let bestDiff = Math.abs(best.ts - arrivalTs);
  for (const h of data.hourly) {
    const diff = Math.abs(h.ts - arrivalTs);
    if (diff < bestDiff) { best = h; bestDiff = diff; }
  }
  // Only use if within 2 hours of the actual arrival
  if (bestDiff > 2 * 3600000) return null;
  return best;
}

// Build gate screen weather HTML for idle mode strip
function gateWeatherWidget(depIata, destIata, arrivalTs) {
  let html = '';
  const depWx = TOMORROW_WX[depIata];
  const destWx = TOMORROW_WX[destIata];
  let hasAny = false;

  // City name helper — "Toronto YYZ" style
  function wxCityLabel(iataCode) {
    var city = CITY[iataCode] || (AP[iataCode]||{}).city || '';
    if (city) return tc(city) + ' ' + iataCode;
    return iataCode || '';
  }

  // Tomorrow.io dest panel — IDENTICAL to dep panel style (same function-body, same sizes).
  // Uses airline accent tint so both dep/dest panels match the carrier's color identity.
  function tioPanelHtml(iataCode, label, wxData) {
    var _accent = (typeof window._gateAccent !== 'undefined') ? window._gateAccent : '#0033A1';
    var wxBg = accentTint(_accent, 0.28);
    // Always render the feels-like line for alignment parity with the dep wx panel
    var _feelsRow = '<div style="font-size:14px;color:rgba(255,255,255,0.72);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-height:19px;">';
    if (wxData.feelsLike !== undefined && !isNaN(wxData.feelsLike)) {
      _feelsRow += TL('feelsLike') + ' ' + displayTemp(Math.round(wxData.feelsLike));
      if (wxData.windSpeed !== undefined && !isNaN(wxData.windSpeed)) {
        _feelsRow += ' \u00B7 ' + Math.round(wxData.windSpeed) + ' km/h';
      }
    } else {
      _feelsRow += '&nbsp;';
    }
    _feelsRow += '</div>';
    return '<div style="width:100%;height:100%;display:flex;align-items:center;gap:16px;padding:18px 22px;border:none;border-radius:0;margin:0;background:' + wxBg + ';box-sizing:border-box;">'
      + tioIcon(wxData.code, 76)
      + '<div style="min-width:0;flex:1;overflow:hidden;">'
      + '<div style="font-size:15px;font-weight:700;color:rgba(255,255,255,0.9);letter-spacing:0.3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + wxCityLabel(iataCode) + '</div>'
      + '<div style="font-size:44px;font-weight:800;color:#fff;line-height:1.05;">' + displayTemp(Math.round(wxData.temp)) + '</div>'
      + '<div style="font-size:18px;font-weight:600;color:rgba(255,255,255,0.9);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + tioLabel(wxData.code) + '</div>'
      + _feelsRow
      + '</div></div>';
  }



  // Try Tomorrow.io arrival hour first, then TIO current
  if (destWx && arrivalTs) {
    const arr = tioArrivalWeather(destIata, arrivalTs);
    if (arr && arr.temp !== undefined) {
      hasAny = true;
      const arrTime = new Date(arr.ts).toLocaleTimeString('en-US', { hour:'2-digit', minute:'2-digit', hour12:true });
      html += tioPanelHtml(destIata, '@ ' + arrTime, arr);
    } else if (destWx.current && destWx.current.temp !== undefined) {
      hasAny = true;
      html += tioPanelHtml(destIata, TL('now'), destWx.current);
    }
  } else if (destWx && destWx.current && destWx.current.temp !== undefined) {
    hasAny = true;
    html += tioPanelHtml(destIata, TL('now'), destWx.current);
  }

  // If no data from either source, show loading placeholder
  if (!hasAny) {
    html = '<div class="g8-wx-panel" style="opacity:0.3;justify-content:center;width:100%;"><div class="g8-wx-info" style="align-items:center;"><div class="g8-wx-label" style="letter-spacing:2px;">WEATHER</div><div class="g8-wx-detail" style="font-size:11px;">Loading...</div></div></div>';
  }

  return html;
}

// Tick the hotel strip rotation — called on the same minute interval that
// refreshes other gate elements. Cycles to the next brand slide.
function tickHotelStrip() {
  var strip = document.getElementById('gateHotelStrip');
  if (!strip) return;
  var slides = strip.querySelectorAll('.g8-hotel-slide');
  if (slides.length < 2) return;
  var activeIdx = -1;
  slides.forEach(function(s, i) { if (s.classList.contains('active')) activeIdx = i; });
  var nextIdx = (activeIdx + 1) % slides.length;
  if (activeIdx >= 0) slides[activeIdx].classList.remove('active');
  slides[nextIdx].classList.add('active');
}


