  'JBU':'B6', 'ASA':'AS', 'FFT':'F9',
  'AAY':'G4', 'HAL':'HA', 'SCX':'SY',
  // ── US regionals (all keep their own IATA for logo purposes) ──
  'SKW':'OO', 'ENY':'MQ', 'JIA':'OH', 'PDT':'PT', 'EDV':'9E',
  'ASH':'YV', 'GJS':'G7', 'RPA':'YX', 'QXE':'QX', 'UCA':'C5',
