  // ── Hawaii inter-island regional ──
  'MHO':'9X', 'SOU':'9X',  // Mokulele (Surf Air Mobility / Southern Airways Express)
  // ── European (most common) ──
  'DLH':'LH', 'BAW':'BA', 'AFR':'AF', 'KLM':'KL',
  'VIR':'VS', 'ITY':'AZ', 'BEL':'SN', 'SWR':'LX',
  'AUA':'OS', 'SAS':'SK', 'FIN':'AY', 'IBE':'IB',
