// ── BULLETPROOF HYBRID LOGO FOR WESTJET ──────────────────────────────────
// This uses the official Google Flights icon perfectly paired with the exact WestJet dark-blue text. 
// It cannot be blocked by firewalls and matches the new branding identically.
const HARDCODED_LOGOS = {
};

// Local transparent-background SVG logos — used by mkLogo() (FIDS board)
// as the FIRST choice before falling back to wway.io or Google.
// This is an ALIAS for LOCAL_LOGOS so the gate screen and FIDS board
// use the same file for each carrier. To update a file, edit LOCAL_LOGOS.
const LOCAL_TRANSPARENT_LOGOS = LOCAL_LOGOS;

var _logoFailCache = {};
function logoFallback(img) {
  const c = img.dataset.code;
  const name = img.alt;
  const t = img.dataset.tried || '0';
  if (t === '0') {
    // First wway URL failed — try the higher-res wway variant
    img.dataset.tried = '1';
    img.src = wwayUrl(c, 400, 80);
  } else if (t === '1') {
    // Second wway URL failed — try Google Flights' logo CDN
    img.dataset.tried = '2';
    img.src = 'https://www.gstatic.com/flights/airline_logos/90px/' + c + '.png';
  } else if (t === '2' && IATA_TO_TILE_ICAO[c]) {
    // gstatic failed too — fall back to the airline tile (colored square).
    // We only do this if a tile exists for this carrier; otherwise we'd
    // chase a 404. The tile is square with brand color background, so we
    // also flip data-logo-set to 'tile' so the CSS shows the name span
    // alongside (since the tile itself doesn't read as a wordmark).
    img.dataset.tried = '3';
    img.dataset.logoSet = 'tile';
    img.src = '/logos/airline-tiles/' + IATA_TO_TILE_ICAO[c] + '.svg';
  } else if (t === '3' && IATA_TO_TILE_ICAO[c]) {
    // airline-tiles failed too (e.g. file missing) — try the icao-icons
    // archive folder as a deep-fallback. icao-icons/ is a backup copy of
    // airline-tiles/ from the AirlineIcons-main source pack. Only useful
    // if airline-tiles/{ICAO}.svg got deleted or corrupted but the
    // archive copy survived.
    img.dataset.tried = '4';
    img.dataset.logoSet = 'tile';
    img.src = '/logos/icao-icons/' + IATA_TO_TILE_ICAO[c] + '.svg';
  } else {
    // All sources exhausted — MONOGRAM tile, not bare text (Nick: text/
    // wordmark in the emblem slot 'doesn't work'). Cache so later renders
    // go straight to the monogram without re-chasing dead URLs.
    if (c) _logoFailCache[c] = true;
    img.outerHTML = (typeof _monogramTile === 'function')
      ? _monogramTile(c, name)
      : `<span class="logo-fallback">${name}</span>`;
  }
}

