// Resolve a logo basename (e.g. "air-canada.svg") to its full path.
// If the file is in LOGO_SUBFOLDER, return /logos/{subfolder}/{name}.
// Otherwise assume root /logos/{name}.
function logoPath(basename) {
  if (!basename) return basename;
  const sub = LOGO_SUBFOLDER[basename];
  return sub ? '/logos/' + sub + '/' + basename : '/logos/' + basename;
}
