function wordmarkSrc(base, forceVariant) {
  // v191: route through logoPath() so reorganized logos resolve correctly
  // forceVariant: per-context override ('dark'|'light') for surfaces whose
  // background is NOT the measured board (e.g. baggage rows are always dark
  // navy, and a state-tinted row needs the dark-ink artwork regardless).
  const _variant = forceVariant || wordmarkVariant();
  if (WORDMARK_RASTER[base]) {
    return WORDMARK_RASTER[base][_variant === 'dark' ? 'dark' : 'light']
      + '?v=' + (typeof FIDS_BUILD_TAG !== 'undefined' ? encodeURIComponent(FIDS_BUILD_TAG) : (typeof FIDS_BUILD !== 'undefined' ? encodeURIComponent(FIDS_BUILD) : '1'));
  }
  if (_variant === 'dark' && COLOR_WORDMARKS[base]) {
    return COLOR_WORDMARKS[base] + '?v=' + (typeof FIDS_BUILD_TAG !== 'undefined' ? encodeURIComponent(FIDS_BUILD_TAG) : (typeof FIDS_BUILD !== 'undefined' ? encodeURIComponent(FIDS_BUILD) : '1'));
  }
  const fname = base + '-wordmark-' + _variant + '.svg';
  // Cache token: un-versioned wordmark URLs let a transient 404 (e.g. a brief
  // deploy window) get cached by the browser FOREVER — every board render then
  // fires onerror and shows the text-name fallback instead of the wordmark,
  // and kiosk displays can't be hard-refreshed. A build-tied token makes every
  // deploy mint fresh URLs, so poisoned caches self-heal.
  return logoPath(fname) + '?v=' + (typeof FIDS_BUILD_TAG !== 'undefined' ? encodeURIComponent(FIDS_BUILD_TAG) : (typeof FIDS_BUILD !== 'undefined' ? encodeURIComponent(FIDS_BUILD) : '1'));
}

// WCAG relative luminance of a #hex colour (0 = black … 1 = white). Used to
// decide whether a carrier's brand accent is legible as the TEXT name on the
// dark board — a deep maroon/navy (Qatar #5c0931, Emirates crimson) reads as
// an unreadable smudge or an alarm state, not a brand (Nick: 'Qatar', earlier
// 'Emirates shouldn't be red').
function _hexLum(hex) {
  try {
    hex = String(hex).replace('#', '');
    if (hex.length === 3) hex = hex.split('').map(function (c) { return c + c; }).join('');
    if (hex.length < 6) return 1;
    var toLin = function (v) { v = v / 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
    var r = toLin(parseInt(hex.slice(0, 2), 16));
    var g = toLin(parseInt(hex.slice(2, 4), 16));
    var b = toLin(parseInt(hex.slice(4, 6), 16));
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  } catch (e) { return 1; }
}

// IATA → emblem-only icon URL. Used by mkLogo() to populate the emblem
// slot for carriers whose primary symbol is an icon/illustration (not a
// solid tile). Distinct from IATA_TO_TILE_ICAO (square-tile carriers like
// AA's eagle box) and from IATA_TO_WORDMARK (text portion). When both an
// emblem and a wordmark exist, the row shows: [emblem] [wordmark text].
const IATA_TO_EMBLEM = {
  'JV': '/logos/airlines/canadian-regional/bearskin-emblem.svg',      // Bearskin bear-paw emblem
  'WT': '/logos/airlines/canadian-regional/wasaya-emblem.svg',        // Wasaya emblem
  'NSA': '/logos/airlines/canadian-regional/north-star-emblem.svg',   // North Star Air emblem
  '9X': '/logos/airlines/us-major/mokulele-emblem.svg',  // Mokulele plumeria flower
  '4Y': '/logos/airlines/european/discover-airlines-emblem.svg',  // Discover Airlines tail-fin emblem (yellow + blue gradient)
  'F9': '/logos/airlines/us-major/frontier-emblem.svg',  // Frontier Airlines green stylized "F" mark
  'XP': '/logos/airlines/us-major/avelo-emblem.svg',     // Avelo Airlines tail mark
  'LL': '/logos/airlines/european/level-emblem.svg',     // LEVEL block mark
  'MX': '/logos/airlines/us-major/breeze-airways-emblem.png',  // Breeze checkmark on navy square
  'VB': '/logos/airlines/asian-other/vivaaerobus-emblem.webp',  // Viva green leaf-shape "a" emblem
  'BW': '/logos/airlines/asian-other/caribbean-emblem.png',     // Caribbean hummingbird (official brand art; no tile exists)
  // US majors — these render wordmark-alone (TILE_SKIP_WORDMARK_ONLY), but the
  // wordmark text by itself loses the iconic brand symbol. Show the symbol in
  // the emblem slot ALONGSIDE the existing wordmark (wordmark text untouched).
  'DL': '/logos/airlines/us-major/delta-widget.svg',           // Delta red/blue widget
  'HA': '/logos/airlines/us-major/hawaiian-pualani.svg',       // Hawaiian Pualani (flower woman)
  'AA': '/logos/airlines/us-major/american-flight-symbol.svg', // American flight symbol (eagle)
  'UA': '/logos/airlines/us-major/united-globe-only.svg',      // United globe
};


/* Carriers to render as wordmark-alone (skip colored tile). Emptied Jul 2026:
   Nick wants every carrier to carry its icon ("JetBlue doesnt have a icon") —
   B6 gets the navy JBU tile back, AS the ASA tile. Keep the mechanism. */
var TILE_SKIP_WORDMARK_ONLY = new Set([]);

// Monogram tile — LAST-RESORT emblem for carriers with no artwork anywhere
// (Nick: a bare wordmark/text in the emblem slot 'doesn't work'). A brand-
// accent square with the carrier code keeps the board's tile rhythm.
function _monogramTile(code, name) {
  var c = String(code || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  var acc = (typeof AIRLINE_BRAND !== 'undefined' && AIRLINE_BRAND[c] && AIRLINE_BRAND[c].accent) || '';
  if (!acc) {
    // Deterministic muted hue from the code — same carrier, same colour, every render.
    var h = 0; for (var i = 0; i < c.length; i++) h = (h * 31 + c.charCodeAt(i)) % 360;
    acc = 'hsl(' + h + ',45%,32%)';
  }
  var txt = (c || String(name || '?').replace(/[^A-Za-z0-9]/g, '')).slice(0, 2).toUpperCase() || '?';
  return '<div class="full-logo logo-monogram" data-code="' + c + '" style="background:' + acc + ';">' + txt + '</div>';
}

function mkLogo(code, faName) {
  const c = (code || '').trim().toUpperCase();
  const displayName = AIRLINE_NAME[c] || faName || c;

  // Skip img entirely if all sources already failed for this airline
  if (_logoFailCache[c]) {
    return _monogramTile(c, displayName);
  }
  
  // If we have a local wordmark for this carrier, the right-hand wordmark
  // image will provide the carrier identity. Only show the colored tile
  // (square brand symbol) here; skip any other lockup that would duplicate
  // the wordmark text. For carriers with no tile, return empty so the
  // wordmark stands alone.
  if (IATA_TO_WORDMARK[c]) {
    /* TEMP (logo cleanup): these carriers have a clean separate wordmark that
       already renders in the row, so skip the redundant colored tile and let
       the wordmark stand alone. WN kept out — it has no separate wordmark. */
    if (IATA_TO_TILE_ICAO[c] && !TILE_SKIP_WORDMARK_ONLY.has(c)) {
      return `<img class="full-logo" data-code="${c}" data-logo-set="tile" alt="${displayName}" src="/logos/airline-tiles/${IATA_TO_TILE_ICAO[c]}.svg" onerror="logoFallback(this)">`;
    }
    // v188: emblem map — for airlines whose primary visual is an icon/symbol
    // (not a tile background), show that icon in the emblem slot alongside
    // the wordmark. Mokulele's plumeria flower is the canonical example.
    if (IATA_TO_EMBLEM[c]) {
      return `<img class="full-logo airline-emblem" data-code="${c}" data-logo-set="emblem" alt="${displayName}" src="${IATA_TO_EMBLEM[c]}" onerror="this.style.display='none'">`;
    }
    return ''; // no tile, wordmark alone
  }
  
  if (HARDCODED_LOGOS[c]) {
    return `<div class="full-logo" style="display:flex; align-items:center; justify-content:center;">${HARDCODED_LOGOS[c].replace(/height:\d+px/, 'height:50px').replace(/style="/, 'style="max-width:170px; ')}</div>`;
  }
  
  // Prefer local transparent-background logo if we have one. This avoids
  // the Google fallback (gstatic.com airline_logos/*.png have a WHITE
  // background baked in, which looks awful on dark FIDS boards).
  // If the carrier's logo is intrinsically full-color, render as-is.
  // Otherwise it likely needs to be inverted to white on dark rows.
  const _invertAttr = LOGO_SKIP_FILTER.has(c) ? '' : ' data-needs-invert="1"';
  
  // PRIORITY 1: Airline tile — square colored background with white logo.
  // Uniform branded look for the FIDS row. Look up by IATA→ICAO map.
  // The airline-name text label shows next to this since the tile is just
  // a square symbol and benefits from being labeled.
  if (IATA_TO_TILE_ICAO[c]) {
    return `<img class="full-logo" data-code="${c}" data-logo-set="tile" alt="${displayName}" src="/logos/airline-tiles/${IATA_TO_TILE_ICAO[c]}.svg" onerror="logoFallback(this)">`;
  }
  
  // PRIORITY 2: existing local transparent wordmark (legacy).
  // These are full lockups (logo+name) so the separate text label is
  // suppressed — data-logo-set="wordmark" triggers the CSS rule that
  // hides .fids-airline-name when this attr is present on the img.
  if (LOCAL_TRANSPARENT_LOGOS[c]) {
    return `<img class="full-logo" data-code="${c}"${_invertAttr} data-logo-set="wordmark" alt="${displayName}" src="${LOCAL_TRANSPARENT_LOGOS[c]}" onerror="logoFallback(this)">`;
  }
  
  // PRIORITY 3: external wway.io fallback. Also full lockups, so same
  // treatment — hide the redundant text label.
  // v196: skip wway.io entirely for IATA codes that have been historically
  // recycled — wway.io serves the OLD carrier's logo. Add codes here as we
  // discover them: 4Y (Yute Air → Discover Airlines, 2017→2023).
  const STALE_WWAY = new Set(['4Y']);
  if (STALE_WWAY.has(c)) {
    return _monogramTile(c, displayName);
  }
  const src = 'https://img.wway.io/pics/root/' + logoCode(c) + '@svg';
  return `<img class="full-logo" data-code="${c}"${_invertAttr} data-logo-set="wordmark" alt="${displayName}" src="${src}" onerror="logoFallback(this)">`;
}

