function displayTemp(c) {
  if (tempUnit === 'F') return Math.round(c * 9/5 + 32) + '°F';
  return c + '°C';
}

// Title case converter for city names and labels
// Province / state / country codes that should stay fully uppercase when they
// appear as a trailing token on a city name (e.g. "Sydney NS", "New York NY").
const _UPPER_TOKENS = new Set([
  // Canadian provinces / territories
  'NS','NB','PE','QC','ON','MB','SK','AB','BC','YT','NT','NU','NL',
  // US states
  'AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VT','VA','WA','WV','WI','WY','DC',
  // Common country trailing codes
  'UK','US','USA','UAE'
]);
function tc(s) {
  if (!s) return '';
  // Title case: capitalize after space, dash, slash, period
  var r = s.toLowerCase().replace(/(^|[\s\-\/\.])(\S)/g, (m,p,c) => p + c.toUpperCase());
  // Protect "St." / "Ste." — both English "Saint" and French "Sainte"
  // "St." or "St"-prefix names: only when followed by a space+letter (e.g. "St John")
  // — NOT when "St" is part of another word like "Stockholm".
  r = r.replace(/\bSt\.\s*([a-z])/g, (m,c) => 'St. ' + c.toUpperCase());
  // No catch-all "St" prefix rule — too aggressive, broke "Stockholm" → "St. Ockholm"
  r = r.replace(/\bSte\.\s*([a-z])/g, (m,c) => 'Ste. ' + c.toUpperCase());
  // Protect "Mc" and "Mac" prefixes
  r = r.replace(/\bMc([a-z])/g, (m,c) => 'Mc' + c.toUpperCase());
  // Preserve trailing region/state/province codes as uppercase
  r = r.replace(/(\s)([A-Za-z]{2,3})$/, function(m, sp, tok) {
    return sp + (_UPPER_TOKENS.has(tok.toUpperCase()) ? tok.toUpperCase() : tok);
  });
  return r;
}

// normalizeDisplayCity(raw, [iata]) — cleans data-source city strings so UI labels
// don't show ugly duplicates like "Toronto-YYZ" or "Atlanta (ATL) ATL".

function airportCityNameSafe_v21877(code, langOverride) {
  var c = String(code || '').replace(/[^A-Za-z]/g, '').toUpperCase().slice(0, 3);
  if (!c) return '';
  var langX = langOverride || (typeof getLang === 'function' ? getLang() : (typeof lang !== 'undefined' ? lang : 'en'));
  var city = '';
  if (langX === 'fr' && typeof CITY_FR !== 'undefined' && CITY_FR[c]) city = CITY_FR[c];
  if (!city && langX === 'es' && typeof CITY_ES !== 'undefined' && CITY_ES[c]) city = CITY_ES[c];
  if (!city && typeof CITY !== 'undefined' && CITY[c]) city = CITY[c];
  if (!city && typeof AP !== 'undefined' && AP[c] && AP[c].city) city = AP[c].city;
  return city || '';
}

// A trailing 3-letter word is only an airport code if we actually know it —
// otherwise it's part of the city name ("Goose Bay", "Medicine Hat", "La Paz").
function _isRealApCode(code) {
  var c = String(code || '').toUpperCase();
  if (!/^[A-Z]{3}$/.test(c)) return false;
  if (typeof CITY !== 'undefined' && CITY[c]) return true;
  if (typeof CITY_FR !== 'undefined' && CITY_FR[c]) return true;
  if (typeof CITY_ES !== 'undefined' && CITY_ES[c]) return true;
  if (typeof AP !== 'undefined' && AP[c]) return true;
  if (typeof GATE_AP !== 'undefined' && GATE_AP[c]) return true;
  if (typeof AIRPORT_COORDS !== 'undefined' && AIRPORT_COORDS[c]) return true;
  return false;
}

function normalizeDisplayCity(raw, iata) {
  var s = String(raw || '').replace(/\s+/g, ' ').trim();
  if (!s || s === '—') return s;

  var code = String(iata || '').replace(/[^A-Za-z]/g, '').toUpperCase().slice(0, 3);

  // If the supplied city is actually just the airport code, look up the city.
  // Examples: YYZ -> Toronto, SEA -> Seattle, PDX -> Portland.
  if (code && s.replace(/[^A-Za-z]/g, '').toUpperCase() === code) {
    var looked = airportCityNameSafe_v21877(code);
    if (looked) s = looked;
  }

  // If no code is supplied and the whole value is just one airport code, look it up.
  if (!code && /^[A-Za-z]{3}$/.test(s)) {
    code = s.toUpperCase();
    var looked2 = airportCityNameSafe_v21877(code);
    if (looked2) s = looked2;
  }

  // If no separate code was supplied, accept only explicit code formatting —
  // and only codes we recognize, so "Goose Bay" never parses as "Goose (BAY)".
  if (!code) {
    var mp = s.match(/^(.+?)\s*\(\s*([A-Za-z]{3})\s*\)$/);
    if (mp && !_isRealApCode(mp[2])) {
      // "(BAY)" is part of the name, not a code — fold it back in.
      s = (mp[1] + ' ' + mp[2]).replace(/\s+/g, ' ').trim();
      mp = null;
    }
    var m = mp || s.match(/^(.+?)(?:\s+|-|\/|,)\s*([A-Za-z]{3})$/);
    if (m && (mp || _isRealApCode(m[2]))) code = String(m[2] || '').toUpperCase();
  }

  // Remove only explicit duplicate copies of the same code.
  // IMPORTANT: no bare suffix rule. This will NOT turn Miami into Mi.
  if (code) {
    var esc = code.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    var changed = true;
    while (changed) {
      var before = s;
      s = s.replace(new RegExp('\\s*\\(\\s*' + esc + '\\s*\\)\\s*$', 'i'), '').trim();
      s = s.replace(new RegExp('[\\s\\-/,]+' + esc + '\\s*$', 'i'), '').trim();
      changed = s !== before;
    }
  }

  s = s.replace(/\s*[-–—]\s*$/, '').trim();

  // If cleaning left just the code, recover the city.
  if (code && (!s || s.replace(/[^A-Za-z]/g, '').toUpperCase() === code)) {
    s = airportCityNameSafe_v21877(code) || s;
  }

  return (typeof tc === 'function') ? tc(s) : s;
}

// ── v22736: THE CODE CHIP WHEN THE FEED DOESN'T CARRY ONE ────────────────
// Nick, on the live Tampa board: Breeze's 'Raleigh/Durham' and
// 'Gulfport/Biloxi' rows showed NO airport code while every other row on the
// same screen had one — 'They dont have a code no' confirmed the feed simply
// omits it for those flights. The city name is resolved back to its IATA from
// our own airport tables so those rows read like the rest of the board.
//
// AMBIGUOUS NAMES ARE NEVER GUESSED. 'Houston' is both IAH and HOU (Nick
// asked about exactly this pair), 'Portland' is PDX and PWM, 'Columbus' and
// 'Charleston' repeat too. Any name that resolves to more than one code is
// poisoned in the index and stays code-less — a missing chip is a small
// blemish, a WRONG airport code on a departure board is a passenger in the
// wrong city.
var _CITY2IATA = null;
// Feed phrasings that aren't in our display tables at all (their airports had
// no entry, which is why these rows arrived raw and code-less).
var _CITY2IATA_ALIAS = {
  gulfportbiloxi: 'GPT', gulfport: 'GPT',
  bentonvillefayetteville: 'XNA', northwestarkansas: 'XNA',
  pensacola: 'PNS', syracuse: 'SYR',
  raleighdurham: 'RDU', raleighdurhamnc: 'RDU'
};
function _normCityKey(s) {
  return String(s || '').toLowerCase().replace(/[^a-z]/g, '');
}
function _iataFromCityName(name) {
  var k = _normCityKey(name);
  if (k.length < 3) return '';
  if (!_CITY2IATA) {
    _CITY2IATA = {};
    var add = function (code, nm) {
      var kk = _normCityKey(nm);
      if (!kk || kk.length < 3) return;
      if (!_CITY2IATA[kk]) _CITY2IATA[kk] = String(code).toUpperCase();
      else if (_CITY2IATA[kk] !== String(code).toUpperCase()) _CITY2IATA[kk] = '!'; // ambiguous — never resolve
    };
    try { if (typeof AP_LIST !== 'undefined' && AP_LIST.forEach) AP_LIST.forEach(function (a) { if (a && a.c && a.n) add(a.c, a.n); }); } catch (e) {}
    try { if (typeof CITY !== 'undefined') Object.keys(CITY).forEach(function (c) { add(c, CITY[c]); }); } catch (e) {}
    try { if (typeof CITY_FR !== 'undefined') Object.keys(CITY_FR).forEach(function (c) { add(c, CITY_FR[c]); }); } catch (e) {}
  }
  if (_CITY2IATA_ALIAS[k]) return _CITY2IATA_ALIAS[k];
  var hit = _CITY2IATA[k];
  return (hit && hit !== '!') ? hit : '';
}

function formatCityIata(raw, iata, langOverride) {
  var rawStr = String(raw || '').replace(/\s+/g, ' ').trim();
  var code = String(iata || '').replace(/[^A-Za-z]/g, '').toUpperCase().slice(0, 3);

  // Handle malformed code-only labels: YYZ(YYZ), YYZ (YYZ), (YYZ)
  if (!code) {
    var cc = rawStr.match(/^\s*([A-Za-z]{3})\s*\(\s*([A-Za-z]{3})\s*\)\s*$/);
    if (cc && cc[1].toUpperCase() === cc[2].toUpperCase()) {
      code = cc[2].toUpperCase();
      rawStr = airportCityNameSafe_v21877(code, langOverride) || code;
    } else {
      var solo = rawStr.match(/^\s*\(\s*([A-Za-z]{3})\s*\)\s*$/);
      if (solo) {
        code = solo[1].toUpperCase();
        rawStr = airportCityNameSafe_v21877(code, langOverride) || code;
      }
    }
  }

  if (!code) {
    var dup = rawStr.match(/^(.+?)\s*\(\s*([A-Za-z]{3})\s*\)\s*\(\s*([A-Za-z]{3})\s*\)$/);
    if (dup && dup[2].toUpperCase() === dup[3].toUpperCase()) {
      rawStr = dup[1].trim();
      code = dup[3].toUpperCase();
    } else {
      var mp2 = rawStr.match(/^(.+?)\s*\(\s*([A-Za-z]{3})\s*\)$/);
      if (mp2 && !_isRealApCode(mp2[2])) {
        // "Goose (BAY)" — the parenthesized word isn't a code; repair the name.
        rawStr = (mp2[1] + ' ' + mp2[2]).replace(/\s+/g, ' ').trim();
        mp2 = null;
      }
      var m = mp2 || rawStr.match(/^(.+?)(?:\s+|-|\/|,)\s*([A-Za-z]{3})$/);
      if (m && (mp2 || _isRealApCode(m[2]))) {
        rawStr = m[1].trim();
        code = m[2].toUpperCase();
      } else if (/^[A-Za-z]{3}$/.test(rawStr)) {
        code = rawStr.toUpperCase();
        rawStr = airportCityNameSafe_v21877(code, langOverride) || rawStr;
      }
    }
  }

  if (code && (!rawStr || rawStr.replace(/[^A-Za-z]/g, '').toUpperCase() === code)) {
    rawStr = airportCityNameSafe_v21877(code, langOverride) || rawStr;
  }

  var city = normalizeDisplayCity(rawStr, code);
  // v22736 — last resort: the feed gave a city but no code. Resolve it from
  // the name (unambiguous matches only) so these rows stop being the only
  // ones on the board without a chip.
  if (!code) {
    var _guess = _iataFromCityName(city);
    if (_guess) code = _guess;
  }
  return code ? (city + ' (' + code + ')') : city;
}

// cityCode(iata, [overrideCity], [langOverride]) — returns "Chicago (MDW)" format
// for unified display across FIDS rows, gate screens, and welcome panels.
//
// Format: "City (CODE)" (mixed case city, uppercase 3-letter IATA in parens).
// Examples:
//   cityCode('MDW')           → "Chicago (MDW)"
//   cityCode('IAD')           → "Washington (IAD)"
//   cityCode('YQM')           → "Moncton (YQM)"
//   cityCode('???')           → "???"  (unknown code, return as-is)
//   cityCode('LAX', 'L.A.')   → "L.A. (LAX)"  (use override)
//
// If a city name is unavailable in CITY/CITY_FR, falls back to AP[].city,
// then to the bare IATA code. The IATA code stays uppercase always.
// v218.14: Changed from "City-IATA" hyphen format to "City (IATA)" parens
// format. All defensive checks that scanned for "-IATA" suffix were
// updated to scan for " (IATA)" instead.
// Display-only IATA overrides (Nick). The real code still drives weather,
// coords and data-iata logic; only the code CHIP shown to travellers changes.
// YHU (Montréal Saint-Hubert) shows as the Montréal metro code MET.
var AIRPORT_DISPLAY_IATA = { YHU: 'MET' };
function _dispIata(code) {
  var c = String(code || '').toUpperCase().trim();
  return AIRPORT_DISPLAY_IATA[c] || code;
}

function cityCode(iata, overrideCity, langOverride) {
  var code = String(iata || '').replace(/[^A-Za-z]/g, '').toUpperCase().slice(0, 3);
  // v22753 — the v22736 fallback lived only in formatCityIata, so rows that
  // render through THIS path still showed a bare city with no chip when the
  // feed omitted the code ('Hartford' on the Tampa board, which we do know as
  // BDL). Same unambiguous-only rule; ambiguous names stay code-less.
  if (!code) {
    var _cc = _iataFromCityName(overrideCity || '');
    if (_cc) code = _cc;
  }
  if (!code) return normalizeDisplayCity(overrideCity || '', '');

  var city = String(overrideCity || '').replace(/\s+/g, ' ').trim();

  // If overrideCity is just the same airport code, use the real city lookup.
  if (city.replace(/[^A-Za-z]/g, '').toUpperCase() === code) city = '';

  if (!city) city = airportCityNameSafe_v21877(code, langOverride);
  if (!city) return _dispIata(code);

  return normalizeDisplayCity(city, code) + ' (' + _dispIata(code) + ')';
}

// TL() returns current rotation language only
const TL = k => {
  const obj = LS[k] || {};
  return obj[lang] || obj.en || k;
};
// TLF() — TL with field interpolation. Pass an object with values for
// placeholders like {FLIGHT}, {GATE}, etc. in the translation string.
const TLF = (k, fields) => {
  let s = TL(k);
  if (fields) {
    Object.keys(fields).forEach(f => {
      s = s.split('{' + f + '}').join(fields[f]);
    });
  }
  return s;
};
// SL() returns current rotation language status (sentence case preserved)
const SL = k => {
  const obj = SS[k] || {};
  return obj[lang] || obj.en || k;
};
// Bilingual variants — always show English · French together. The web cards
// (mobile) otherwise show only the single rotation language; the boards are
// already bilingual, so these bring the cards in line.
const SLbi = k => { const o = SS[k] || {}; const en = o.en || k; return (o.fr && o.fr !== en) ? (en + ' · ' + o.fr) : en; };
const TLbi = k => { const o = LS[k] || {}; const en = o.en || k; return (o.fr && o.fr !== en) ? (en + ' · ' + o.fr) : en; };

// ── LANGUAGE ROTATION — flips between selected languages ─────────────────
function startLangRotation() {
  if (langRotateTimer) clearInterval(langRotateTimer);
  if (langs.length <= 1) return;
  langRotateTimer = setInterval(() => {
    // The MAIN board's paging clock (tick_carousel: EN page → FR page →
    // advance) OWNS the language there. This second timer flipping lang on
    // its own 30s beat produced '15 seconds English, 1 second French'
    // depending on phase offset (Nick). It now only serves screens the
    // paging clock doesn't cover.
    if (screenType === 'main' && typeof pageTimer !== 'undefined' && pageTimer) return;
    langIdx = (langIdx + 1) % langs.length;
    lang = langs[langIdx];
    updateTicker();
    if (screenType === 'main' && (data.dep.length || data.arr.length)) render();
    if (screenType !== 'main') {
      // v22158 — do NOT force a full gate rebuild here: the v2 gate is
      // bilingual-simultaneous, and the rebuild on every 30s flip made the
      // whole screen visibly bounce (Nick: 'still bouncing every so often').
      // Widgets with their own timers (ticker, clock, ads) keep rotating.
    }
  }, 30000); // flip every 30 seconds
}

function toggleLang(l) {
  const idx = langs.indexOf(l);
  if (idx >= 0) {
    if (langs.length <= 1) return; // keep at least 1
    langs.splice(idx, 1);
    if (langIdx >= langs.length) langIdx = 0;
  } else {
    langs.push(l);
  }
  lang = langs[langIdx];
  updateLangButtons();
  updateTicker();
  startLangRotation();
  const testBtn = document.getElementById('testFlightBtn');
  if (testBtn) testBtn.textContent = TL('addFlight');
  if (data.dep.length || data.arr.length) render();
}
function updateLangButtons() {
  ['en','fr','es','de','it','pt','ja','zh','ar'].forEach(l => {
    const btn = document.getElementById('lLang' + l.charAt(0).toUpperCase() + l.slice(1));
    if (btn) btn.classList.toggle('active', langs.includes(l));
  });
}

// ── TICKER — interleaves selected languages ──────────────────────────────
// Baggage-hall ticker messages (Nick: 'the ticker info messages on bags').
// Same bilingual pattern as the main-board ticker, baggage-flavoured.
// On-screen BUILD TAG (bottom-left, faint) — ends the 'which build am I
// looking at' guessing during preview reviews. Bump with the cache token.
var FIDS_BUILD_TAG = 'v22863';
(function(){
  try {
    function _addTag(){
      if (document.getElementById('fidsBuildTag')) return;
      var d = document.createElement('div');
      d.id = 'fidsBuildTag';
      d.textContent = FIDS_BUILD_TAG;
      d.style.cssText = 'position:fixed;left:7px;bottom:1px;z-index:99999;font:600 10px/1.6 monospace;color:rgba(128,138,152,0.55);pointer-events:none;';
      document.body.appendChild(d);
      setInterval(function(){
        try {
          var t = FIDS_BUILD_TAG + (window._adDiag ? ' · ' + window._adDiag : '');
          // Name the element actually PAINTING the ad panel's centre pixel —
          // the definitive answer to which of the several renderers is on top.
          var c = document.getElementById('gateAdCarousel');
          if (c) {
            var r = c.getBoundingClientRect();
            if (r.width > 0) {
              var e = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
              if (e) t += ' · top:' + (e.id || (e.tagName.toLowerCase() + (e.className && typeof e.className === 'string' ? '.' + e.className.split(' ')[0] : '')));
            }
          }
          d.textContent = t;
        } catch (e) {}
      }, 2000);
    }
    if (document.body) _addTag(); else document.addEventListener('DOMContentLoaded', _addTag);
  } catch (e) {}
})();

// ── BUILD WATCHDOG ───────────────────────────────────────────────────────
// A running page executes the build it loaded — field displays run for days,
// so every deployed fix reached them only on a manual reload (Nick: 'its not
// getting fixed nothing is changing' — the screen was still executing an old
// build). Poll our own page (served no-store), read the fids-core buster,
// and when a newer build is live reload at a QUIET moment: no pointer/key
// input for 5+ minutes, so an unattended kiosk updates within minutes and an
// admin mid-click is never yanked.
(function () {
  try {
    var _lastInput = Date.now();
    ['pointerdown', 'keydown', 'mousemove', 'touchstart', 'wheel'].forEach(function (ev) {
      window.addEventListener(ev, function () { _lastInput = Date.now(); }, { passive: true });
    });
    var _newBuild = null;
    setInterval(function () {
      try {
        fetch(location.pathname + location.search, { cache: 'no-store' })
          .then(function (r) { return r.ok ? r.text() : ''; })
          .then(function (html) {
            var m = html && html.match(/fids-core\.js\?v=([0-9][0-9.-]*)/);
            if (m && ('v' + m[1]) !== FIDS_BUILD_TAG) _newBuild = 'v' + m[1];
            if (_newBuild && Date.now() - _lastInput > 5 * 60000) {
              console.log('[FIDS] Build ' + _newBuild + ' deployed (running ' + FIDS_BUILD_TAG + ') — reloading');
              location.reload();
            }
          }).catch(function () {});
      } catch (e) {}
    }, 180000);
  } catch (e) {}
})();

// ── GATE STYLESHEET GUARD ────────────────────────────────────────────────
// One browser cached a dead response for gids-v218.78.css (fetched during a
// deploy window) and rendered the retired gate look — visible g8-r2 banner,
// unstyled rails — on every build after, because the cached URL never
// changed. The probe measures the sentinel rule that sits at the END of the
// stylesheet (so it also catches truncated responses); when it isn't live,
// the file is re-fetched under a unique URL. Screens in the field can't
// have their caches cleared by hand — they have to self-heal.
(function () {
  try {
    // Every guarded stylesheet carries a sentinel rule at its very END with a
    // unique probe height, so a cached bad/truncated copy of ANY of them
    // self-heals — the jetBlue clip was fids-layout-fixes.css gone stale on
    // one browser, the exact disease v22358 fixed for the gate stylesheet.
    var GUARDS = [
      { href: 'gids-v218.78.css',     cls: 'g8-css-sentinel',   h: 7, tries: 0 },
      { href: 'fids-layout-fixes.css', cls: 'fids-css-sentinel', h: 9, tries: 0 }
    ];
    function _cssAlive(g) {
      if (!document.body) return true; // can't probe yet — don't re-fetch blind
      var p = document.createElement('div');
      p.className = g.cls;
      p.style.cssText = 'position:absolute;visibility:hidden;pointer-events:none;';
      document.body.appendChild(p);
      var h = p.offsetHeight;
      p.parentNode.removeChild(p);
      return h === g.h;
    }
    function _check() {
      GUARDS.forEach(function (g) {
        var link = document.querySelector('link[href*="' + g.href + '"]');
        if (!link) return;            // page doesn't use this stylesheet
        if (_cssAlive(g)) return;     // sheet is live — nothing to do
        if (g.tries >= 3) return;     // give up after 3 recoveries (network down)
        g.tries++;
        console.warn('[FIDS] stylesheet not applied — re-fetching ' + g.href + ' (attempt ' + g.tries + ')');
        var fresh = document.createElement('link');
        fresh.rel = 'stylesheet';
        fresh.href = link.getAttribute('href').split('?')[0] + '?v=cssguard-' + Date.now();
        fresh.onload = function () { setTimeout(_check, 1500); };
        fresh.onerror = function () { setTimeout(_check, 8000); };
        link.parentNode.insertBefore(fresh, link.nextSibling);
      });
    }
    if (document.readyState === 'complete') setTimeout(_check, 3000);
    else window.addEventListener('load', function () { setTimeout(_check, 3000); });
    setTimeout(_check, 12000); // fallback in case the load event never fires
  } catch (e) {}
})();

// ── MAP ENGINE GUARD ─────────────────────────────────────────────────────
// The stylesheet guard's failure class, aimed at the route maps: the
// /mapcdn/leaflet.js tag carries no version, and until v22378 the worker
// stamped day-long cache headers on FAILED upstream fetches too — so one bad
// response poisoned a display's copy of the map engine for 24 h, initGateMap
// bailed on its typeof L check, and every route map on that screen vanished
// (Nick: 'the flight routes i dont see any show up whatsoever'). Probe
// window.L after load; when the engine is missing, re-inject it under a
// unique query (the worker ignores queries; browser and edge treat it as a
// new URL) and re-run the live map init so maps return without a re-render.
// leaflet-arc is optional (plain-line fallback exists) but heals the same
// way once L is live.
(function () {
  try {
    var _engTries = 0, _arcTries = 0, _engInFlight = false;
    function _engAlive() {
      return typeof window.L !== 'undefined' && window.L && typeof window.L.map === 'function';
    }
    function _healArc() {
      try {
        if (!_engAlive() || !window.L.Polyline) return;
        if (typeof window.L.Polyline.Arc === 'function' || _arcTries >= 3) return;
        _arcTries++;
        var a = document.createElement('script');
        a.src = '/mapcdn/leaflet-arc.js?v=mapguard-' + Date.now();
        document.head.appendChild(a);
      } catch (e) {}
    }
    function _probe() {
      if (_engAlive()) { _healArc(); return; }
      // Only pages that draw maps carry the engine tag — bail elsewhere.
      if (!document.querySelector('script[src*="/mapcdn/leaflet.js"]')) return;
      if (_engInFlight || _engTries >= 3) return;
      _engTries++; _engInFlight = true;
      console.warn('[FIDS] map engine missing — re-fetching leaflet.js (attempt ' + _engTries + ')');
      var s = document.createElement('script');
      s.src = '/mapcdn/leaflet.js?v=mapguard-' + Date.now();
      s.onload = function () {
        _engInFlight = false;
        _healArc();
        // Bring the maps back NOW — the 10 s map tick would also catch it,
        // but the retry hook re-frames the current gate immediately.
        try { if (typeof window._gateMapRetry === 'function') window._gateMapRetry(); } catch (e) {}
      };
      s.onerror = function () { _engInFlight = false; };
      document.head.appendChild(s);
    }
    if (document.readyState === 'complete') setTimeout(_probe, 3000);
    else window.addEventListener('load', function () { setTimeout(_probe, 3000); });
    // Screens run for days — keep a slow watch, allowing one fresh attempt
    // per cycle while the engine is still out (network may have recovered).
    setInterval(function () {
      if (!_engAlive()) { _engTries = Math.min(_engTries, 2); _probe(); }
      else _healArc();
    }, 180000);
  } catch (e) {}
})();

