function _adbLat(loc) { return _adbCoord(loc, 'lat', 'latitude'); }
function _adbLng(loc) {
  var v = _adbCoord(loc, 'lon', 'lng');
  return v !== null ? v : _adbCoord(loc, 'longitude', 'long');
}
