      // A Mode-S address is also a current aircraft identifier. If the flight
      // payload has it but omits reg, resolve the active registry record before
      // inbound linking; this uses the API's documented Icao24 search option.
      if (!result.reg && result.modeS) {
        try {
          var _modeIdent = await fidsAircraftByModeS(result.modeS);
          if (_modeIdent && _modeIdent.reg) {
            result.reg = _modeIdent.reg;
            result._regSource = 'icao24';
            if (!result.aircraft && _modeIdent.aircraft) result.aircraft = formatAircraft(_modeIdent.aircraft);
            if (!result.aircraftCode && _modeIdent.aircraftCode) result.aircraftCode = _modeIdent.aircraftCode;
            if (!result.aircraftModel && _modeIdent.aircraft) result.aircraftModel = _modeIdent.aircraft;
          }
        } catch (e) {}
      }

      // Step 3: Resolve marketing vs operating carrier.
      // leg.airline = marketing carrier. leg.departure.airline = operating carrier.
      // When they differ, it's a codeshare and departure.airline is the truth.
      var mktAl = primaryLeg.airline || {};
      var opAl  = (primaryLeg.departure && primaryLeg.departure.airline) || null;
      result.marketing = {
        iata: (mktAl.iata || '').trim().toUpperCase(),
        name: (mktAl.name || '').trim(),
        icao: (mktAl.icao || '').trim().toUpperCase()
      };

      // Operator priority: (1) explicit operating carrier from ADB,
      // (2) callsign prefix lookup, (3) fall back to marketing.
      if (opAl && opAl.iata && opAl.iata.toUpperCase() !== result.marketing.iata) {
        result.operator = {
          iata: opAl.iata.trim().toUpperCase(),
          name: (opAl.name || '').trim(),
          icao: (opAl.icao || '').trim().toUpperCase(),
          _source: 'adb-departure-airline'
        };
      } else if (result.callsign) {
        var csIata = callsignToIata(result.callsign);
        if (csIata && csIata !== result.marketing.iata) {
          result.operator = {
            iata: csIata,
            name: AIRLINE_NAME[csIata] || csIata,
            icao: result.callsign.substring(0,3),
            _source: 'callsign-prefix'
          };
        }
      }
      // If no operator differs from marketing, operator === marketing
      if (!result.operator) {
        result.operator = Object.assign({}, result.marketing, { _source: 'same-as-marketing' });
      }

      // Step 4: Extract live position from the leg if airborne.
      // A foreign leg's position is another flight's aircraft — never ours.
      var loc = _legForeign ? null : primaryLeg.location;
      if (loc) {
        result.livePosition = {
          lat: _adbLat(loc),
          lng: _adbLng(loc),
          alt: _adbAltFt(loc),
          speed: _adbSpdKt(loc)
        };
      }

      // Step 5: Find the inbound — the leg this airframe flew that arrives
      // at airportIata immediately before the primary leg departs.
