    var path = '/flights/reg/' + encodeURIComponent(cleanReg) + '/' + dateStr + '?withLocation=true';
    var r = await adbPacedFetch('https://fids-proxy.n-leblanc1984.workers.dev' + path);
    if (!r.ok) return null;
