let _apAutoActive = -1;
let _apAutoCtx = 'ctrl'; // 'ctrl' (top toolbar) or 'menu' (sidebar)

var _apSearchTimer = null;
var _apSearchCache = {};

function apAutoSearch(q, ctx) {
  _apAutoCtx = ctx || 'ctrl';
  _apAutoActive = -1;
  const ddId = ctx === 'menu' ? 'apDropdownMenu' : 'apDropdownCtrl';
  const dd = document.getElementById(ddId);
  if (!dd) return;
  const v = (q||'').trim();
  if (v.length < 2) { dd.style.display='none'; return; }

  function renderMatches(matches) {
    if (!matches.length) { dd.style.display='none'; return; }
    var isMenu = (ctx === 'menu');
    var borderC = isMenu ? '#f4f4f5' : '#2a2a2e';
    var textC   = isMenu ? '#3f3f46' : '#fff';
    var codeC   = isMenu ? '#18181b' : '#eab308';
    var nameC   = isMenu ? '#71717a' : 'rgba(255,255,255,0.85)';
    var subC    = isMenu ? '#c4c4cc' : 'rgba(255,255,255,0.4)';
    dd.innerHTML = matches.map((a,i) => {
      const safeName = (a.n||'').replace(/'/g, "\\'");
      const safeCtx  = ctx || 'ctrl';
      const sub = a.city && a.city !== a.n ? '<span style="font-size:11px;color:' + subC + ';margin-left:4px;">' + a.city + '</span>' : '';
      return '<div data-code="' + a.c + '" data-idx="' + i + '"'
        + ' style="padding:8px 12px;cursor:pointer;font-size:13px;font-weight:600;border-bottom:1px solid ' + borderC + ';color:' + textC + ';display:flex;gap:10px;align-items:center;"'
        + ' onmousedown="apAutoSelect(\'' + a.c + '\',\'' + safeName + '\',\'' + safeCtx + '\')"'
        + ' onmouseover="apAutoHover(' + i + ',\'' + safeCtx + '\')">'
        + '<span style="color:' + codeC + ';font-weight:800;min-width:36px;">' + a.c + '</span>'
        + '<span style="color:' + nameC + ';">' + a.n + '</span>' + sub
        + '</div>';
    }).join('');
    dd.style.display='block';
  }

  // Local results instantly
  const vUp = v.toUpperCase();
  const local = AP_LIST.filter(a =>
    a.c.startsWith(vUp) || a.n.toUpperCase().includes(vUp)
  ).slice(0, 10).map(a => ({c:a.c, n:a.n, city:''}));
  renderMatches(local);

  // Live API search after 350ms debounce (3+ chars only)
  if (v.length < 3) return;
  if (_apSearchTimer) clearTimeout(_apSearchTimer);
  _apSearchTimer = setTimeout(function() {
    if (_apSearchCache[vUp]) { renderMatches(_apSearchCache[vUp]); return; }
    var path = '/airports/search/term?q=' + encodeURIComponent(v) + '&limit=12&withFlightInfoOnly=true&withSearchByCode=true';
    adbPacedFetch('https://fids-proxy.n-leblanc1984.workers.dev' + path)
      .then(function(r) { return r.ok ? r.json() : null; })
      .then(function(data) {
        if (!data || !data.items || !data.items.length) return;
        var results = data.items
          .filter(function(a) { return a.iata; })
          .map(function(a) { return {
            c: a.iata,
            n: a.shortName || a.municipalityName || a.name || a.iata,
            city: a.municipalityName || ''
          }; });
        _apSearchCache[vUp] = results;
        renderMatches(results);
      })
      .catch(function() {});
  }, 800);
}
function apAutoHover(idx, ctx) {
  _apAutoActive = idx;
  const ddId = ctx === 'menu' ? 'apDropdownMenu' : 'apDropdownCtrl';
  const dd = document.getElementById(ddId);
  if (!dd) return;
  const hoverBg = ctx === 'menu' ? '#f4f4f5' : '#2a2a2e';
  [...dd.children].forEach((el,i) => {
    el.style.background = i === idx ? hoverBg : '';
  });
}

function apAutoSelect(code, name, ctx) {
  const ddId = ctx === 'menu' ? 'apDropdownMenu' : 'apDropdownCtrl';
  const inputId = ctx === 'menu' ? 'menuApInput' : 'apSelInput';
  const hiddenId = 'apSel'; // both ctrl and menu write to the same hidden field
  const dd = document.getElementById(ddId);
  const inp = document.getElementById(inputId);
  const hid = document.getElementById(hiddenId);
  if (inp) inp.value = code + ' — ' + name;
  if (hid) hid.value = code;
  if (dd) dd.style.display='none';
  onApChange();
  if (ctx === 'menu') {
    if (typeof _syncMenu === 'function') _syncMenu();
  } else {
    var apPanel = document.getElementById('apPanel');
    if (apPanel) apPanel.classList.add('hidden');
  }
}

function apAutoKey(e, ctx) {
  const c = ctx || 'ctrl';
  const ddId = c === 'menu' ? 'apDropdownMenu' : 'apDropdownCtrl';
  const dd = document.getElementById(ddId);
  if (!dd || dd.style.display === 'none') return;
  const items = dd.children;
  if (e.key === 'ArrowDown') {
    e.preventDefault();
    _apAutoActive = Math.min(_apAutoActive+1, items.length-1);
    apAutoHover(_apAutoActive, c);
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    _apAutoActive = Math.max(_apAutoActive-1, 0);
    apAutoHover(_apAutoActive, c);
  } else if (e.key === 'Enter') {
    e.preventDefault();
    if (_apAutoActive >= 0 && items[_apAutoActive]) {
      const el = items[_apAutoActive];
      apAutoSelect(el.dataset.code, '', c);
    }
  } else if (e.key === 'Escape') {
    dd.style.display='none';
  }
}

// Close dropdown on outside click
document.addEventListener('click', e => {
  ['apDropdown','apDropdownCtrl','apDropdownMenu'].forEach(id => {
    const dd = document.getElementById(id);
    if (dd && !dd.contains(e.target)) dd.style.display='none';
  });
});

// Sync airport input display on load
function initApInputs() {
  const ctrlInp = document.getElementById('apSelInput');
  if (ctrlInp) {
    const code = document.getElementById('apSel')?.value || 'YQM';
    const ap = AP_LIST.find(a=>a.c===code);
    ctrlInp.value = ap ? code+' — '+ap.n : code;
  }
}
// Run immediately and again after DOM ready
initApInputs();
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApInputs);
} else {
  setTimeout(initApInputs, 100);
}

window.addEventListener('DOMContentLoaded', () => {
  // RocGrotesk is only the DEFAULT — a font the user picked (and which
  // changeFont persisted) must never be stomped on reload.
  try { restoreFontChoice('Possibility'); } catch (e) {}
  const bgCtrls = document.getElementById('ctrlBgGroup');
  if (bgCtrls && screenType === 'gate') bgCtrls.style.display = 'flex';
  // If airline mode was restored from localStorage, kick off rotation.
  if (GATE_BG_MODE === 'airline') {
    try { startAirlineBgRotation(); } catch(e) {}
  }
  // Populate the menu picker dropdown (hidden unless airline mode active).
  try { refreshAirlineBgPicker(); } catch(e) {}
  // Update the airport name header from the current apSel value. The HTML
  // files ship with "Greater Moncton Roméo LeBlanc..." as a placeholder;
  // this replaces it with whatever airport is actually being displayed
  // (URL ?ap= param, sessionStorage, or the default).
  try {
    var apInit = document.getElementById('apSel');
    var hdrInit = document.getElementById('hdrApName');
    if (apInit && hdrInit && apInit.value) {
      var apRec = (typeof AP !== 'undefined' && AP[apInit.value]) || null;
      hdrInit.textContent = apRec ? apRec.name : apInit.value;
    }
  } catch(e) {}
});




