// Show floating button when toolbar is hidden, auto-hide after 10s
var _floatingTimer = null;
function showFloatingMenu() {
  var fb = document.getElementById('floatingMenu');
  if (!fb) return;
  if (!ctrl.classList.contains('show')) {
    fb.style.display = 'block';
    fb.style.opacity = '1';
    if (_floatingTimer) clearTimeout(_floatingTimer);
    _floatingTimer = setTimeout(function() {
      fb.style.opacity = '0';
      setTimeout(function() { fb.style.display = 'none'; }, 300);
    }, 10000);
  } else {
    fb.style.display = 'none';
  }
}
