function findVideoForDestination(destIata, preferredLang) {
  if (!destIata) return null;
  var code = String(destIata).toUpperCase();
  // NOTE: Hardcoded video IDs were removed — those individual videos have
  // embedding disabled (YouTube error 150). Only the AC playlists themselves
  // allow embedding, so we MUST find videos by matching playlist titles.

  // Dynamic lookup via YouTube playlist harvest. Matches AC_VIDEO_DEST_MAP
  // keywords (e.g. "Toronto", "Montréal") against harvested playlist video
  // titles. Returns the playlist index, which playDestinationVideo() uses
  // to play via loadPlaylist({list, index}).
  var keys = AC_VIDEO_DEST_MAP[code];
  if (!keys || !keys.length) return null;
  function _norm(s) {
    return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  }
  // Try the preferred language first, then fall back to the other.
  var order = (preferredLang === 'en') ? ['en','fr'] : ['fr','en'];
  for (var o = 0; o < order.length; o++) {
    var lang2 = order[o];
    var items = _ytPlaylistItemsByLang[lang2] || [];
    for (var i = 0; i < items.length; i++) {
      var title = _norm(items[i].title);
      if (!title) continue; // title hasn't harvested yet
      for (var k = 0; k < keys.length; k++) {
        var needle = _norm(keys[k]);
        var re = new RegExp('\\b' + needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b');
          if (re.test(title)) {
            var cdKey3 = lang2 + ':' + i;
            var cd3 = _videoCooldownUntil[cdKey3] || 0;
            if (Date.now() >= cd3) {
              console.log('[AC-VIDEO] matched IATA', code, 'keys', keys, '→', lang2, 'idx', i, 'title:', items[i].title);
              return { lang: lang2, idx: i, videoId: items[i].videoId };
            }
            break;
          }
      }
    }
  }
  return null;
}

// Mark a video as recently played — won't re-show for AC_VIDEO_COOLDOWN_MS.
// Accepts either the legacy numeric idx OR a composite 'lang:idx' key.
function markVideoPlayed(key) {
  if (key === null || key === undefined) return;
  var cdKey = (typeof key === 'number') ? ('fr:' + key) : String(key);
  _videoCooldownUntil[cdKey] = Date.now() + AC_VIDEO_COOLDOWN_MS;
  console.log('[AC-VIDEO] cooldown set for ' + cdKey + ' until ' + new Date(_videoCooldownUntil[cdKey]).toLocaleTimeString());
}

// Load the YouTube IFrame API once, lazily. Returns a Promise.
function loadYouTubeApi() {
  return new Promise(function(resolve) {
    if (_ytApiReady) { resolve(); return; }
    if (_ytApiLoading) {
      var _check = setInterval(function(){ if (_ytApiReady) { clearInterval(_check); resolve(); } }, 100);
      return;
    }
    _ytApiLoading = true;
    // YouTube API calls this global callback when loaded.
    window.onYouTubeIframeAPIReady = function() {
      _ytApiReady = true;
      console.log('[AC-VIDEO] YouTube IFrame API ready');
      resolve();
    };
    var tag = document.createElement('script');
    tag.src = 'https://www.youtube.com/iframe_api';
    tag.async = true;
    document.head.appendChild(tag);
  });
}

// Mount the hidden player + snapshot BOTH playlists' video IDs.
// We cue the FR playlist, snapshot its IDs, then cue EN and snapshot its IDs
// too. After that the player is idle and ready for loadVideoById() calls.
function ensureVideoPlayer() {
  return loadYouTubeApi().then(function() {
    if (_ytPlayer && _ytPlayer.loadVideoById) return _ytPlayer;
    if (_ytPlayer) {
      // Player exists but isn't ready yet — wait for it
      return new Promise(function(resolve) {
        var checks = 0;
        var iv = setInterval(function() {
          checks++;
          if (_ytPlayer && _ytPlayer.loadVideoById) { clearInterval(iv); resolve(_ytPlayer); }
          else if (checks > 50) { clearInterval(iv); resolve(_ytPlayer); }
        }, 100);
      });
    }
    var host = document.getElementById('acVideoHost');
    if (!host) {
      host = document.createElement('div');
      host.id = 'acVideoHost';
      host.style.cssText = 'position:fixed;left:-99999px;top:-99999px;width:320px;height:180px;z-index:0;pointer-events:none;overflow:hidden;';
      document.body.appendChild(host);
      var inner = document.createElement('div');
      inner.id = 'acVideoMount';
      inner.style.cssText = 'width:100%;height:100%;';
      host.appendChild(inner);
    }
    // Player is initialized in SINGLE-VIDEO mode — no playlist context.
    // That way loadVideoById() always plays exactly the requested video,
    // and ENDED fires cleanly without YouTube auto-advancing to the next
    // playlist entry. Playlist harvest (for the secondary IATA-not-in-
    // hardcoded path) runs lazily after the player is ready, in a way
    // that doesn't interfere with playback.
    _ytPlayer = new YT.Player('acVideoMount', {
      width: '100%', height: '100%',
      host: 'https://www.youtube-nocookie.com',
      playerVars: {
        autoplay: 0,
        controls: 0,
        modestbranding: 1,
        rel: 0,
        playsinline: 1,
        iv_load_policy: 3,
        disablekb: 1,
        fs: 0,
        mute: 1,
        origin: window.location.origin
      },
      events: {
        onReady: function() {
          console.log('[VIDEO] player ready');
          // Note: legacy AC playlist harvester removed in v111. The
          // destination-keyword matching system is gone — admin assigns
          // videos directly via the Media tab now.
        },
        onStateChange: function(ev) {
          // 0 = ENDED — the requested video finished naturally.
          // Behavior depends on what we're playing:
          //   - Single video (cdKey 'saved:xxx'): kill playback, start cooldown
          //   - Playlist (cdKey 'playlist:xxx'): let it auto-advance to the
          //     next video. The playlist will fire state 0 again at the END
          //     of the LAST video, when getPlaylistIndex returns -1 or the
          //     final index.
          if (ev.data === 0) {
            var cdStr = String(_currentVideoIdx || '');
            var isPlaylist = cdStr.indexOf('playlist:') === 0;
            var isLoop = cdStr.indexOf('savedLoop:') === 0;
            if (isLoop) {
              // Loop mode — replay the same video from the start
              console.log('[VIDEO] loop — replaying');
              try {
                if (_ytPlayer && window._loopVideoId) {
                  _ytPlayer.seekTo(0, true);
                  _ytPlayer.playVideo();
                  return;
                }
              } catch (e) {}
            }
            if (isPlaylist) {
              // Check if this was the last video in the playlist
              var atEnd = false;
              try {
                var idx = _ytPlayer.getPlaylistIndex();
                var pl = _ytPlayer.getPlaylist() || [];
                if (idx === -1 || idx >= pl.length - 1) atEnd = true;
              } catch (e) {}
              if (!atEnd) {
                console.log('[VIDEO] playlist video ended — auto-advancing');
                // Don't stop — YouTube will advance to the next playlist item
                return;
              }
              console.log('[VIDEO] playlist reached end');
            } else {
              console.log('[VIDEO] ended (state 0)');
            }
            // Final-stop path (single video, or playlist's last video)
            try { if (_ytPlayer && _ytPlayer.stopVideo) _ytPlayer.stopVideo(); } catch(e) {}
            try { if (_ytPlayer && _ytPlayer.clearVideo) _ytPlayer.clearVideo(); } catch(e) {}
            if (_currentVideoIdx) markVideoPlayed(_currentVideoIdx);
            _currentVideoIdx = null;
            _currentVideoLang = null;
            window._expectedVideoId = null;
            window._lastVideoEndedAt = Date.now();
            try { _hideDestinationVideoOverlay(); } catch(e) {}
          }
          // 2 = PAUSED. If the user (or the player itself) paused, we want
          // to know — but NEVER kill playback just because of a pause.
          // 1 = PLAYING — see below.
          if (ev.data === 1) {
            try { _ytPlayer.mute(); } catch(e) {}
            // Note: we used to have an "auto-advance detected" check here that
            // compared the playing video ID to _expectedVideoId. That fired
            // false positives ~2s into every video and killed playback. The
            // real auto-advance protection is in the ENDED handler below,
            // which calls stopVideo() and clearVideo() before YouTube can
            // load the next playlist entry.
          }
        },
        onError: function(ev) {
          // 2 = invalid videoId, 5 = HTML5 player error, 100 = video not found,
          // 101/150 = embedding disallowed by uploader
          console.warn('[AC-VIDEO] player error code:', ev.data, '— restoring overlay');
          try { _hideDestinationVideoOverlay(); } catch(e) {}
        }
      }
    });
    return _ytPlayer;
  });
}

// Lazy playlist harvest using a separate hidden player — keeps the FR/EN
// playlist video IDs available for the secondary findVideoForDestination
// lookup path without ever touching the primary player's playback state.
var _harvestPlayer = null;
var _harvestStage = null;

// Harvest titles by briefly cueing each playlist item. This is the only
// reliable way without an API key. Runs asynchronously; titles populate
// over ~1 second. findVideoForDestination() gracefully returns -1 until
// the title it's looking for has been populated.
function _harvestPlaylistTitles(lang) {
  var items = _ytPlaylistItemsByLang[lang] || [];
  if (!items.length) return;
  var pendingCount = items.filter(function(it){ return !it.title; }).length;
  if (!pendingCount) return;
  var resolved = 0;
  items.forEach(function(item) {
    if (item.title) return;
    var url = 'https://www.youtube.com/oembed?url=' + encodeURIComponent('https://www.youtube.com/watch?v=' + item.videoId) + '&format=json';
    fetch(url).then(function(r){ return r.ok ? r.json() : null; })
      .then(function(j){
        if (j && j.title) item.title = j.title;
        resolved++;
        if (resolved >= pendingCount) {
          console.log('[AC-VIDEO] all', lang.toUpperCase(), 'titles harvested:');
          items.forEach(function(it, i) { console.log('  ', i, it.videoId, '→', it.title || '(failed)'); });
        }
      })
      .catch(function(){
        resolved++;
        if (resolved >= pendingCount) {
          console.log('[AC-VIDEO] all', lang.toUpperCase(), 'titles harvested (some failed):');
          items.forEach(function(it, i) { console.log('  ', i, it.videoId, '→', it.title || '(failed)'); });
        }
      });
  });
}

// ── DESTINATION VIDEO PLAYBACK (welcome area) ────────────────────────
// Instead of injecting into the ad carousel, the video plays over the
// left welcome/photo area of the gate screen — the same place that shows
// "Welcome to <City>" and the rotating airline/city backgrounds.
// When the video ends, the welcome area restores to its normal state.
// A separate timer triggers playback every 5 minutes.

var _destVideoInterval = null;
var _videoPlayTimeoutSafety = null;

// Hide the "Welcome to City" text + position an overlay label over the slot.
function _showDestinationVideoOverlay(slot, cityStr) {
  var wt = document.getElementById('gateWelcomeText');
  if (wt && wt.style.display !== 'none') {
    wt.dataset.prevDisplay = wt.style.display || 'flex';
    wt.style.display = 'none';
    wt.dataset.hiddenByVideo = '1';
  }
  // Also hide the bottom message zone so it doesn't overlay the video.
  // (Message zone and video share z-index 5 and the same welcome panel.)
  var mz = document.getElementById('gateMessageZone');
  if (mz && mz.style.display !== 'none') {
    mz.dataset.prevDisplay = mz.style.display || 'flex';
    mz.style.display = 'none';
    mz.dataset.hiddenByVideo = '1';
  }
  _positionVideoHostOver(slot);
  // (Floating "DESTINATION · City" label intentionally removed — it could
  // get stranded as a fixed-position DOM element when video playback was
  // interrupted, leaving stale text on screen across airline/flight changes.
  // The new themed UI conveys destination context through the layout itself,
  // no extra label needed.)
  var staleLbl = document.getElementById('acVideoLabel');
  if (staleLbl) { try { staleLbl.remove(); } catch(e) { staleLbl.style.display = 'none'; } }
}

// Restore the welcome area to its normal state.
function _hideDestinationVideoOverlay() {
  // Always stamp end time so the 5-min cooldown applies whether the video
  // ended naturally, was forced off by safety timeout, or hit an error.
  console.log('[VIDEO] hide overlay — stack:', new Error().stack ? new Error().stack.split('\n').slice(1, 4).join(' | ') : '(no stack)');
  window._lastVideoEndedAt = Date.now();
  stopDestinationVideo();
  // Also hide native <video> element if a file upload was playing
  try { _hideNativeVideo(); } catch (e) {}
  // Also hide library image if one was showing
  try { _hideLibraryImage(); } catch (e) {}
  var wt = document.getElementById('gateWelcomeText');
  if (wt && wt.dataset.hiddenByVideo === '1') {
    wt.style.display = wt.dataset.prevDisplay || 'flex';
    delete wt.dataset.hiddenByVideo;
    delete wt.dataset.prevDisplay;
  }
  // Restore the message zone if we hid it for the video.
  var mz = document.getElementById('gateMessageZone');
  if (mz && mz.dataset.hiddenByVideo === '1') {
    mz.style.display = mz.dataset.prevDisplay || 'flex';
    delete mz.dataset.hiddenByVideo;
    delete mz.dataset.prevDisplay;
  }
  var lbl = document.getElementById('acVideoLabel');
  if (lbl) lbl.style.display = 'none';
  if (_videoPlayTimeoutSafety) { clearTimeout(_videoPlayTimeoutSafety); _videoPlayTimeoutSafety = null; }
}

// Try to play the current gate's destination video in the welcome area.
// Returns true if playback triggered, false otherwise (no match, cooldown,
// wrong airline, titles still loading, etc.).
function tryPlayDestinationVideo() {
  // Hard guard: if a video is currently playing, never start another one.
  if (_currentVideoIdx !== null && _currentVideoIdx !== undefined) {
    console.log('[VIDEO] already playing (' + _currentVideoIdx + '), skipping');
    return false;
  }
  // Cooldown — let other content show between videos.
  var COOLDOWN_MS = 5 * 60 * 1000;
  if (window._lastVideoEndedAt && (Date.now() - window._lastVideoEndedAt) < COOLDOWN_MS) {
    var secsLeft = Math.round((COOLDOWN_MS - (Date.now() - window._lastVideoEndedAt)) / 1000);
    console.log('[VIDEO] cooldown — ' + secsLeft + 's remaining');
    return false;
  }

  var code = (window._gateCurrentAirline || '').toUpperCase();
  var cf = window._gateCurrentFlight;
  var destIata = (cf && cf._locIata || '').toUpperCase();
  if (!destIata) return false;

  var slot = document.getElementById('gatePhotoBg');
  if (!slot) return false;

  // ── Build the candidate pool from FIDS_MEDIA admin assignments ──
  // The library has 3 kinds of items: YouTube single videos, YouTube
  // playlists, and uploaded MP4/WebM files. We pick one item to play
  // based on the airline's mode (rotate vs single). Recently-played
  // ITEM IDS (not video IDs) are tracked so the same item doesn't
  // play back-to-back.
  if (!window._recentVideoIds) window._recentVideoIds = [];
  function _wasRecent(id) { return window._recentVideoIds.indexOf(id) !== -1; }
  function _markRecent(id) {
    window._recentVideoIds.unshift(id);
    if (window._recentVideoIds.length > 20) window._recentVideoIds.length = 20;
  }

  var pool = [];
  try {
    if (window.FIDS_MEDIA && typeof window.FIDS_MEDIA.getAssignedVideosForAirline === 'function') {
      // Combine VIDEOS and IMAGES into one pool — both display in the
      // main gate area. Each entry's mode comes from the airline's
      // assignment slot, so videos and images can have different modes
      // (e.g. videos rotate, images single).
      var assignedVids = window.FIDS_MEDIA.getAssignedVideosForAirline(code) || [];
      var assignedImgs = window.FIDS_MEDIA.getAssignedImagesForAirline(code) || [];
      function _applyMode(arr) {
        if (!arr.length) return [];
        var mode = arr[0].mode || 'rotate';
        if (mode === 'single') {
          var primaryId = arr[0].primaryId;
          var primary = arr.find(function(x) { return x.item.id === primaryId; });
          return primary ? [primary] : [arr[0]];
        }
        var filtered = arr.filter(function(x) { return !_wasRecent(x.item.id); });
        if (!filtered.length) filtered = arr;
        return filtered;
      }
      pool = _applyMode(assignedVids).concat(_applyMode(assignedImgs));
    }
  } catch (e) {
    console.warn('[VIDEO] error reading FIDS_MEDIA:', e);
  }

  if (!pool.length) {
    console.log('[VIDEO] no assigned media for', code);
    return false;
  }

  var destCity = (typeof CITY !== 'undefined' && CITY[destIata]) || (cf.dest || destIata);
  try { destCity = destCity.toLowerCase().replace(/\b\w/g, function(l){return l.toUpperCase();}); } catch(e){}

  // Pick a random item from the combined pool
  var pickedEntry = pool[Math.floor(Math.random() * pool.length)];
  var item = pickedEntry.item;
  _markRecent(item.id);
  var typeLabel = item.type === 'image'
    ? 'image'
    : (item.source + '/' + (item.ytType || 'upload'));
  console.log('[VIDEO] Playing for', code, '→', destIata, ':', item.label || '(no label)', '(' + typeLabel + ')');
  _showDestinationVideoOverlay(slot, destCity);

  // Route to the right playback function based on item kind
  if (item.type === 'image' && item.url) {
    playLibraryImage(slot, item);
  } else if (item.source === 'youtube' && item.ytType === 'playlist') {
    playYouTubePlaylist(slot, item.ytId);
  } else if (item.source === 'youtube' && item.ytType === 'video') {
    try { ensureVideoPlayer(); } catch(e) {}
    playSavedVideo(slot, item.ytId, item.playback || {});
  } else if (item.source === 'upload' && item.url) {
    playUploadedVideo(slot, item.url, item.playback || {});
  } else {
    console.warn('[VIDEO] unknown item type:', item);
    _hideDestinationVideoOverlay();
    return false;
  }

  if (_videoPlayTimeoutSafety) clearTimeout(_videoPlayTimeoutSafety);
  _videoPlayTimeoutSafety = setTimeout(function() {
    console.warn('[VIDEO] safety timeout (8 min) — video stuck? forcing overlay restore');
    _hideDestinationVideoOverlay();
  }, 8 * 60 * 1000);
  return true;
}

// Play an individual YouTube video by ID (used for user-saved video pool).
// Uses loadVideoById (single-video mode), which doesn't auto-advance.
// playback: { loop?: bool } — if loop, replay from start when video ends.
function playSavedVideo(slot, videoId, playback) {
  playback = playback || {};
  window._adDiag = 'yt-vid';
  return ensureVideoPlayer().then(function() {
    if (!_ytPlayer || !slot || !videoId) return;
    // Encode loop in cdKey so onStateChange can detect it
    var cdKey = (playback.loop ? 'savedLoop:' : 'saved:') + videoId;
    var slotKey = (slot.id || 'slot') + '|' + cdKey;
    if (_videoCurrentSlotId === slotKey && _currentVideoIdx === cdKey) return;
    _videoCurrentSlotId = slotKey;

    _positionVideoHostOver(slot);
    if (_videoResizeObserver) { try { _videoResizeObserver.disconnect(); } catch(e){} _videoResizeObserver = null; }
    if (window.ResizeObserver) {
      _videoResizeObserver = new ResizeObserver(function() { _positionVideoHostOver(slot); });
      try { _videoResizeObserver.observe(slot); } catch(e){}
    }
    if (_videoScrollHandler) { window.removeEventListener('scroll', _videoScrollHandler, true); }
    _videoScrollHandler = function() { _positionVideoHostOver(slot); };
    window.addEventListener('scroll', _videoScrollHandler, true);

    _currentVideoIdx = cdKey;
    _currentVideoLang = null;
    window._expectedVideoId = videoId;
    window._loopVideoId = playback.loop ? videoId : null;

    try {
      _ytPlayer.mute();
      _ytPlayer.loadVideoById({ videoId: videoId, suggestedQuality: 'default' });
      setTimeout(function() {
        try {
          if (_ytPlayer && _ytPlayer.playVideo && _currentVideoIdx === cdKey) {
            _ytPlayer.playVideo();
          }
        } catch(e) {}
      }, 400);
    } catch(e) {
      console.warn('[VIDEO] saved play failed:', e);
      _hideDestinationVideoOverlay();
    }
  });
}

// Start the 5-minute scheduler. First attempt ~20s after gate load, then every 5 min.
function startDestinationVideoScheduler() {
  if (_destVideoInterval) {
    console.log('[AC-VIDEO] scheduler already running');
    return;
  }
  console.log('[AC-VIDEO] starting scheduler');
  // Retry loop for first play — attempt every 3 seconds for 30 seconds
  // so we don't miss it when airline/destination fields haven't populated
  // yet on the first tick. Stops as soon as one successfully plays.
  var _initAttempts = 0;
  var _initRetry = setInterval(function() {
    _initAttempts++;
    var ok = tryPlayDestinationVideo();
    console.log('[AC-VIDEO] init attempt', _initAttempts, 'result:', ok);
    if (ok || _initAttempts >= 10) {
      clearInterval(_initRetry);
    }
  }, 3000);
  _destVideoInterval = setInterval(function() {
    tryPlayDestinationVideo();
  }, 60 * 1000);  // check every minute; the 5-min cooldown gates actual playback
}

function stopDestinationVideoScheduler() {
  if (_destVideoInterval) { clearInterval(_destVideoInterval); _destVideoInterval = null; }
  _hideDestinationVideoOverlay();
}

// Position the iframe overlay to cover the given DOM element's rect.
// Keeps the iframe parented to its permanent host; just moves the host.
function _positionVideoHostOver(slot) {
  var host = document.getElementById('acVideoHost');
  if (!host) return;
  var liveSlot = document.getElementById('gatePhotoBg') || slot;
  if (!liveSlot) return;
  var r = liveSlot.getBoundingClientRect();
  if (r.width === 0 || r.height === 0) return; // detached or hidden
  host.style.left = Math.round(r.left) + 'px';
  host.style.top = Math.round(r.top) + 'px';
  host.style.width = Math.round(r.width) + 'px';
  host.style.height = Math.round(r.height) + 'px';
  host.style.zIndex = '5';
  host.style.pointerEvents = 'none';
  host.style.visibility = 'visible';
}

function _parkVideoHost() {
  var host = document.getElementById('acVideoHost');
  if (!host) return;
  host.style.left = '-99999px';
  host.style.top = '-99999px';
  host.style.visibility = 'hidden';
}

var _videoResizeObserver = null;
var _videoScrollHandler = null;
var _videoCurrentSlotId = null;

// Play a YouTube PLAYLIST. Cues the playlist into the player which then
// auto-advances through videos. We track playlistId as the cdKey so we
// don't re-cue the same playlist while it's already playing.
function playYouTubePlaylist(slot, playlistId) {
  return ensureVideoPlayer().then(function() {
    if (!_ytPlayer || !slot || !playlistId) return;
    var cdKey = 'playlist:' + playlistId;
    var slotKey = (slot.id || 'slot') + '|' + cdKey;
    if (_videoCurrentSlotId === slotKey && _currentVideoIdx === cdKey) return;
    _videoCurrentSlotId = slotKey;

    _positionVideoHostOver(slot);
    if (_videoResizeObserver) { try { _videoResizeObserver.disconnect(); } catch(e){} _videoResizeObserver = null; }
    if (window.ResizeObserver) {
      _videoResizeObserver = new ResizeObserver(function() { _positionVideoHostOver(slot); });
      try { _videoResizeObserver.observe(slot); } catch(e){}
    }
    if (_videoScrollHandler) { window.removeEventListener('scroll', _videoScrollHandler, true); }
    _videoScrollHandler = function() { _positionVideoHostOver(slot); };
    window.addEventListener('scroll', _videoScrollHandler, true);

    _currentVideoIdx = cdKey;
    _currentVideoLang = null;
    window._expectedVideoId = null;

    try {
      _ytPlayer.mute();
      // loadPlaylist starts playback immediately; index 0 = start at first
      // video. The player will auto-advance through the playlist.
      _ytPlayer.loadPlaylist({
        list: playlistId,
        listType: 'playlist',
        index: 0,
        suggestedQuality: 'default'
      });
      setTimeout(function() {
        try {
          if (_ytPlayer && _ytPlayer.playVideo && _currentVideoIdx === cdKey) {
            _ytPlayer.playVideo();
          }
        } catch(e) {}
      }, 600);
    } catch(e) {
      console.warn('[VIDEO] playlist play failed:', e);
      _hideDestinationVideoOverlay();
    }
  });
}

// Play an UPLOADED video file (MP4/WebM from R2). Uses a native <video>
// element instead of the YouTube iframe. The element is positioned over
// the slot the same way the YT iframe is.
// playback: { loop?: bool } — if loop, native <video> will replay automatically.
// ── Branded FRAME behind library media (Nick: uploaded ads must sit on the
// dots-world panel — the light brushed base + grey globe + accent handles —
// like the aircraft-info background, not on their own baked backgrounds or
// black). One fixed layer just under the media element; the media renders
// object-fit:contain with a transparent back so the frame shows through
// wherever the ad doesn't reach.
var _mediaFrameEl = null;
function _ensureMediaFrame() {
  if (_mediaFrameEl) return _mediaFrameEl;
  _mediaFrameEl = document.createElement('div');
  _mediaFrameEl.id = 'fidsMediaFrame';
  _mediaFrameEl.style.position = 'fixed';
  // z 5: the gate welcome panel paints its background at z-index 5 — a frame
  // at 4 sat UNDER it (Nick's flat-red bands). Equal z + appended to <body>
  // (later in DOM) puts the frame above the panel, and the media at 6 above
  // the frame.
  _mediaFrameEl.style.zIndex = '5';
  _mediaFrameEl.style.pointerEvents = 'none';
  _mediaFrameEl.style.overflow = 'hidden';
  _mediaFrameEl.style.display = 'none';
  document.body.appendChild(_mediaFrameEl);
  return _mediaFrameEl;
}
function _positionMediaFrame(r, blurUrl) {
  var f = _ensureMediaFrame();
  var _bk = String(blurUrl || '') + '|' + (typeof FIDS_BUILD_TAG !== 'undefined' ? FIDS_BUILD_TAG : '');
  if (f._blurKey !== _bk) {
    f._blurKey = _bk;
    f.innerHTML = ((typeof _adBackdropHtml === 'function') ? _adBackdropHtml(_bk) : '')
      // Tech border around the media box (frame spans the same rect the
      // media is positioned in, so the helper's inset lines up with it).
      + ((typeof _adTechFrameHtml === 'function') ? _adTechFrameHtml() : '');
  }
  // The frame lives on <body>, outside .g8-wrap — pull the airline accent
  // across so the handles keep the airline's colour.
  try {
    var _gw = document.querySelector('.g8-wrap');
    var _acc = _gw ? getComputedStyle(_gw).getPropertyValue('--airline-accent') : '';
    if (_acc) f.style.setProperty('--airline-accent', _acc.trim());
  } catch (e) {}
  f.style.left = Math.round(r.left) + 'px';
  f.style.top = Math.round(r.top) + 'px';
  f.style.width = Math.round(r.width) + 'px';
  f.style.height = Math.round(r.height) + 'px';
  f.style.display = 'block';
}
function _hideMediaFrame() { if (_mediaFrameEl) _mediaFrameEl.style.display = 'none'; }

/* Tech-frame fitter: contain-fit media draws smaller than its element box —
   shrink each .ad-tech-frame to the media's ACTUAL drawn rectangle so the
   frame hugs the ad itself (Nick), whatever the creative's aspect ratio. */
(function () {
  // Frozen frame rects, keyed by creative + panel size. Module scope on
  // purpose: a slide re-render replaces BOTH the frame and its parent,
  // so anything stored on those elements is lost and the frame re-places
  // itself a pixel off — the twitch a 3-minute recording caught twice.
  var _GEOM_CACHE = {};
  var _PENDING = {};
  function _drawnRect(m) {
    var b = m.getBoundingClientRect();
    if (!b.width || !b.height) return null;
    // cover/fill media (v22561: the ad goes against the border) paints the
    // whole element box — the frame hugs the box itself. The contain math
    // below only applies when the media letterboxes.
    var _fit = '';
    var _cs = null;
    try { _cs = getComputedStyle(m); _fit = (_cs.objectFit || '').trim(); } catch (e) {}
    if (_fit === 'cover' || _fit === 'fill') {
      return { left: b.left, top: b.top, width: b.width, height: b.height };
    }
    var mw = m.videoWidth || m.naturalWidth, mh = m.videoHeight || m.naturalHeight;
    if (!mw || !mh) return null;
    // object-fit paints inside the CONTENT box — when the confine pass has
    // padded the media (g8-ad-inset below), the drawn art lives inside the
    // padding, so the box math must use the content box.
    var _pl = _cs ? (parseFloat(_cs.paddingLeft) || 0) : 0;
    var _pr = _cs ? (parseFloat(_cs.paddingRight) || 0) : 0;
    var _pt = _cs ? (parseFloat(_cs.paddingTop) || 0) : 0;
    var _pb = _cs ? (parseFloat(_cs.paddingBottom) || 0) : 0;
    var bl = b.left + _pl, bt = b.top + _pt;
    var bw = Math.max(1, b.width - _pl - _pr), bh = Math.max(1, b.height - _pt - _pb);
    var ar = mw / mh, br = bw / bh, w, h;
    if (ar >= br) { w = bw; h = bw / ar; } else { h = bh; w = bh * ar; }
    return { left: bl + (bw - w) / 2, top: bt + (bh - h) / 2, width: w, height: h };
  }
  function _tick() {
    var frames = document.querySelectorAll('.ad-tech-frame');
    for (var i = 0; i < frames.length; i++) {
      var f = frames[i];
      var host = f.parentElement;
      if (!host) continue;
      var m = host.querySelector('img.ad-tech-media, video.ad-tech-media');
      if (!m && typeof _libImgEl !== 'undefined' && _libImgEl && _libImgEl.style.display !== 'none') m = _libImgEl;
      if (!m && typeof _nativeVideoEl !== 'undefined' && _nativeVideoEl && _nativeVideoEl.style.display !== 'none') m = _nativeVideoEl;
      if (!m) continue;
      var r = _drawnRect(m);
      if (!r) continue;
      var hb = host.getBoundingClientRect();
      // ONE frame per ad. Full-bleed ad: the frame sits ON the ad ('it can
      // go over it, it's fine'). Smaller ad: the frame is inflated so its
      // band sits OUTSIDE the ad — the creative is confined within it.
      // v22595: EXACTLY the v22589 behavior Nick approved ('almost there')
      // — the v22592 clamp and v22593 auto-shrink both moved the border
      // between builds and are gone.
      var fullW = r.width >= hb.width - 8, fullH = r.height >= hb.height - 8;
      var padX = 0, padY = 0;
      if (!(fullW && fullH)) {
        // Clear the WHOLE double-line motif past the ad edge (the inner
        // line sat on the creative — 'you can still see the ad outside
        // borders'). Solved from the art's line geometry: inner-line inner
        // edge at 2.8%/4.3% of the frame box.
        padX = Math.max(10, Math.round(r.width * 0.030));
        padY = Math.max(10, Math.round(r.height * 0.047));
      }
      try { if (m.classList.contains('g8-ad-inset')) { m.classList.remove('g8-ad-inset'); delete f.dataset.geom; continue; } } catch (e) {}
      // FREEZE (Nick: 'make sure the frames don't move'): once placed,
      // ignore sub-2px re-measures — rounding and image settle were able
      // to nudge the frame between ticks.
      var _gx = Math.round(r.left - hb.left - padX), _gy = Math.round(r.top - hb.top - padY);
      var _gw = Math.round(r.width + 2 * padX), _gh = Math.round(r.height + 2 * padY);
      // ONE RECT PER CREATIVE, EVER. Recordings showed the frame landing
      // on up to four different rects for a single ad: the fitter was
      // measuring while the image was still decoding and while the panel
      // was still settling, so each early pass produced a different
      // answer and the frame visibly hopped. Three gates now stand
      // between a measurement and the screen:
      //   1. the media must be fully decoded before it counts at all
      //   2. the key buckets the panel size, so sub-pixel host jitter
      //      cannot mint a new entry for the same ad
      //   3. a rect must repeat on two consecutive passes to be trusted
      // Once committed it is reused verbatim for the life of the page.
      var _ready = (m.tagName === 'VIDEO') ? (m.readyState >= 2) : (m.complete && m.naturalWidth > 0);
      if (!_ready) continue;
      // Key off the CAROUSEL, not the host. The host is the slide wrapper
      // and it animates in, so bucketing its box minted a fresh cache
      // entry at each stage of the transition and every entry confirmed
      // a slightly different rect — which is how two creatives still
      // hopped after the first fix. The carousel does not animate.
      var _mkey = '';
      try {
        var _cz = document.getElementById('gateAdCarousel');
        var _cr = _cz ? _cz.getBoundingClientRect() : hb;
        _mkey = String(m.currentSrc || m.src || '')
          + '|' + (Math.round(_cr.width / 20) * 20) + 'x' + (Math.round(_cr.height / 20) * 20);
      } catch (e) {}
      if (!_mkey) continue;
      var _apply = function (str) {
        var z = str.split(',');
        f.dataset.geom = str;
        f.style.left = z[0] + 'px'; f.style.top = z[1] + 'px';
        f.style.width = z[2] + 'px'; f.style.height = z[3] + 'px';
        f.style.right = 'auto'; f.style.bottom = 'auto';
        f.style.visibility = 'visible';
      };
      if (_GEOM_CACHE[_mkey]) { _apply(_GEOM_CACHE[_mkey]); continue; }
      var _pend = _PENDING[_mkey];
      if (!_pend || Math.abs(_pend[0] - _gx) > 2 || Math.abs(_pend[1] - _gy) > 2
          || Math.abs(_pend[2] - _gw) > 2 || Math.abs(_pend[3] - _gh) > 2) {
        _PENDING[_mkey] = [_gx, _gy, _gw, _gh];
        // v22852 (Nick: 'the timing seems off it appears after the add') —
        // show the frame on the FIRST valid measure instead of holding it
        // hidden through the two-pass confirmation. The rect is not
        // committed yet: if the confirmed rect lands elsewhere it re-applies
        // once, but the frame arrives WITH the ad, not a beat later.
        _apply(_gx + ',' + _gy + ',' + _gw + ',' + _gh);
        continue;                      // unconfirmed — visible, not frozen
      }
      _GEOM_CACHE[_mkey] = _gx + ',' + _gy + ',' + _gw + ',' + _gh;
      _apply(_GEOM_CACHE[_mkey]);
    }
  }
  setInterval(_tick, 300);   // v22852: half the first-paint latency of 600ms
})();

var _nativeVideoEl = null;
function playUploadedVideo(slot, videoUrl, playback) {
  playback = playback || {};
  if (!slot || !videoUrl) return;
  window._adDiag = 'lib-vid';
  var cdKey = 'upload:' + videoUrl;
  var slotKey = (slot.id || 'slot') + '|' + cdKey;
  if (_videoCurrentSlotId === slotKey && _currentVideoIdx === cdKey) return;
  _videoCurrentSlotId = slotKey;

  // Hide YouTube iframe (if it was running) by parking its host off-screen
  try { _parkVideoHost(); } catch (e) {}
  if (_ytPlayer) { try { _ytPlayer.stopVideo(); } catch(e) {} }

  // Lazy-create the native video element
  if (!_nativeVideoEl) {
    _nativeVideoEl = document.createElement('video');
    _nativeVideoEl.id = 'fidsNativeVideo';
    _nativeVideoEl.muted = true;
    _nativeVideoEl.autoplay = true;
    _nativeVideoEl.playsInline = true;
    _nativeVideoEl.controls = false;
    _nativeVideoEl.style.position = 'fixed';
    _nativeVideoEl.style.objectFit = 'contain';   /* whole ad visible; the branded frame fills the rest */
    _nativeVideoEl.style.zIndex = '6';
    _nativeVideoEl.style.pointerEvents = 'none';
    _nativeVideoEl.style.background = 'transparent';
    _nativeVideoEl.style.filter = 'drop-shadow(0 10px 30px rgba(10,20,40,0.28))';
    _nativeVideoEl.addEventListener('ended', function() {
      // If loop is set, the native element handles replay itself via .loop
      // attribute and 'ended' shouldn't fire. This handler only runs on
      // actual final end (no loop).
      window._lastVideoEndedAt = Date.now();
      _currentVideoIdx = null;
      _currentVideoLang = null;
      _videoCurrentSlotId = null;
      _hideDestinationVideoOverlay();
      _hideNativeVideo();
    });
    _nativeVideoEl.addEventListener('error', function() {
      console.warn('[VIDEO] native video error');
      _hideDestinationVideoOverlay();
      _hideNativeVideo();
    });
    document.body.appendChild(_nativeVideoEl);
  }
  // Apply loop setting (works whether element is new or being reused)
  _nativeVideoEl.loop = !!playback.loop;

  function _positionNative() {
    if (!_nativeVideoEl) return;
    // Anchor to the measured VISIBLE panel region (the raw carousel /
    // gatePhotoBg boxes can run past the viewport and under the columns).
    var _vvr = (typeof _adVisibleRect === 'function') ? _adVisibleRect() : null;
    var liveSlot = document.getElementById('gatePhotoBg') || slot;
    if (!liveSlot && !_vvr) return;
    if (_nativeVideoEl.style.display === 'none') return;
    var r = _vvr || liveSlot.getBoundingClientRect();
    if (r.width === 0 || r.height === 0) return; // detached element
    // Full width, tiny vertical breathing room (Nick: 'entire width, stretch
    // a bit up not much').
    var _nvIy = Math.round(r.height * 0.0125);
    _nativeVideoEl.style.left = Math.round(r.left) + 'px';
    _nativeVideoEl.style.top = Math.round(r.top + _nvIy) + 'px';
    _nativeVideoEl.style.width = Math.round(r.width) + 'px';
    _nativeVideoEl.style.height = Math.round(r.height - 2 * _nvIy) + 'px';
    _nativeVideoEl.style.display = 'block';
    try { _positionMediaFrame(r, ''); } catch (e) {}
  }
  _positionNative();
  if (_videoResizeObserver) { try { _videoResizeObserver.disconnect(); } catch(e){} _videoResizeObserver = null; }
  if (window.ResizeObserver) {
    _videoResizeObserver = new ResizeObserver(_positionNative);
    try { _videoResizeObserver.observe(slot); } catch(e){}
  }
  if (_videoScrollHandler) { window.removeEventListener('scroll', _videoScrollHandler, true); }
  _videoScrollHandler = _positionNative;
  window.addEventListener('scroll', _videoScrollHandler, true);

  _currentVideoIdx = cdKey;
  _currentVideoLang = null;
  window._expectedVideoId = null;

  try {
    _nativeVideoEl.src = videoUrl;
    _nativeVideoEl.load();
    var playP = _nativeVideoEl.play();
    if (playP && typeof playP.catch === 'function') {
      playP.catch(function(e) {
        console.warn('[VIDEO] native autoplay blocked:', e.message);
      });
    }
  } catch (e) {
    console.warn('[VIDEO] native play failed:', e);
    _hideDestinationVideoOverlay();
    _hideNativeVideo();
  }
}

function _hideNativeVideo() {
  try { _hideMediaFrame(); } catch (e) {}
  if (_nativeVideoEl) {
    try { _nativeVideoEl.pause(); _nativeVideoEl.removeAttribute('src'); _nativeVideoEl.load(); } catch (e) {}
    _nativeVideoEl.style.display = 'none';
  }
  // Disconnect observers so map zooms/layout shifts don't re-show element
  if (_videoResizeObserver) { try { _videoResizeObserver.disconnect(); } catch(e){} _videoResizeObserver = null; }
  if (_videoScrollHandler) {
    window.removeEventListener('scroll', _videoScrollHandler, true);
    _videoScrollHandler = null;
  }
}

// Display a library IMAGE in the main gate area (full-bleed over the slot).
// Uses a shared <img> element positioned the same way the YT iframe is.
// Honors item.playback.duration:
//   '5s' | '10s' | '15s' | '30s' | '60s' — auto-hides after that long
//   'indefinite' — stays until something else replaces it (no auto-hide)
var _libImgEl = null;
var _libImgTimeout = null;
function playLibraryImage(slot, item) {
  if (!slot || !item || !item.url) return;
  window._adDiag = 'lib-img';
  var cdKey = 'image:' + item.id;
  var slotKey = (slot.id || 'slot') + '|' + cdKey;
  if (_videoCurrentSlotId === slotKey && _currentVideoIdx === cdKey) return;
  _videoCurrentSlotId = slotKey;

  // Stop any existing playback (YT or native video) before showing image
  try { _parkVideoHost(); } catch (e) {}
  if (_ytPlayer) { try { _ytPlayer.stopVideo(); } catch (e) {} }
  try { _hideNativeVideo(); } catch (e) {}
  if (_libImgTimeout) { clearTimeout(_libImgTimeout); _libImgTimeout = null; }

  // Lazy-create the image element
  if (!_libImgEl) {
    _libImgEl = document.createElement('img');
    _libImgEl.id = 'fidsLibraryImage';
    _libImgEl.style.position = 'fixed';
    _libImgEl.style.objectFit = 'contain';   /* whole ad visible; the branded frame fills the rest */
    _libImgEl.style.zIndex = '6';
    _libImgEl.style.pointerEvents = 'none';
    _libImgEl.style.background = 'transparent';
    _libImgEl.style.filter = 'drop-shadow(0 10px 30px rgba(10,20,40,0.28))';
    _libImgEl.addEventListener('error', function() {
      console.warn('[IMAGE] failed to load', item.url);
      _hideDestinationVideoOverlay();
      _hideLibraryImage();
    });
    document.body.appendChild(_libImgEl);
  }

  function _positionImg() {
    if (!_libImgEl) return;
    // Same visible-region anchoring as _positionNative.
    var _vir = (typeof _adVisibleRect === 'function') ? _adVisibleRect() : null;
    var liveSlot = document.getElementById('gatePhotoBg') || slot;
    if (!liveSlot && !_vir) return;
    if (_libImgEl.style.display === 'none') return;
    var r = _vir || liveSlot.getBoundingClientRect();
    if (r.width === 0 || r.height === 0) return;
    // Full width, tiny vertical breathing room (Nick: 'entire width, stretch
    // a bit up not much').
    var _liIy = Math.round(r.height * 0.0125);
    _libImgEl.style.left = Math.round(r.left) + 'px';
    _libImgEl.style.top = Math.round(r.top + _liIy) + 'px';
    _libImgEl.style.width = Math.round(r.width) + 'px';
    _libImgEl.style.height = Math.round(r.height - 2 * _liIy) + 'px';
    _libImgEl.style.display = 'block';
    try { _positionMediaFrame(r, item.url); } catch (e) {}
  }
  _libImgEl.src = item.url;
  _positionImg();
  if (_videoResizeObserver) { try { _videoResizeObserver.disconnect(); } catch(e){} _videoResizeObserver = null; }
  if (window.ResizeObserver) {
    _videoResizeObserver = new ResizeObserver(_positionImg);
    try { _videoResizeObserver.observe(slot); } catch(e){}
  }
  if (_videoScrollHandler) { window.removeEventListener('scroll', _videoScrollHandler, true); }
  _videoScrollHandler = _positionImg;
  window.addEventListener('scroll', _videoScrollHandler, true);

  _currentVideoIdx = cdKey;
  _currentVideoLang = null;
  window._expectedVideoId = null;

  // Schedule auto-hide based on duration (unless indefinite).
  // Defaults to 10s ONLY when no playback object set at all. Once Edit
  // has saved a setting, that value should persist.
  var pb = item.playback || {};
  var durStr = (typeof pb.duration === 'string' && pb.duration) ? pb.duration : '10s';
  console.log('[IMAGE] item', item.id, 'playback:', JSON.stringify(pb), '→ duration:', durStr);
  if (durStr !== 'indefinite') {
    var ms = 10000;
    var m = String(durStr).match(/^(\d+)s$/);
    if (m) ms = parseInt(m[1], 10) * 1000;
    _libImgTimeout = setTimeout(function() {
      console.log('[IMAGE] duration', durStr, 'elapsed — hiding');
      window._lastVideoEndedAt = Date.now();
      _currentVideoIdx = null;
      _videoCurrentSlotId = null;
      _hideDestinationVideoOverlay();
    }, ms);
  } else {
    console.log('[IMAGE] indefinite — staying until gate change');
  }
}

function _hideLibraryImage() {
  try { _hideMediaFrame(); } catch (e) {}
  if (_libImgTimeout) { clearTimeout(_libImgTimeout); _libImgTimeout = null; }
  if (_libImgEl) {
    _libImgEl.style.display = 'none';
    _libImgEl.removeAttribute('src');
  }
  // Disconnect observers so layout shifts don't re-show the hidden image
  if (_videoResizeObserver) { try { _videoResizeObserver.disconnect(); } catch(e){} _videoResizeObserver = null; }
  if (_videoScrollHandler) {
    window.removeEventListener('scroll', _videoScrollHandler, true);
    _videoScrollHandler = null;
  }
}

// Play a specific video. Takes a match object {lang, idx, videoId}.
// The iframe stays in its permanent host; we reposition the host on top
// of the slot's on-screen rect.
function playDestinationVideo(slot, match) {
  return ensureVideoPlayer().then(function() {
    if (!_ytPlayer || !slot || !match) return;
    var cdKey = match.lang + ':' + match.idx;
    // Debounce: if this exact (slot, cdKey) is already active, skip.
    var slotKey = (slot.id || 'slot') + '|' + cdKey;
    if (_videoCurrentSlotId === slotKey && _currentVideoIdx === cdKey) return;
    _videoCurrentSlotId = slotKey;

    _positionVideoHostOver(slot);
    if (_videoResizeObserver) { try { _videoResizeObserver.disconnect(); } catch(e){} _videoResizeObserver = null; }
    if (window.ResizeObserver) {
      _videoResizeObserver = new ResizeObserver(function() { _positionVideoHostOver(slot); });
      try { _videoResizeObserver.observe(slot); } catch(e){}
    }
    if (_videoScrollHandler) window.removeEventListener('scroll', _videoScrollHandler, true);
    _videoScrollHandler = function() { _positionVideoHostOver(slot); };
    window.addEventListener('scroll', _videoScrollHandler, true);
    window.addEventListener('resize', _videoScrollHandler);

    _currentVideoIdx = cdKey;
    _currentVideoLang = match.lang;
    if (!match.videoId) {
      console.warn('[AC-VIDEO] no videoId in match — abort');
      _hideDestinationVideoOverlay();
      return;
    }

    // Play via loadPlaylist({list, index}) — bypasses error 150 since
    // the playlist itself is whitelisted for embedding even if individual
    // videos aren't. The match.idx is the index within the harvested
    // playlist for match.lang, and match.videoId came from that same
    // playlist, so the index is always valid.
    var playlistId = AC_VIDEO_PLAYLISTS[match.lang];
    var idx = match.idx;
    if (typeof idx !== 'number' || idx < 0) {
      console.warn('[AC-VIDEO] invalid idx', idx, '— abort');
      _hideDestinationVideoOverlay();
      return;
    }

    console.log('[AC-VIDEO] loading playlist', playlistId, 'index', idx, 'videoId', match.videoId, 'lang', match.lang);
    // Mark as played NOW (not at end). This way, even if playback crashes,
    // is interrupted, or stops mid-way, the next pick won't choose the same
    // video. The cooldown set keeps a memory of recent picks.
    if (cdKey) markVideoPlayed(cdKey);
    // Record expected video ID so onStateChange can detect playlist auto-advance
    window._expectedVideoId = match.videoId || null;
    try {
      _ytPlayer.mute();
      // loadPlaylist plays via the playlist's whitelisted embed context
      // — bypasses error 150 on individual videos.
      _ytPlayer.loadPlaylist({ list: playlistId, listType: 'playlist', index: idx, suggestedQuality: 'default' });
      // Belt-and-suspenders: explicit playVideo() after a short delay.
      setTimeout(function() {
        try {
          if (_ytPlayer && _ytPlayer.playVideo && _currentVideoIdx === cdKey) {
            _ytPlayer.playVideo();
          }
        } catch(e) {}
      }, 400);
    } catch(e) { console.warn('[AC-VIDEO] play failed:', e); _hideDestinationVideoOverlay(); }
    // Update "last played" so next attempt alternates language.
    try { localStorage.setItem('fids_last_video_lang', match.lang); } catch(e) {}
    _nextVideoLang = (match.lang === 'fr') ? 'en' : 'fr';
  });
}

// Stop the video and park the host off-screen. Safe to call repeatedly —
// idempotent when no video is active.
function stopDestinationVideo() {
  if (!_ytPlayer) return;
  // Only act if we were actually mounted — avoid postMessage storms.
  if (_videoCurrentSlotId === null) return;
  try {
    // Only call stopVideo if the player function actually exists — during
    // destruction / reinit the YT.Player methods can be missing even though
    // the outer object is truthy.
    if (typeof _ytPlayer.stopVideo === 'function') _ytPlayer.stopVideo();
  } catch(e) {}
  if (_currentVideoIdx !== null) markVideoPlayed(_currentVideoIdx);
  _currentVideoIdx = null;
  _videoCurrentSlotId = null;
  if (_videoResizeObserver) { try { _videoResizeObserver.disconnect(); } catch(e){} _videoResizeObserver = null; }
  if (_videoScrollHandler) {
    window.removeEventListener('scroll', _videoScrollHandler, true);
    window.removeEventListener('resize', _videoScrollHandler);
    _videoScrollHandler = null;
  }
  _parkVideoHost();
}

