// Brand Corner API cache
var ACCOR_BRAND_CACHE = {};

function fetchAccorBrand(brandCode) {
  if (!brandCode) return;
  var lc = brandCode.toLowerCase();
  if (ACCOR_BRAND_CACHE[lc]) return;
  ACCOR_BRAND_CACHE[lc] = { loading: true };
  var url = 'https://fids-proxy.n-leblanc1984.workers.dev/accor/ecom/v1/brand-corner/brand-details?language=en&brandCode=' + lc;
  fetch(url).then(function(r){ return r.ok ? r.json() : null; })
    .then(function(data) {
      if (data && data.heading) {
        ACCOR_BRAND_CACHE[lc] = {
          title: data.heading.title || '',
          kicker: data.heading.kicker || '',
          tagline: data.heading.description || '',
          subtitle: (data.highlight && data.highlight.subTitle) || ''
        };
        console.log('[ACCOR-BRAND]', lc, '=', ACCOR_BRAND_CACHE[lc].title, '(' + ACCOR_BRAND_CACHE[lc].kicker + ')');
      }
    })
    .catch(function(){ ACCOR_BRAND_CACHE[lc] = { failed: true }; });
}

// Strip garbled prefixes from Accor hotel names
function cleanAccorName(name) {
  if (!name) return 'Accor Hotel';
  // Remove known CRS/system prefixes (may be chained: "FX - ROTW Novotel...")
  var prev = '';
  while (prev !== name) {
    prev = name;
    name = name.replace(/^(Core|GDS|FX|ROTW|HTNG|MGT|OPS|REV|TST|DEV|STG)\s*[-–]?\s*/i, '');
    // Strip "Novo" only when NOT followed by "tel" (preserve "Novotel")
    name = name.replace(/^Novo(?!tel)\s*[-–]?\s*/i, '');
  }
  name = name.replace(/^-\s*/, '');
  name = name.replace(/\s{2,}/g, ' ').trim();
  // Fix abbreviations
  name = name.replace(/\bCntr\b/g, 'Centre');
  return name || 'Accor Hotel';
}

// Ensure hotel name includes brand name
function ensureBrandInName(name, brandCode) {
  var brandName = ACCOR_BRAND_NAMES[brandCode] || '';
  if (!brandName || !name) return name;
  // If the cleaned name doesn't contain the brand name, prepend it
  if (name.toLowerCase().indexOf(brandName.toLowerCase()) === -1) {
    return brandName + ' ' + name;
  }
  return name;
}

function fetchAccorHotels(destIata) {
  if (!destIata) return;
  // Language for THIS fetch (the current board rotation language).
  var _listLang = _accorLangNow();
  var _ck = destIata + '|' + _listLang;
  var cached = ACCOR_HOTEL_CACHE[_ck];
  if (cached && (Date.now() - cached.ts < ACCOR_CACHE_TTL)) return;
  if (window['_accorFetching_' + _ck]) return;

  // If COORDS missing, geocode first then fetch
  if (!COORDS[destIata]) {
    var cityName = CITY[destIata] || (AP[destIata]||{}).city || destIata;
    fetch('https://geocoding-api.open-meteo.com/v1/search?name=' + encodeURIComponent(cityName) + '&count=1')
      .then(function(r){ return r.ok ? r.json() : null; })
      .then(function(gd){
        if (gd && gd.results && gd.results.length) {
          COORDS[destIata] = [gd.results[0].latitude, gd.results[0].longitude];
          console.log('[ACCOR] Geocoded', destIata, 'to', COORDS[destIata]);
          fetchAccorHotels(destIata); // Retry now that we have coords
        }
      })
      .catch(function(){ console.warn('[ACCOR] Geocoding failed for', destIata); });
    return;
  }

  window['_accorFetching_' + _ck] = true;

  // v218.99.54 — Use DOWNTOWN coordinates (not airport) so results are
  // centered on the city, not the airport. Hotels are then filtered in
  // _processAccorData to within 100km of downtown so we don't show
  // properties that are really closer to a different city.
  var coords;
  if (DOWNTOWN_COORDS[destIata]) {
    coords = [DOWNTOWN_COORDS[destIata].lat, DOWNTOWN_COORDS[destIata].lng];
  } else {
    coords = COORDS[destIata];
  }
  // _listLang computed at the top of the function (the LIST endpoint honors
  // Accept-Language; detail/photos/amenities all come through this call).
  var proxyUrl = 'https://fids-proxy.n-leblanc1984.workers.dev/accor/catalog/v1/hotels?latLng=' + coords[0] + ',' + coords[1]
    + '&radius=110&range=0-15&sort=distance'
    + '&language=' + encodeURIComponent(_listLang);

  console.log('[ACCOR] Fetching hotels near', destIata, '(' + _listLang + ', Accept-Language: ' + _accorAcceptLang(_listLang) + ')');
  fetch(proxyUrl, { headers: { 'Accept-Language': _accorAcceptLang(_listLang) } })
    .then(function(r) {
      if (!r.ok) throw new Error('Proxy HTTP ' + r.status);
      return r.json();
    })
    .then(function(data) { _processAccorData(data, destIata, _listLang); window['_accorFetching_' + _ck] = false; })
    .catch(function(e) {
      console.warn('[ACCOR] Fetch failed:', e.message, '- will retry in 5min');
      ACCOR_HOTEL_CACHE[_ck] = { hotels: [], ts: Date.now() - ACCOR_CACHE_TTL + 300000 };
      window['_accorFetching_' + _ck] = false;
    });
}

