      'mercure':  { propertyName: { weight: 700, italic: false, case: 'none',
                        family: 'var(--font-accor-title)', spacing: '0' } },
      'ibis':     { propertyName: { weight: 700, italic: false, case: 'none',
                        family: 'var(--font-accor-title)', spacing: '0' } },
      'sofitel':  { propertyName: { weight: 700, italic: false, case: 'none',
                        family: 'var(--font-accor-title)', spacing: '0' } },
      'fairmont': { propertyName: { weight: 700, italic: false, case: 'none',
                        family: 'var(--font-accor-title)', spacing: '0' } },
      'raffles':  { propertyName: { weight: 700, italic: false, case: 'none',
                        family: 'var(--font-accor-title)', spacing: '0' } },
      'pullman':  { propertyName: { weight: 700, italic: false, case: 'none',
                        family: 'var(--font-accor-title)', spacing: '0' } }
